VALUES ('doc-04-nist-sp-800-86-p50-6', 'doc-04-nist-sp-800-86', '', 50, 'Various password- cracking utilities may be used to convert a password hash to its clear text equivalent for certain OSs.', 'kb-doc-04-nist-sp-800-86-p50-6', 0, 20, '04-nist-sp-800-86', 'retrieved', 'B81AB4DB7CF143FA9546642928712511A211D7927637F25B86FBB1FDE23FC9C8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
