INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p50-8', 'doc-04-nist-sp-800-86', '', 50, 'The OS maintains a list of scheduled tasks that are to be performed automatically at a certain time (e.g., perform a virus scan every week).', 'kb-doc-04-nist-sp-800-86-p50-8', 0, 25, '04-nist-sp-800-86', 'retrieved', '974424D675B20B1DE9348E3C8159C7F1FC437103C92C36D8BE6949C51BC44674', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
