VALUES ('doc-04-nist-sp-800-86-p50-9', 'doc-04-nist-sp-800-86', '', 50, 'Information that can be gleaned from this include the task name, the program used to perform the task, command line switches and arguments, and the days and times when the task is to be performed.', 'kb-doc-04-nist-sp-800-86-p50-9', 0, 35, '04-nist-sp-800-86', 'retrieved', 'B27AE730F25BE49F5F8FE776A5DA65678396A879E5681F41AD8A3572F44A6CFA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
