VALUES ('doc-04-nist-sp-800-86-p50-11', 'doc-04-nist-sp-800-86', '', 50, 'OS log files contain information about various OS events, and may also hold application- specific event information.', 'kb-doc-04-nist-sp-800-86-p50-11', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A2C2168F38DCE0273D38170A42820A79D9673774B56EECF72F1184BEF18C3E41', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
