VALUES ('doc-04-nist-sp-800-86-p50-12', 'doc-04-nist-sp-800-86', '', 50, 'Depending on the OS, logs may be stored in text files, proprietary- format binary files, or databases.', 'kb-doc-04-nist-sp-800-86-p50-12', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A4A6B7E7579D028C70D50DCF7D326EE1C4FE874B79D976DC0DE2104D17937CA5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
