VALUES ('doc-04-nist-sp-800-86-p50-14', 'doc-04-nist-sp-800-86', '', 50, 'The types of information typically found in OS logs are as follows:  System Events.', 'kb-doc-04-nist-sp-800-86-p50-14', 0, 15, '04-nist-sp-800-86', 'retrieved', '3254C9C87BA3B4FCA6906439819E04633539F0A5E112491A5F83C13F45699FA8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
