VALUES ('doc-04-nist-sp-800-86-p50-15', 'doc-04-nist-sp-800-86', '', 50, 'System events are operational actions performed by OS components, such as shutting down the system or starting a service.', 'kb-doc-04-nist-sp-800-86-p50-15', 0, 19, '04-nist-sp-800-86', 'retrieved', 'CF68054AA14DD08F302C62B3C8E7BB463B72B8BAF2000CF9D96F1ACA3A174285', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
