VALUES ('doc-04-nist-sp-800-86-p50-16', 'doc-04-nist-sp-800-86', '', 50, 'Typically, failed events and the most significant successful events are logged, but many OSs permit system administrators to specify which types of events will be logged.', 'kb-doc-04-nist-sp-800-86-p50-16', 0, 26, '04-nist-sp-800-86', 'retrieved', '64BC71BE6DF18213B21028DFED8F6815B8FC0796D4F29EF67A8C730D3D152FC4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
