VALUES ('doc-04-nist-sp-800-86-p51-5', 'doc-04-nist-sp-800-86', '', 51, 'Some OSs have the ability to store the contents of memory automatically during an error condition to assist in subsequent troubleshooting.', 'kb-doc-04-nist-sp-800-86-p51-5', 0, 21, '04-nist-sp-800-86', 'retrieved', '7B96B9A0521232003270C41D4126642D177ACA3FC51F69EB01076BED36B382A1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
