INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-8', 'doc-04-nist-sp-800-86', '', 51, 'A hibernation file is created to preserve the current state of a system (typically a laptop) by recording memory and open files before shutting off the system.', 'kb-doc-04-nist-sp-800-86-p51-8', 0, 27, '04-nist-sp-800-86', 'retrieved', '1CCCDBD29D4EC6DF1C75659653AC769B278004AE3509684630E6217986BE79AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-11', 'doc-04-nist-sp-800-86', '', 51, 'During the installation of an OS, application, or OS or application updates and upgrades, temporary files are often created.', 'kb-doc-04-nist-sp-800-86-p51-11', 0, 19, '04-nist-sp-800-86', 'retrieved', 'AD61929918F9E7EE50EFB30C91FA1FBC900D92E2C4D5EADFB31830EBEFCA89C1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-12', 'doc-04-nist-sp-800-86', '', 51, 'Although such files are typically deleted at the end of the installation process, this does not always occur.', 'kb-doc-04-nist-sp-800-86-p51-12', 0, 18, '04-nist-sp-800-86', 'retrieved', 'B76F985BBE5100BB111666F04F1B43E8E0340F4D11163F566F99EBE6689F969C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-13', 'doc-04-nist-sp-800-86', '', 51, 'In addition, temporary files are created when many applications are run; again, such files are usually deleted when the application is terminated, but this does not always happen.', 'kb-doc-04-nist-sp-800-86-p51-13', 0, 28, '04-nist-sp-800-86', 'retrieved', 'CAADF6F508DD4697FB688CF3276D606FCFAF1910240D97C9F0CB38B33DB9EB11', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-14', 'doc-04-nist-sp-800-86', '', 51, 'Temporary files could contain copies of other files on the system, application data, or other information.', 'kb-doc-04-nist-sp-800-86-p51-14', 0, 16, '04-nist-sp-800-86', 'retrieved', 'C56BE9EA772D0867D8C8AC5372A6F2FEBC95B448F96C5F888D4C10F2296C42C3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-15', 'doc-04-nist-sp-800-86', '', 51, 'Although filesystems are the primary source of non-volatile data, another source of interest is the BIOS.', 'kb-doc-04-nist-sp-800-86-p51-15', 0, 16, '04-nist-sp-800-86', 'retrieved', '7815D91B0EC320C02738E6CA7CAF840B214D3762C9DFC338B0991768BF10624B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-16', 'doc-04-nist-sp-800-86', '', 51, 'The BIOS contains many types of hardware-related information, such as the attached devices (e.g., CD- ROM drives, hard drives), the types of connections and interrupt request line (IRQ) assignments (e.g., serial, USB, network card), motherboard components (e.g., processor type and speed, cache size, memory information), system security settings, and hot keys.', 'kb-doc-04-nist-sp-800-86-p51-16', 0, 51, '04-nist-sp-800-86', 'retrieved', 'AF4B49799690EE01B26DF800A6086E82B27C7E445FD3638AFFC961F8FB135339', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-17', 'doc-04-nist-sp-800-86', '', 51, 'The BIOS also communicates with RAID drivers and displays the information provided by the drivers.', 'kb-doc-04-nist-sp-800-86-p51-17', 0, 15, '04-nist-sp-800-86', 'retrieved', '4972078DCD23662451A11F42259DAD291C5E216929567F9BF7A829D9787D6B9B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-18', 'doc-04-nist-sp-800-86', '', 51, 'For example, the BIOS views a hardware RAID as a single drive and a software RAID as multiple drives.', 'kb-doc-04-nist-sp-800-86-p51-18', 0, 19, '04-nist-sp-800-86', 'retrieved', '0B7D229FF1DEF2F3F721C8F8788E36869359A67EC090BEA20CA93CCA2B81BF9D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-19', 'doc-04-nist-sp-800-86', '', 51, 'The BIOS typically permits the user to set passwords, which restrict access to the BIOS settings and may prevent the system from booting if the password is not supplied.', 'kb-doc-04-nist-sp-800-86-p51-19', 0, 29, '04-nist-sp-800-86', 'retrieved', '7C405854DCBDE2430FFADDDF5583411F3F0B5F424354D3472EC917688DBD5189', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-23', 'doc-04-nist-sp-800-86', '', 51, 'At any given time, RAM might contain many types of data and information that could be of interest.', 'kb-doc-04-nist-sp-800-86-p51-23', 0, 18, '04-nist-sp-800-86', 'retrieved', '248E3F0380C3CFAF488E5411E45DD4212BFFD151BA9109D1AE5661C2703B21AF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-24', 'doc-04-nist-sp-800-86', '', 51, 'For example, RAM often contains frequently and recently accessed data, such as data files, password hashes, and recent commands.', 'kb-doc-04-nist-sp-800-86-p51-24', 0, 19, '04-nist-sp-800-86', 'retrieved', '39315D7FDC8B11C12D80FD0F1797A0EDB5BA8184408D4042E755785412A4AA7E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-25', 'doc-04-nist-sp-800-86', '', 51, 'In addition, like filesystems, RAM can contain residual data in slack and free space, as follows: ! Slack Space.', 'kb-doc-04-nist-sp-800-86-p51-25', 0, 19, '04-nist-sp-800-86', 'retrieved', 'FDA1C3AE282C1007127F73835736BEE709BF669F1D144A365E67D169F95AD933', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-27', 'doc-04-nist-sp-800-86', '', 51, 'For example, an OS generally manages memory in units known as pages or blocks, and allocates them to requesting applications.', 'kb-doc-04-nist-sp-800-86-p51-27', 0, 20, '04-nist-sp-800-86', 'retrieved', '8A5608F5DB347132B8D8FEFB713899F5BFF7992CB417CADD00F47B27DCBCDED0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-28', 'doc-04-nist-sp-800-86', '', 51, 'Sometimes, although an application might not request an entire unit, it is given one anyway.', 'kb-doc-04-nist-sp-800-86-p51-28', 0, 15, '04-nist-sp-800-86', 'retrieved', '8EDE79CC988A29A172789C236C48D38E233FB5DFA38228291FB66A11833CF094', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-29', 'doc-04-nist-sp-800-86', '', 51, 'Residual data could therefore reside in the unit of memory allocated to an application, although it might not be addressable by the application.', 'kb-doc-04-nist-sp-800-86-p51-29', 0, 23, '04-nist-sp-800-86', 'retrieved', 'D59F0042012CB7774F49B0D3A2D2074A99767B5B431E7613F9A6B21F639358EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-30', 'doc-04-nist-sp-800-86', '', 51, 'For performance and efficiency, some OSs vary the size of the units they allocate, which tends to result in smaller memory slack spaces.', 'kb-doc-04-nist-sp-800-86-p51-30', 0, 23, '04-nist-sp-800-86', 'retrieved', 'DEEF010959571DA5171EADD624E0667814F0471240A9B19429C069862D42F3A7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-33', 'doc-04-nist-sp-800-86', '', 51, 'When they are not allocated, memory pages are often collected into a common pool of available pagesa process often referred to as garbage collection.', 'kb-doc-04-nist-sp-800-86-p51-33', 0, 24, '04-nist-sp-800-86', 'retrieved', '8AA01E390094839319AEF814EE688DB22F56559BFF95744ECBBC0105584E1B38', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-34', 'doc-04-nist-sp-800-86', '', 51, 'It is not uncommon for residual data to reside in these reusable memory pages, which are analogous to unallocated file clusters.', 'kb-doc-04-nist-sp-800-86-p51-34', 0, 21, '04-nist-sp-800-86', 'retrieved', '0F33D7531ADD1ECE7550FA405EB9686D97BFA5978953B4C450E469D383793FB9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p51-35', 'doc-04-nist-sp-800-86', '', 51, 'Some other significant types of volatile data that might exist within an OS are as follows: 5-3', 'kb-doc-04-nist-sp-800-86-p51-35', 0, 17, '04-nist-sp-800-86', 'retrieved', 'D5F65AB6862C718CB3B427EA925E04B517A823907995756138343EEFD667F175', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-1', 'doc-04-nist-sp-800-86', '', 52, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Network Configuration.', 'kb-doc-04-nist-sp-800-86-p52-1', 0, 11, '04-nist-sp-800-86', 'retrieved', 'FA35713FF527BB4182C9AE86D3260F07474323282BF21D6E92BB8C5D1549D9CA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-2', 'doc-04-nist-sp-800-86', '', 52, 'Although many elements of networking, such as network interface card (NIC) drivers and configuration settings, are typically stored in the filesystem, networking is dynamic in nature.', 'kb-doc-04-nist-sp-800-86-p52-2', 0, 26, '04-nist-sp-800-86', 'retrieved', 'FBC9B746715D0C6AB3DAFB0D750BD3FA5425F1991B9AE227A6705BFC37F40756', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-3', 'doc-04-nist-sp-800-86', '', 52, 'For example, many hosts are assigned Internet Protocol (IP) addresses dynamically by another host, meaning that their IP addresses are not part of the stored configuration.', 'kb-doc-04-nist-sp-800-86-p52-3', 0, 26, '04-nist-sp-800-86', 'retrieved', 'C9DAFFD604C14D085B5F381BD90546905D3101EFF4E2E5416974819AC5B9A1AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-4', 'doc-04-nist-sp-800-86', '', 52, 'Many hosts also have multiple network interfaces defined, such as wired, wireless, virtual private network (VPN), and modem; the current network configuration indicates which interfaces are currently in use.', 'kb-doc-04-nist-sp-800-86-p52-4', 0, 29, '04-nist-sp-800-86', 'retrieved', '28E0A80A207252F170D6495A46D28AC6F2CB1E7CAEFF9D0D94147D181CD3AD6B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-5', 'doc-04-nist-sp-800-86', '', 52, 'Users also may be able to alter network interface configurations from the defaults, such as manually changing IP addresses.', 'kb-doc-04-nist-sp-800-86-p52-5', 0, 19, '04-nist-sp-800-86', 'retrieved', '528A97C09ACBB562671BECA4579EE1BC735B9F947E0FBBC75D8892B9BE8281E9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
