INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-6', 'doc-04-nist-sp-800-86', '', 52, 'Accordingly, analysts should use the current network configuration, not the stored configuration, whenever possible.', 'kb-doc-04-nist-sp-800-86-p52-6', 0, 14, '04-nist-sp-800-86', 'retrieved', 'A7977B19E980E2D65C18321193937239CE2CABDF80B60C8A0F82A6D1D02F635F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
