INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-9', 'doc-04-nist-sp-800-86', '', 52, 'Most OSs can provide a list of current incoming and outgoing network connections, and some OSs can list recent connections as well.', 'kb-doc-04-nist-sp-800-86-p52-9', 0, 22, '04-nist-sp-800-86', 'retrieved', 'DD9EAA9316CCC68D8BD031BF1A34A911FB107B6DC5B2F886C9101E03C668EE93', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-10', 'doc-04-nist-sp-800-86', '', 52, 'For incoming connections, the OS typically indicates which resources are being used, such as file shares and printers.', 'kb-doc-04-nist-sp-800-86-p52-10', 0, 18, '04-nist-sp-800-86', 'retrieved', '585409114597D22B76E98604046812C0B44876FB95FFEC71DD7AEB252551B95F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-11', 'doc-04-nist-sp-800-86', '', 52, 'Most OSs can also provide a list of the ports and IP addresses at which the system is listening for connections.', 'kb-doc-04-nist-sp-800-86-p52-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '7CD44F5E98AC3C093A183D7C4DDF9B6185E99B052FF2405236BBBE7CDF6ED44A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
