VALUES ('doc-04-nist-sp-800-86-p52-12', 'doc-04-nist-sp-800-86', '', 52, 'Section 6 provides an in-depth examination of the significance of network connections.', 'kb-doc-04-nist-sp-800-86-p52-12', 0, 12, '04-nist-sp-800-86', 'retrieved', 'D2730D963867142A163F158D1236126CEA219AD6084A26F4F4729FD399E75CB6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
