INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-15', 'doc-04-nist-sp-800-86', '', 52, 'Processes include services offered by the OS and applications run by administrators and users.', 'kb-doc-04-nist-sp-800-86-p52-15', 0, 14, '04-nist-sp-800-86', 'retrieved', '36D3D4065BC4EB12AD0E7DF432F14C322CA8FEDADF36A632629A5492A7E5D064', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-17', 'doc-04-nist-sp-800-86', '', 52, 'This list can be studied to determine the services that are active on the system, such as a Web server, and the programs that individual users are running (e.g., encryption utility, word processor, e-mail client).', 'kb-doc-04-nist-sp-800-86-p52-17', 0, 35, '04-nist-sp-800-86', 'retrieved', '70C4C4CAF9601D799909F30C7B6CFF6D8210A666A4B38E79447B75ED92AB52DD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-18', 'doc-04-nist-sp-800-86', '', 52, 'Process lists may also indicate which command options were used, as described in Section 7.', 'kb-doc-04-nist-sp-800-86-p52-18', 0, 15, '04-nist-sp-800-86', 'retrieved', '6C72B76506CC206AAF6138E6B2E9FCC8A49D5AB05E577E0F6AC1019A31BEC258', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-19', 'doc-04-nist-sp-800-86', '', 52, 'Identifying the running processes is also helpful for identifying programs that should be running but have been disabled or removed, such as antivirus software and firewalls.', 'kb-doc-04-nist-sp-800-86-p52-19', 0, 26, '04-nist-sp-800-86', 'retrieved', '982A7CDACBB5A30F25E6CAE943D84788330ED435A4DF68AD0C6468466470F409', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-21', 'doc-04-nist-sp-800-86', '', 52, 'OSs may maintain a list of open files, which typically includes the user or process that opened each file.', 'kb-doc-04-nist-sp-800-86-p52-21', 0, 19, '04-nist-sp-800-86', 'retrieved', 'D2CFCA109E6E5F8DD1B6CA372844742DCF6F1600AD424917C63F8D4AF2A62221', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-23', 'doc-04-nist-sp-800-86', '', 52, 'OSs typically maintain information about currently logged-in users (and the start time and duration of each session), previous successful and failed logons, privileged usage, and impersonation.65 However, login session information might be available only if the computer has been configured to audit logon attempts.', 'kb-doc-04-nist-sp-800-86-p52-23', 0, 44, '04-nist-sp-800-86', 'retrieved', '76080960D36ABB0B868A7B903126F2E7ACEB09F60B719F1F36A05110D3A7ED27', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-24', 'doc-04-nist-sp-800-86', '', 52, 'Logon records can help to determine a users computer usage habits and confirm whether a user account was active when a given event occurred.', 'kb-doc-04-nist-sp-800-86-p52-24', 0, 24, '04-nist-sp-800-86', 'retrieved', '6F22C9EF895B97407334F9AA0A8343633BDFCF456598A6DB0304D75458A97207', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-26', 'doc-04-nist-sp-800-86', '', 52, 'The OS maintains the current time and stores daylight savings time and time zone information.', 'kb-doc-04-nist-sp-800-86-p52-26', 0, 15, '04-nist-sp-800-86', 'retrieved', '92E127D8902E58F725353EEEEC043040CEF648FDA08F554C205079ACC5ED68AE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-27', 'doc-04-nist-sp-800-86', '', 52, 'This information can be useful when building a timeline of events or correlating events among different systems.', 'kb-doc-04-nist-sp-800-86-p52-27', 0, 17, '04-nist-sp-800-86', 'retrieved', 'D8DA51B84D98EF03C92435D8EF2B7D0879CFEF59999080103CD97AFE403B8F92', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-28', 'doc-04-nist-sp-800-86', '', 52, 'Analysts should be aware that the time presented by the OS might differ from that presented by the BIOS because of OS-specific settings, such as time zone.', 'kb-doc-04-nist-sp-800-86-p52-28', 0, 27, '04-nist-sp-800-86', 'retrieved', '7236245229D59C4F6A8366413718034180922FD2AEA7EBAF5C3DE23D333A532B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-29', 'doc-04-nist-sp-800-86', '', 52, '5.2 Collecting OS Data As described in Section 5.1, OS data exists in both non-volatile and volatile states.', 'kb-doc-04-nist-sp-800-86-p52-29', 0, 18, '04-nist-sp-800-86', 'retrieved', '41A6D84C02609CECBC9296F235192587AF7052909C7CC6F7A361D05E77361645', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-30', 'doc-04-nist-sp-800-86', '', 52, 'Non-volatile OS data such as filesystem data can be collected using the approaches discussed in Section 4 for performing logical backups and bit stream imaging.', 'kb-doc-04-nist-sp-800-86-p52-30', 0, 25, '04-nist-sp-800-86', 'retrieved', '5C32DC909CC87E81C66C5F685E47B725A02B91DD90CCB2074B3A03E558A1D81B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-32', 'doc-04-nist-sp-800-86', '', 52, 'Sections 5.2.1 and 5.2.2 provide recommendations for collecting volatile and non-volatile OS data, respectively.', 'kb-doc-04-nist-sp-800-86-p52-32', 0, 14, '04-nist-sp-800-86', 'retrieved', 'A41BEEE2E591FBBB20F53454D1FB964888A90EF494A30D65F82C1E01430CF504', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-33', 'doc-04-nist-sp-800-86', '', 52, 'Section 5.2.3 discusses technical issues that can impede the collection of data.', 'kb-doc-04-nist-sp-800-86-p52-33', 0, 12, '04-nist-sp-800-86', 'retrieved', '22316D7B4BF617D27ECD1E5BC0432D4075601C73DF1771534317878D4BD432FA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-34', 'doc-04-nist-sp-800-86', '', 52, '65 Impersonation can allow a regular system user to have higher system privileges to accomplish certain tasks.', 'kb-doc-04-nist-sp-800-86-p52-34', 0, 17, '04-nist-sp-800-86', 'retrieved', 'EA28972BC51F4A0D2EE31B1E2E8EF3108B7B81493416070480A6DE5C715704A8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p52-36', 'doc-04-nist-sp-800-86', '', 52, 'Through impersonation, a regular user can be given those permissions to run the application and then be reverted back to the usual privileges.', 'kb-doc-04-nist-sp-800-86-p52-36', 0, 23, '04-nist-sp-800-86', 'retrieved', 'CBFB4D5491FE6C1770ACC31523231EA5CB72C68FDB7549AFE5688FDE7DCD054D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-1', 'doc-04-nist-sp-800-86', '', 53, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 5.2.1 Collecting Volatile OS Data Volatile OS data involving an event can be collected only from a live system that has not been rebooted or shut down since the event occurred.', 'kb-doc-04-nist-sp-800-86-p53-1', 0, 39, '04-nist-sp-800-86', 'retrieved', 'DCB5FEA48053FDFB3402FACB7D7517DB5B9DF32C1B463780D82FDC5F33C71DC8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-2', 'doc-04-nist-sp-800-86', '', 53, 'Every action performed on the system, whether initiated by a person or by the OS itself, will almost certainly alter the volatile OS data in some way.', 'kb-doc-04-nist-sp-800-86-p53-2', 0, 27, '04-nist-sp-800-86', 'retrieved', 'D26A0C0AE78199F58BFD028BE430701CC80805A3FDF2B4B8D4D7B80E177E6F81', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-3', 'doc-04-nist-sp-800-86', '', 53, 'Therefore, analysts should decide as quickly as possible whether the volatile OS data should be preserved.', 'kb-doc-04-nist-sp-800-86-p53-3', 0, 16, '04-nist-sp-800-86', 'retrieved', '7D80C8DA47D6CDC5EE491BAF47F5C6AC346519E4C27B0B6373BE5C48A2C6045D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-4', 'doc-04-nist-sp-800-86', '', 53, 'Ideally, the criteria for making this decision should have been documented in advance so that the analyst can make the best decision immediately.', 'kb-doc-04-nist-sp-800-86-p53-4', 0, 23, '04-nist-sp-800-86', 'retrieved', 'F4B4F8C1A5AE078A5E495851B4E8FF92CC6DCE114EBEDB175604A6A6F692C9EF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-5', 'doc-04-nist-sp-800-86', '', 53, 'The importance of this decision cannot be stressed enough, because powering off the system or even disconnecting it from a network can eliminate the opportunity to collect potentially important information.', 'kb-doc-04-nist-sp-800-86-p53-5', 0, 30, '04-nist-sp-800-86', 'retrieved', '0937289B71F1251F713DDF6E838F89C0786078CB96EE7342D0105329B4C0B42B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-6', 'doc-04-nist-sp-800-86', '', 53, 'For example, if a user recently ran encryption tools to secure data, the computers RAM might contain password hashes, which could be used to determine the passwords.', 'kb-doc-04-nist-sp-800-86-p53-6', 0, 27, '04-nist-sp-800-86', 'retrieved', 'F762608465DEF9E69A486AA1BA5E321C2E11F6ABA5915F90989B16439CA13390', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-7', 'doc-04-nist-sp-800-86', '', 53, 'On the other hand, collecting volatile OS data from a running computer has inherent risks.', 'kb-doc-04-nist-sp-800-86-p53-7', 0, 15, '04-nist-sp-800-86', 'retrieved', 'A7982702DAA7FC56253CE4F3FB6BAD2A467879B374CE8F7033AE97629AC370E0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-8', 'doc-04-nist-sp-800-86', '', 53, 'For instance, the possibility always exists that files on the computer might change and other volatile OS data might be altered.', 'kb-doc-04-nist-sp-800-86-p53-8', 0, 21, '04-nist-sp-800-86', 'retrieved', 'B1F17D85D5E651EC8132B402A8E26BB5DE249A813604264E9C111AFEE454FA08', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-9', 'doc-04-nist-sp-800-86', '', 53, 'In addition, a malicious party might have installed rootkits designed to return false information, delete files, or perform other malicious acts.', 'kb-doc-04-nist-sp-800-86-p53-9', 0, 21, '04-nist-sp-800-86', 'retrieved', '8C52E3371645F5B8C57AD75055F7246A67E8F0CA42D9CC128BA94A5ACAFCAB51', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-10', 'doc-04-nist-sp-800-86', '', 53, 'In deciding whether to collect volatile data, the risks associated with such collection should be weighed against the potential for recovering important information.', 'kb-doc-04-nist-sp-800-86-p53-10', 0, 23, '04-nist-sp-800-86', 'retrieved', '13D482622C56D9EC6304C1905FE1771865C23ECE73275A20F01B2997A3C7AB1F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-11', 'doc-04-nist-sp-800-86', '', 53, 'As noted in Section 3.2, if evidence may be needed, the analyst should fully document what is seen on the screen before touching the system.', 'kb-doc-04-nist-sp-800-86-p53-11', 0, 25, '04-nist-sp-800-86', 'retrieved', 'C8ECE139C75D5DEE39A6A86EA273F3837D68752BD1C4ED3389D87BF8FD3210F3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-12', 'doc-04-nist-sp-800-86', '', 53, 'If a live system is in sleep mode or has visible password protection, analysts should also decide whether to alter the state of the system by waking it from sleep mode or attempting to crack or bypass the password protection so that analysts can attempt to collect volatile data.', 'kb-doc-04-nist-sp-800-86-p53-12', 0, 49, '04-nist-sp-800-86', 'retrieved', '98642E21D2D711AACC2397D7912E39D6FDB9A6817392EFA8096A5F3F6323799A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-13', 'doc-04-nist-sp-800-86', '', 53, 'If the effort needed to collect the volatile data is not merited, analysts might instead decide to perform a shutdown, as described in Section 5.2.2.', 'kb-doc-04-nist-sp-800-86-p53-13', 0, 25, '04-nist-sp-800-86', 'retrieved', '51DD6266099B3BC60ADDFA210C6D06FC7C9B33B554FCEC3D94CE43DEBAC7854C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-14', 'doc-04-nist-sp-800-86', '', 53, 'Section 5.2.1.1 describes how forensic tools should be compiled in preparation for collecting volatile OS data.', 'kb-doc-04-nist-sp-800-86-p53-14', 0, 16, '04-nist-sp-800-86', 'retrieved', '215D118382F5282D18C70AD4096DD2A0E1BFF85131666D3F1FA7E4999D175161', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-15', 'doc-04-nist-sp-800-86', '', 53, 'Next, Section 5.2.1.2 discusses several types of data and mentions categories of tools or specific OS tools that are effective in collecting each type of data.', 'kb-doc-04-nist-sp-800-86-p53-15', 0, 26, '04-nist-sp-800-86', 'retrieved', '5869E68CCD484A4DB7AB51AF42A55F57AF33704457FE31472AFB25F3DE9A7FD5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-16', 'doc-04-nist-sp-800-86', '', 53, 'Finally, Section 5.2.1.3 explains the need to identify the types of volatile OS data that are most likely to be valuable in a particular situation and then to prioritize the collection of data based on importance and relative volatility.', 'kb-doc-04-nist-sp-800-86-p53-16', 0, 39, '04-nist-sp-800-86', 'retrieved', '4FE8F0017E817E30C127E1FC2B9C8DF2EE4FB3DB12A37F9F52E0B585B355DDBE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-17', 'doc-04-nist-sp-800-86', '', 53, '5.2.1.1 Forensic Tool Preparation When collecting volatile OS data, all forensic tools that might be needed should be placed on a floppy disk, CD-ROM, or USB flash drive, from which the tools should be executed.', 'kb-doc-04-nist-sp-800-86-p53-17', 0, 35, '04-nist-sp-800-86', 'retrieved', '79C77770BB6520A415E9776EDA2F8DBFAA07B77F21B9EF96556B2BE4E1955579', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-18', 'doc-04-nist-sp-800-86', '', 53, 'Doing so enables analysts to collect OS data with the least amount of disturbance to the system.', 'kb-doc-04-nist-sp-800-86-p53-18', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A3D947536A65D0737200F68047C386414EA9483C03DA64F5434104EA2D7F8EF1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-19', 'doc-04-nist-sp-800-86', '', 53, 'In addition, only forensic tools should be used, since a user might have replaced system commands with malicious programs, such as one to format a hard disk or return false information.', 'kb-doc-04-nist-sp-800-86-p53-19', 0, 31, '04-nist-sp-800-86', 'retrieved', '82267DA1BEBA3A5A179F5536D52FD6544C5F4747BB189906AAAEDB735914E6B0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-20', 'doc-04-nist-sp-800-86', '', 53, 'However, use of forensic tools is no guarantee that the data retrieved will be accurate.', 'kb-doc-04-nist-sp-800-86-p53-20', 0, 15, '04-nist-sp-800-86', 'retrieved', '384855D37F871D6FCDA35FE47A68387239C027C27422156EB1D131985C9B1A3F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-21', 'doc-04-nist-sp-800-86', '', 53, 'If a system has been fully compromised, it is possible that rootkits and other malicious utilities have been installed that alter the systems functionality at the kernel level.', 'kb-doc-04-nist-sp-800-86-p53-21', 0, 28, '04-nist-sp-800-86', 'retrieved', 'C63619AC6C46BBAB1715BEEBFC1E6BE426BFA47678D9317A4302646827F45957', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-23', 'doc-04-nist-sp-800-86', '', 53, 'When creating a collection of forensic tools, statically linked binary files should be used.', 'kb-doc-04-nist-sp-800-86-p53-23', 0, 14, '04-nist-sp-800-86', 'retrieved', '8CE761D52A60EAE06A5CD4D089450DBE6020479EEC98D028E4D8365BA77EFA98', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-24', 'doc-04-nist-sp-800-86', '', 53, 'Such an executable file contains all of the functions and library functions that it references, so separate dynamic link libraries (DLL) and other supporting files are not needed.', 'kb-doc-04-nist-sp-800-86-p53-24', 0, 28, '04-nist-sp-800-86', 'retrieved', '5264D42086820E6010A8F70A0159BD4ABF5F61EC91DB509FC11F5CDC957748DA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-25', 'doc-04-nist-sp-800-86', '', 53, 'This eliminates the need to place the appropriate versions of DLLs on the tool media and increases the reliability of the tools.', 'kb-doc-04-nist-sp-800-86-p53-25', 0, 22, '04-nist-sp-800-86', 'retrieved', 'A3C710077D1FC5B25F33216902BFC73FA9908F961A384CD45312B6ABA33FACBE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-26', 'doc-04-nist-sp-800-86', '', 53, 'The analyst should know how each tool affects or alters the system before collecting the volatile data.', 'kb-doc-04-nist-sp-800-86-p53-26', 0, 17, '04-nist-sp-800-86', 'retrieved', '92B3E350F1CFA8ED66FCF3399A6CB0C3C07682874CA69061A98EED3EF01007F5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-27', 'doc-04-nist-sp-800-86', '', 53, 'The message digest of each tool should be computed and stored safely to verify file integrity.', 'kb-doc-04-nist-sp-800-86-p53-27', 0, 16, '04-nist-sp-800-86', 'retrieved', '592EBB7AB5DC86E21823BD0B98FB07614A1F5ABD63ABE971485827291FDF214A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-28', 'doc-04-nist-sp-800-86', '', 53, 'Licensing and version information also should be documented for each forensic tool.', 'kb-doc-04-nist-sp-800-86-p53-28', 0, 12, '04-nist-sp-800-86', 'retrieved', '7288C1E0E9765D064F23FDDC7F1831270ECF8727CF52C0362D146C6CB55C7033', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-29', 'doc-04-nist-sp-800-86', '', 53, 'In addition, the exact commands that were used to run each forensic tool should be documented (i.e., command line arguments and switches).', 'kb-doc-04-nist-sp-800-86-p53-29', 0, 22, '04-nist-sp-800-86', 'retrieved', '4B56810556A26AF839A85608128D819911FC1C9FC1282EBD7F15F02BC37D1C94', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p53-30', 'doc-04-nist-sp-800-86', '', 53, 'It may be helpful to place a script on the tool media that can be run to capture which commands were run, at what time, and with what output.', 'kb-doc-04-nist-sp-800-86-p53-30', 0, 29, '04-nist-sp-800-86', 'retrieved', 'F36F234AA5392FD44A7A172151505641D16AF03094B7AFF87217D918F3278C96', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-1', 'doc-04-nist-sp-800-86', '', 54, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE The media containing the tools should protect them from changes.', 'kb-doc-04-nist-sp-800-86-p54-1', 0, 18, '04-nist-sp-800-86', 'retrieved', '11638406D4069CFEBB5B7DD137FED2B5E62F7A5A4514EA722F997F745A1DE196', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-2', 'doc-04-nist-sp-800-86', '', 54, 'Floppy disks should be write- protected to ensure that no changes are made to the tools.', 'kb-doc-04-nist-sp-800-86-p54-2', 0, 16, '04-nist-sp-800-86', 'retrieved', 'CCC5CB05BCF34550440EE59B22ADC6B573445963AC3A8C569BE0F0D58B5E3AED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-3', 'doc-04-nist-sp-800-86', '', 54, 'CD-ROMs should be write-once CDs (i.e., CD- R), not rewritable CDs, since the contents of a rewritable CD could be altered by CD-burning utilities on the users computer.', 'kb-doc-04-nist-sp-800-86-p54-3', 0, 28, '04-nist-sp-800-86', 'retrieved', 'F6499B2C60A89434AF8C1D98F980ACE9B3027861348CA544C96BB0357EC2B286', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-4', 'doc-04-nist-sp-800-86', '', 54, 'After the tools have been burned to a write-once CD, the disc should be finalized to ensure that no additional data can be written to it.66 Because the media containing the tools should be write-protected, the results produced by the tools cannot be placed onto the tool media.', 'kb-doc-04-nist-sp-800-86-p54-4', 0, 48, '04-nist-sp-800-86', 'retrieved', '32F3C2A4BDFF56F5CFDAE7DFD27E6272EAF91F6100172243DC1074D7751693D3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-5', 'doc-04-nist-sp-800-86', '', 54, 'Analysts often direct tool output to a floppy disk, but the prevalence of floppy disk drives on computing devices is decreasing.', 'kb-doc-04-nist-sp-800-86-p54-5', 0, 21, '04-nist-sp-800-86', 'retrieved', '52645F5C1CB18062B367F2319AA0C9761840A6344ADE2CF8D1A67377A4CDA0A9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-7', 'doc-04-nist-sp-800-86', '', 54, 'Specially prepared CDs and USB flash drives containing a Windows or Linux-based environment can be used to gather output without changing the state of the system and typically direct the output to another USB flash drive, external hard drive, or other writable media, or to a remote system.', 'kb-doc-04-nist-sp-800-86-p54-7', 0, 48, '04-nist-sp-800-86', 'retrieved', '80FBECDEE66DEADC38F206CA4924DBF0E9A59DD70F016DFD3CF2CCAEB7E52BDB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-8', 'doc-04-nist-sp-800-86', '', 54, '5.2.1.2 Types of Volatile OS Data The following list shows several types of volatile OS data and explains how forensic tools can be used in collecting each type of data:67 ! Contents of Memory.', 'kb-doc-04-nist-sp-800-86-p54-8', 0, 34, '04-nist-sp-800-86', 'retrieved', '5A49D5D220AC9AEEA545455F67E531F958BBD280833395F9F578CE92772ED4CC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-9', 'doc-04-nist-sp-800-86', '', 54, 'There are several utilities that can copy the contents of RAM to a data file and assist in subsequent analysis of the data.', 'kb-doc-04-nist-sp-800-86-p54-9', 0, 23, '04-nist-sp-800-86', 'retrieved', '1CBEFACA2AB2F6CB7FC68AE63EB652ABEB3C9D8C72DB651D0D811675CB764191', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-10', 'doc-04-nist-sp-800-86', '', 54, 'On most systems, it is not possible to avoid alteration of RAM when running a utility that attempts to make a copy of RAM.', 'kb-doc-04-nist-sp-800-86-p54-10', 0, 24, '04-nist-sp-800-86', 'retrieved', 'EB7D42AEC5DF25AF69686B971BC81EF5D8455E1552178E2AC2F5F5604192D7C8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-11', 'doc-04-nist-sp-800-86', '', 54, 'Instead, the goal is to perform the copying with as small a footprint as possible to minimize the disruption of RAM.', 'kb-doc-04-nist-sp-800-86-p54-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '71284D8AB74D8205E724DEA60D896C60B8829E7D7AC0C6DBBC56E19093A59B76', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-13', 'doc-04-nist-sp-800-86', '', 54, 'Most OSs include a utility that displays the current network configuration, such as ifconfig on UNIX systems and ipconfig on Windows systems.', 'kb-doc-04-nist-sp-800-86-p54-13', 0, 22, '04-nist-sp-800-86', 'retrieved', '585FFA38206075B11FE3A25468EAF7DCBA6AEFD700069157E89C1699F46DCA12', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-14', 'doc-04-nist-sp-800-86', '', 54, 'Information that can be provided through network configuration utilities includes the hostname, the physical and logical network interfaces, and configuration information for each interface (e.g., IP address, Media Access Control [MAC] address, current status).', 'kb-doc-04-nist-sp-800-86-p54-14', 0, 34, '04-nist-sp-800-86', 'retrieved', '10CB86C609C8BF95BB11A7D29C8BC07F56F0E9CD053366F01A531AA6311EA174', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-16', 'doc-04-nist-sp-800-86', '', 54, 'OSs typically provide a method for displaying a list of the current network connections.', 'kb-doc-04-nist-sp-800-86-p54-16', 0, 14, '04-nist-sp-800-86', 'retrieved', '8C9B924AA9E7F00D2D55B094A952772369E64CCD836E794C225A437116BB4276', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-17', 'doc-04-nist-sp-800-86', '', 54, 'Both Windows and UNIX-based systems usually include the netstat program, which lists network connections by source and destination IP addresses and ports, and also lists which ports are open on each interface.68 Third-party utilities are available that can display port assignments for each program.', 'kb-doc-04-nist-sp-800-86-p54-17', 0, 44, '04-nist-sp-800-86', 'retrieved', 'A2AA42B09B389717386924742F6CF40AC8CA55B559255671377C240D1AAA9C45', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-18', 'doc-04-nist-sp-800-86', '', 54, 'Most OSs also can display a list of remotely mounted filesystems, which provides more detailed information than a network connection list.', 'kb-doc-04-nist-sp-800-86-p54-18', 0, 21, '04-nist-sp-800-86', 'retrieved', '060A611C93F308EC3E224A3EB39370272EE06842725AC9721DB49CE61C2E3C3B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-19', 'doc-04-nist-sp-800-86', '', 54, 'Section 6.2.7 provides additional information about gathering network connection information.69', 'kb-doc-04-nist-sp-800-86-p54-19', 0, 10, '04-nist-sp-800-86', 'retrieved', '18D48EBA9762E5AFA2D9FD1A8FD05DB4BF70F2111AF7E9AF10EDC5AADE43E39D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-22', 'doc-04-nist-sp-800-86', '', 54, 'However, closing a session simply indicates to the CD-burning utility that no additional data will be written to the disc in the current session; it does not prevent additional data from being written to the disc in a different session (often referred to as a multisession disc).', 'kb-doc-04-nist-sp-800-86-p54-22', 0, 47, '04-nist-sp-800-86', 'retrieved', '6B4217AF64667510FC7AB7D65D6CB67D0B1803CBFCAD1FD15F50706487755593', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-23', 'doc-04-nist-sp-800-86', '', 54, 'Therefore, analysts should finalize the disc, not close the session, when creating a toolkit CD.', 'kb-doc-04-nist-sp-800-86-p54-23', 0, 15, '04-nist-sp-800-86', 'retrieved', '11A736F1E6A8CD49825A86A297059CE7ED09DBDF7AE653792B1263060866BFBC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-24', 'doc-04-nist-sp-800-86', '', 54, '67 Many resources are available that list the hundreds of tools available for analysts.', 'kb-doc-04-nist-sp-800-86-p54-24', 0, 14, '04-nist-sp-800-86', 'retrieved', 'FD5B8447C0089ED8CE2589AE7EC6DE8060E642EEA7E4D188F770BBE9F766A7DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-25', 'doc-04-nist-sp-800-86', '', 54, 'Appendix F lists several Web sites that contain more information on computer forensic tools.', 'kb-doc-04-nist-sp-800-86-p54-25', 0, 14, '04-nist-sp-800-86', 'retrieved', '2D6BE48EBD51B9D0C33AFCB545C9ADF14DDB1282F2CF7CE2274898C6EC757B21', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-26', 'doc-04-nist-sp-800-86', '', 54, 'For tools that are included with OSs, analysts should use copies of the tools that are on read-only media, not tools on the OS of a system of interest.', 'kb-doc-04-nist-sp-800-86-p54-26', 0, 29, '04-nist-sp-800-86', 'retrieved', '246C6A50B38FA301416A73BD775B50F36BFB5020D4605A57206C285B40249218', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-27', 'doc-04-nist-sp-800-86', '', 54, '68 Another way of identifying the open ports is by running port scanning software from another system.', 'kb-doc-04-nist-sp-800-86-p54-27', 0, 17, '04-nist-sp-800-86', 'retrieved', 'C1EB6A4EC075664E4D9F7C6E11B47C57ECE2CFC54417926F3E6E7AF2C2F33D6D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-28', 'doc-04-nist-sp-800-86', '', 54, 'Port scanning software sends network traffic to various ports and analyzes the responses, as well as missing responses, to determine which ports are open.', 'kb-doc-04-nist-sp-800-86-p54-28', 0, 24, '04-nist-sp-800-86', 'retrieved', '12D3FFA6891B0789547B292B1F6EBFFBD1B7C3D6BB1E123BF105D10D65A39D16', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-29', 'doc-04-nist-sp-800-86', '', 54, 'However, port scanning might produce inaccurate results due to security controls, such as host-based firewalls that block the scans; also, the scans could change the state of the system.', 'kb-doc-04-nist-sp-800-86-p54-29', 0, 29, '04-nist-sp-800-86', 'retrieved', 'BFB82A0DB65CE3C34F47AE1269A0131A9475E31103284133238966A5812D04DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p54-30', 'doc-04-nist-sp-800-86', '', 54, 'Accordingly, port scans are best suited for informal data acquisition and for information collection when access to the OS is not available.', 'kb-doc-04-nist-sp-800-86-p54-30', 0, 22, '04-nist-sp-800-86', 'retrieved', '649DCB65DC07ABF74C610D0437B3A40CC50D89F4B1CCEDD33F04357035EF34E7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
