VALUES ('doc-04-nist-sp-800-86-p56-1', 'doc-04-nist-sp-800-86', '', 56, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE such data will be lost once the computer is powered down.', 'kb-doc-04-nist-sp-800-86-p56-1', 0, 19, '04-nist-sp-800-86', 'retrieved', '0632A3F11F98A1F9EE6ADF73FD06B52F68DB5B5793C09C3B4EE74B815B7CDFD5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
