VALUES ('doc-04-nist-sp-800-86-p56-2', 'doc-04-nist-sp-800-86', '', 56, 'Later, a determination can be made as to which collected volatile data should be examined.', 'kb-doc-04-nist-sp-800-86-p56-2', 0, 15, '04-nist-sp-800-86', 'retrieved', '1834D6EA643DB4EFFEAC68F4782D75EE164F1ABB36E895352DE88C969B18F871', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
