INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-3', 'doc-04-nist-sp-800-86', '', 56, 'An automated script on a toolkit CD can be used for consistency in collecting volatile data.', 'kb-doc-04-nist-sp-800-86-p56-3', 0, 16, '04-nist-sp-800-86', 'retrieved', '8162D817A763EE8CB324C5D7F44B441FA4BB496E46B731729F91F620CE8C1C55', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
