INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-4', 'doc-04-nist-sp-800-86', '', 56, 'The script can include ways to transfer the collected information to local storage media, such as a thumb drive, and to networked drive locations.', 'kb-doc-04-nist-sp-800-86-p56-4', 0, 24, '04-nist-sp-800-86', 'retrieved', 'BA2C9DA9C08598F267610A75CF36FE107B518ABB975F82885BF5B5DC4A0F03F9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-5', 'doc-04-nist-sp-800-86', '', 56, 'Because volatile data has a propensity to change over time, the order and timeliness with which volatile data is collected is important.', 'kb-doc-04-nist-sp-800-86-p56-5', 0, 22, '04-nist-sp-800-86', 'retrieved', '3DAAC9E54655AD9620DDA09D529B22DAC192DBA8556A85288248018F51091F52', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-6', 'doc-04-nist-sp-800-86', '', 56, 'In most cases, analysts should first collect information on network connections and login sessions, because network connections may time out or be disconnected and the list of users connected to a system at any single time may vary.', 'kb-doc-04-nist-sp-800-86-p56-6', 0, 38, '04-nist-sp-800-86', 'retrieved', '55444915A66A91E6288CEA81931AFCA3CEF53D18A4A8FC6F05CF3765A75979C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-7', 'doc-04-nist-sp-800-86', '', 56, 'Volatile data that is less likely to change, such as network configuration information, should be collected later.', 'kb-doc-04-nist-sp-800-86-p56-7', 0, 17, '04-nist-sp-800-86', 'retrieved', 'F32EF4FA680935E40C20A9D74360B43C3199430E89953CF630A5CD2635B53860', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-8', 'doc-04-nist-sp-800-86', '', 56, 'The recommended order in which volatile data generally should be collected, from first to last, is as follows: 1. N etwork connections 2. Logi n sessions 3. C ontents of memory 4. R unning processes 5. Ope n files 6. N etwork configuration 7. Operating system time.', 'kb-doc-04-nist-sp-800-86-p56-8', 0, 47, '04-nist-sp-800-86', 'retrieved', '0CC45B54930BACCB47201BCB393EC33A2788F18D8B257E21A729467358405455', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-10', 'doc-04-nist-sp-800-86', '', 56, 'Collecting Non-Volatile OS Data After obtaining volatile OS data, analysts often should collect non-volatile OS data.', 'kb-doc-04-nist-sp-800-86-p56-10', 0, 16, '04-nist-sp-800-86', 'retrieved', '4CC56852127C3E2492F666C0E3BB3695799BB02F17687A6AF753880FA38B2D23', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-11', 'doc-04-nist-sp-800-86', '', 56, 'To do so, the analyst first should decide whether the system should be shut down.', 'kb-doc-04-nist-sp-800-86-p56-11', 0, 15, '04-nist-sp-800-86', 'retrieved', 'D0BFA4EA87B3AA31F47FE0EABFF30620B918311E2B0821A1B3EC304040B2B747', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-12', 'doc-04-nist-sp-800-86', '', 56, 'Shutting down the system not only affects the ability to perform bit stream imaging and many logical backups, but can also change which OS data is preserved.', 'kb-doc-04-nist-sp-800-86-p56-12', 0, 27, '04-nist-sp-800-86', 'retrieved', '8707EE34BC125614220BDEB72D1BC23963E02FBCA485650F471739B1CED801EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-13', 'doc-04-nist-sp-800-86', '', 56, 'Most systems can be shut down through two methods: ! Perform a Graceful OS Shutdown.', 'kb-doc-04-nist-sp-800-86-p56-13', 0, 15, '04-nist-sp-800-86', 'retrieved', 'D79D83B1A190299E1338E9C710E788854F538564CD063B29567AFB181FDA2F58', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-14', 'doc-04-nist-sp-800-86', '', 56, 'Nearly every OS offers a shutdown option.72 This causes the OS to perform cleanup activities, such as closing open files, deleting temporary files, and possibly clearing the swap file, before shutting down the system.', 'kb-doc-04-nist-sp-800-86-p56-14', 0, 34, '04-nist-sp-800-86', 'retrieved', 'DE13ABA5C45B1AEDEAD11D7F0847433ACBA33607BD6715B2603DE548623F6188', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-15', 'doc-04-nist-sp-800-86', '', 56, 'A graceful shutdown can also trigger removal of malicious material; for example, memory-resident rootkits may disappear, and Trojan horses may remove evidence of their malicious activity.', 'kb-doc-04-nist-sp-800-86-p56-15', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A6047A6CF14143A960AE16545D16821AEB86FD094EFAFA58BBEBE978A3DFAEEB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-16', 'doc-04-nist-sp-800-86', '', 56, 'The OS is typically shut down from the account of the administrator or the current user of the system (if the current user has sufficient privileges).', 'kb-doc-04-nist-sp-800-86-p56-16', 0, 26, '04-nist-sp-800-86', 'retrieved', 'D0091079072CD6CBA746633BEF1742B77066B17C8771AD0C81C90859A1D4129A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-18', 'doc-04-nist-sp-800-86', '', 56, 'Disconnecting the power cord from the back of the computer (and removing the batteries on a laptop or other portable device) can preserve swap files, temporary data files, and other information that might be altered or deleted during a graceful shutdown.73 Unfortunately, a sudden loss of power can cause some OSs to corrupt data, such as', 'kb-doc-04-nist-sp-800-86-p56-18', 0, 56, '04-nist-sp-800-86', 'retrieved', '0CCFB3B45473A9467E0EC50A362B5F4B164239B9C30FD14B9107279D943AF0A5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-19', 'doc-04-nist-sp-800-86', '', 56, '72 For example, on Windows systems, analysts could use the Shut Down feature on the Start menu.', 'kb-doc-04-nist-sp-800-86-p56-19', 0, 17, '04-nist-sp-800-86', 'retrieved', '1233C177E0E3A69C27770EC88165A13654D7C29A8097F5C5429C77410B365253', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p56-20', 'doc-04-nist-sp-800-86', '', 56, '73 Disconnecting a power cord from the electrical wall outlet is not recommended because the computers power cord may be plugged into an uninterruptible power supply (UPS) unit.', 'kb-doc-04-nist-sp-800-86-p56-20', 0, 28, '04-nist-sp-800-86', 'retrieved', 'B96154F82E840DC67AA0C6A880C4AD897C8520BF9B1B5F1C58257DDD3C8CC7EC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-2', 'doc-04-nist-sp-800-86', '', 57, 'In addition, for some consumer devices, such as PDAs and cell phones, removing battery power can cause a loss of data.74 Some tools are able to perform collection actions on running systems without any problems, while other tools are best run on systems that have been shut down.', 'kb-doc-04-nist-sp-800-86-p57-2', 0, 48, '04-nist-sp-800-86', 'retrieved', '36FB53D47DB3A26BE00B9AA341F518E1018DEAACF35A51685153D6ED3E4A5D4A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-3', 'doc-04-nist-sp-800-86', '', 57, 'In the latter case, analysts should be aware of the characteristics of each OS and choose a shutdown method based on the typical behavior of the OS and the types of data that need to be preserved.75 For example, DOS and Windows 95/98 systems generally do not corrupt data when power is removed suddenly, so removing power should preserve data.', 'kb-doc-04-nist-sp-800-86-p57-3', 0, 60, '04-nist-sp-800-86', 'retrieved', 'D85E9B364A901AA5579FFF7E24095ACF518320886AA6C0DAE4682AE8EC50D112', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-4', 'doc-04-nist-sp-800-86', '', 57, 'Other OSs might corrupt data, such as open files or files that were being accessed at the time, if there is a loss of power.', 'kb-doc-04-nist-sp-800-86-p57-4', 0, 25, '04-nist-sp-800-86', 'retrieved', '47EF7BB2A94D73994694F98E4673181CB592DB1B97D5D3CF58850B8EA82A53AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-5', 'doc-04-nist-sp-800-86', '', 57, 'In these cases, a graceful shutdown is generally best unless swap files or temporary data files are of particular interest or the system might contain rootkits, Trojan horses, or other malicious programs that might be triggered by a graceful shutdown.', 'kb-doc-04-nist-sp-800-86-p57-5', 0, 40, '04-nist-sp-800-86', 'retrieved', '7B571378A512BFAA58360554883B7AFEEC9E66D56997990256FD342753639A2E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-6', 'doc-04-nist-sp-800-86', '', 57, 'After performing a shutdown (if needed), the analyst should acquire filesystem data from the systems storage media using the methods discussed in Section 4.', 'kb-doc-04-nist-sp-800-86-p57-6', 0, 24, '04-nist-sp-800-86', 'retrieved', 'F9845B0E3ADEAD94CBB384BF902AFD1515D119B77640DBCBC06CF477849F784A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-7', 'doc-04-nist-sp-800-86', '', 57, 'After the computer has been powered off, all components, storage devices, media, and peripheral devices connected to the computer should be inventoried and labeled if they are needed as evidence.', 'kb-doc-04-nist-sp-800-86-p57-7', 0, 30, '04-nist-sp-800-86', 'retrieved', '65EBA036E95A590DDD5EC92FDCF8B4D6051FEC2E124866FC4E3BFAB0A5382694', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
