INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-8', 'doc-04-nist-sp-800-86', '', 57, 'Whenever possible, the inventory should include the model number, serial number, and description of the item.', 'kb-doc-04-nist-sp-800-86-p57-8', 0, 16, '04-nist-sp-800-86', 'retrieved', 'E8AB7852A7814C2BB7512F3CA27296856C81A17DC9B97C0F5BEEB0DF9327857A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
