VALUES ('doc-04-nist-sp-800-86-p57-9', 'doc-04-nist-sp-800-86', '', 57, 'In addition, information about how each item is connected to the outside or inside of the computer (e.g., cable connections, jumper settings) should be documented and photographed.', 'kb-doc-04-nist-sp-800-86-p57-9', 0, 27, '04-nist-sp-800-86', 'retrieved', 'CF7E1689C9A3A425DC6BF892C0A59BB9BB786F4461C429C02E55213527A12B28', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
