INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-11', 'doc-04-nist-sp-800-86', '', 57, 'Assuming that the evidence can be legally seized, each item should be handled using antistatic bracelets, guarded against electrostatic discharges that can damage the item, sealed properly (i.e., a box that is taped shut), and packed securely for transport.', 'kb-doc-04-nist-sp-800-86-p57-11', 0, 39, '04-nist-sp-800-86', 'retrieved', '2853BB5B4A1BBB13C200539A4FB04E994A1058844BC544E0DE522BDD7D7898E4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
