INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-12', 'doc-04-nist-sp-800-86', '', 57, 'Handlers should wear antistatic bracelets when handling sensitive media and protect media with antistatic bags and other special packing materials.', 'kb-doc-04-nist-sp-800-86-p57-12', 0, 20, '04-nist-sp-800-86', 'retrieved', 'E73452C7420638F7E1C421D6F562627608B0E2306EBC60E81B5A7045984362EE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
