INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-13', 'doc-04-nist-sp-800-86', '', 57, 'Once the filesystem data has been collected, tools can be used to acquire specific types of data from the filesystem.', 'kb-doc-04-nist-sp-800-86-p57-13', 0, 20, '04-nist-sp-800-86', 'retrieved', '019C59A1F9CD463CA24A320C401E31070FAEF61C254D8B087A1AD7F1167EFC10', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
