INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-14', 'doc-04-nist-sp-800-86', '', 57, 'Acquiring regular files, such as data, application, and configuration files, is relatively straightforward and is described in more detail in Section 4.', 'kb-doc-04-nist-sp-800-86-p57-14', 0, 22, '04-nist-sp-800-86', 'retrieved', 'DE83BA50902CB85D2F3A2338F244A14A4B7085CA1BD103044A0D6B4C92C4948A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
