INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-15', 'doc-04-nist-sp-800-86', '', 57, 'The following list describes several other types of non-volatile OS data and explains how tools can be useful in acquiring each type from the filesystem:76 ! Users and Groups.', 'kb-doc-04-nist-sp-800-86-p57-15', 0, 29, '04-nist-sp-800-86', 'retrieved', '512EE70CCC14AC2A4CC4DF11A2B8B26E840DC3CCC52698A0FFF2AD8D696999C5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-16', 'doc-04-nist-sp-800-86', '', 57, 'Operating systems maintain a list of users and groups that have access to the system.', 'kb-doc-04-nist-sp-800-86-p57-16', 0, 15, '04-nist-sp-800-86', 'retrieved', '34E953FB0A5AFD7EBBC4534BA093460CE676036AA5E4AA329E80F2C820EFDD17', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-17', 'doc-04-nist-sp-800-86', '', 57, 'On UNIX systems, users and groups are listed in /etc/passwd and /etc/groups, respectively.', 'kb-doc-04-nist-sp-800-86-p57-17', 0, 13, '04-nist-sp-800-86', 'retrieved', 'E89BE125033D4035921C819D5B440F0DCCC7F6122D93008B9DC8D32F2C4BDB82', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-18', 'doc-04-nist-sp-800-86', '', 57, 'In addition, the groups and users commands can be used to identify users who have logged onto the system and the groups to which they belong.', 'kb-doc-04-nist-sp-800-86-p57-18', 0, 26, '04-nist-sp-800-86', 'retrieved', 'D070ADCBE23A099E0055F2408D15F39A26DDBFDA943021B4F5FC16B5294C9520', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-19', 'doc-04-nist-sp-800-86', '', 57, 'On Windows systems, the net user and net group commands can be used to enumerate the users and groups on a system.', 'kb-doc-04-nist-sp-800-86-p57-19', 0, 22, '04-nist-sp-800-86', 'retrieved', 'FE7C4EA3D23AA1C071010EAAFF6E208388F4DD6A085539A9C0C072A4BB651BCD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-22', 'doc-04-nist-sp-800-86', '', 57, 'On Windows systems, third-party utilities can be used to dump password hashes from the Security Account Manager (SAM) database.', 'kb-doc-04-nist-sp-800-86-p57-22', 0, 19, '04-nist-sp-800-86', 'retrieved', 'BB4101CDC4D62441EA680FDF7CEF484676C2E905BEA7ECED3D4D4E27FB4E578A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-23', 'doc-04-nist-sp-800-86', '', 57, 'On UNIX systems, password hashes are usually in the /etc/passwd or /etc/shadow file.', 'kb-doc-04-nist-sp-800-86-p57-23', 0, 13, '04-nist-sp-800-86', 'retrieved', '997DBE826B2F29588FA2616084C1E85899A3106F3441323A14BFBE56BC930D18', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
