VALUES ('doc-04-nist-sp-800-86-p57-24', 'doc-04-nist-sp-800-86', '', 57, 'As described in Section 4.3.2, password cracking programs can be used to extract passwords from their hashes.', 'kb-doc-04-nist-sp-800-86-p57-24', 0, 17, '04-nist-sp-800-86', 'retrieved', 'DFABFD684042FD7C6013A92CB006ACEB0A244532F4E61A923814BEF9774438AA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
