INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-26', 'doc-04-nist-sp-800-86', '', 57, 'If a device does not have regular power, typically its memory will be sustained by battery power only for the short term (weeks at most, minutes at worst), even if the device is powered off.', 'kb-doc-04-nist-sp-800-86-p57-26', 0, 35, '04-nist-sp-800-86', 'retrieved', '57754F64634C6BFC81103B4956E2FC7148D6277F19B4BDA39A532C5FA7F7BF71', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p57-27', 'doc-04-nist-sp-800-86', '', 57, 'For long-term storage of consumer devices that contain important data, power should be maintained to preserve the devices memory.', 'kb-doc-04-nist-sp-800-86-p57-27', 0, 19, '04-nist-sp-800-86', 'retrieved', '01F6DACB463BC729D58552F1EAA8E4B66C801496B4B01CEC304C205C74813AB3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
