VALUES ('doc-04-nist-sp-800-86-p57-28', 'doc-04-nist-sp-800-86', '', 57, '75 In most cases, analysts can determine which type of OS is in use by looking at the screen.', 'kb-doc-04-nist-sp-800-86-p57-28', 0, 19, '04-nist-sp-800-86', 'retrieved', 'F5E9E4151C696AABF5743B07911AC4855E57142B7CB7948836C25238C82076C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
