VALUES ('doc-04-nist-sp-800-86-p57-29', 'doc-04-nist-sp-800-86', '', 57, 'For example, Windows systems use taskbars and other graphic elements that do not appear on other OSs.', 'kb-doc-04-nist-sp-800-86-p57-29', 0, 17, '04-nist-sp-800-86', 'retrieved', 'E54753FED984C4FA2435DF7AE50A55B003D91C68A66993423E014B7ABBEAF1C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
