VALUES ('doc-04-nist-sp-800-86-p57-30', 'doc-04-nist-sp-800-86', '', 57, '76 Some of the tools described in this section can also be used to collect data from a live system.', 'kb-doc-04-nist-sp-800-86-p57-30', 0, 20, '04-nist-sp-800-86', 'retrieved', 'ACA726C7E9008C1485355C3784365F09AD7A9F08F60C1E05797CA6DCB3EC375B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
