INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-3', 'doc-04-nist-sp-800-86', '', 58, 'On Windows systems, the SrvCheck utility can be used to list network shares.77 Third-party utilities can provide similar information for other OSs.', 'kb-doc-04-nist-sp-800-86-p58-3', 0, 22, '04-nist-sp-800-86', 'retrieved', 'E29D771D5F7C4DFDF14616FCD602192734A9A04D58A53FB6B23BB7CC2B83EB9C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-5', 'doc-04-nist-sp-800-86', '', 58, 'Logs that are not stored in text files might necessitate use of log extraction utilities.', 'kb-doc-04-nist-sp-800-86-p58-5', 0, 15, '04-nist-sp-800-86', 'retrieved', '95DE84DF13C282192F16A9848A400E836C479E93B755715317C1AE693C12E088', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-6', 'doc-04-nist-sp-800-86', '', 58, 'For example, specialized utilities can retrieve information about recent successful and failed logon attempts on Windows systems, which are stored in binary format logs.', 'kb-doc-04-nist-sp-800-86-p58-6', 0, 24, '04-nist-sp-800-86', 'retrieved', 'B11B58D7D1AB8DF6C2484ED12D74F70D001864F2A853F24E0BE6D64938AD1DF7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-7', 'doc-04-nist-sp-800-86', '', 58, 'Most log entries on Unix systems are stored in text files by syslog or in the /var/log directory, so special utilities are not needed to acquire information from the logs.78 Searching for filenames ending in .log should identify most log files.', 'kb-doc-04-nist-sp-800-86-p58-7', 0, 41, '04-nist-sp-800-86', 'retrieved', '2E4B0F422633DEFA1D433A8BE4645B7FF64DFF8E51932E1C3D1F7A4CD2FE54E3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-8', 'doc-04-nist-sp-800-86', '', 58, 'Occasionally, analysts may need to collect data from the BIOS, such as system date and time or processor type and speed.79 Because the BIOS primarily contains information related to the systems hardware configuration, BIOS data collection is most likely to be needed when a system administrator is troubleshooting operational issues.', 'kb-doc-04-nist-sp-800-86-p58-8', 0, 50, '04-nist-sp-800-86', 'retrieved', 'E9E137770E0682E65875EAFF8483B995B6695AB7CCC2508ADFEAC1539201B9E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
