INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-9', 'doc-04-nist-sp-800-86', '', 58, 'Typically, analysts who need BIOS data first collect any needed volatile data and filesystems, then reboot the system and press the appropriate function key (generally specified in the initial screen during boot) to display the BIOS settings.', 'kb-doc-04-nist-sp-800-86-p58-9', 0, 37, '04-nist-sp-800-86', 'retrieved', '5C9BAD7F4004B61D6628B12F830DC02F2070FFD02B88A6F39B666C68155BCAE7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-10', 'doc-04-nist-sp-800-86', '', 58, 'If the BIOS password is set, the analyst might not be able to gain access to the BIOS settings easily and might have to attempt to guess default passwords or circumvent the password protection.', 'kb-doc-04-nist-sp-800-86-p58-10', 0, 34, '04-nist-sp-800-86', 'retrieved', '883195DB1F8A3AB2677BC036F791DF1B628131133D129D9CABC853459E1B9864', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-11', 'doc-04-nist-sp-800-86', '', 58, 'A variety of methods can be used to bypass BIOS passwords, including finding the appropriate manufacturer backdoor password, using a password cracker, moving the appropriate jumper on the motherboard, or removing the Complementary Metal Oxide Semiconductor (CMOS) battery (if possible).', 'kb-doc-04-nist-sp-800-86-p58-11', 0, 40, '04-nist-sp-800-86', 'retrieved', 'A7029682E341093BB6B8EF1AAD0B95B945AD8C516C1FAD9CF43A1101660A3F43', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-12', 'doc-04-nist-sp-800-86', '', 58, 'Systems vary, so analysts should first research the particular characteristics of the system they are analyzing, as described in motherboard documentation, to avoid harming a system unnecessarily.80 5.2.3', 'kb-doc-04-nist-sp-800-86-p58-12', 0, 28, '04-nist-sp-800-86', 'retrieved', 'C211D4282920199741ED8FD47B8D71EBBAA48B37B888906B10E9F0CD0DD6917C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
