VALUES ('doc-04-nist-sp-800-86-p58-13', 'doc-04-nist-sp-800-86', '', 58, 'Technical Issues with Collecting Data Technical issues might also impede collection of OS data.', 'kb-doc-04-nist-sp-800-86-p58-13', 0, 14, '04-nist-sp-800-86', 'retrieved', 'AC26FEAEADB56D5A95B9F0617A4F5055A3AB271EA103802ED2F78A363355BFE3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
