INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-14', 'doc-04-nist-sp-800-86', '', 58, 'Section 4 describes several filesystem-related issues; this section focuses on additional collection issues and provides guidance on what, if anything, can be done to mitigate them.', 'kb-doc-04-nist-sp-800-86-p58-14', 0, 26, '04-nist-sp-800-86', 'retrieved', 'B59C9F79912CCDDDE09BECB5C83EA7D5C50F3D7395B5751E09C4F5816E48528D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
