INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-15', 'doc-04-nist-sp-800-86', '', 58, 'The intent of this section is not to provide an exhaustive discussion of all possible issues, but to provide some basic information on common ones.', 'kb-doc-04-nist-sp-800-86-p58-15', 0, 25, '04-nist-sp-800-86', 'retrieved', '8343BF07374E5D52D909D0078546B08F36F0642B0626E70981D0744CFAB656A3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
