INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-17', 'doc-04-nist-sp-800-86', '', 58, 'Collecting volatile data can be difficult because the analyst might not be able to readily gain access to the OS.', 'kb-doc-04-nist-sp-800-86-p58-17', 0, 20, '04-nist-sp-800-86', 'retrieved', '0D0FC3EDF1E2E98A3A54EAFCB1C554094E8308DC5EAE79B28AD4A1C6C6CE585E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
