INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-18', 'doc-04-nist-sp-800-86', '', 58, 'For instance, a user might run a password-protected screen saver or have the system locked.', 'kb-doc-04-nist-sp-800-86-p58-18', 0, 15, '04-nist-sp-800-86', 'retrieved', 'D8CC8CD1CF379A114A56E7BED921CEDE8DB6378F42EA10C77C1BE26E5114E292', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
