INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-19', 'doc-04-nist-sp-800-86', '', 58, 'In these cases, the analyst will need to circumvent this protection or find another way to gain access to volatile OS data.81 If a password-protected screen saver is active, restarting the system might allow the analyst to bypass the screen saver, but would also cause all volatile OS data to be lost.', 'kb-doc-04-nist-sp-800-86-p58-19', 0, 52, '04-nist-sp-800-86', 'retrieved', '01D0B0EAAE5762B3A142EB1AB603723AFAC381F7B761443DB6B4BED40D6CE2E2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p58-20', 'doc-04-nist-sp-800-86', '', 58, 'If a host uses biometric-based authentication, such as a fingerprint reader, or another add-on authentication service, this could cause similar issues in accessing volatile OS data.', 'kb-doc-04-nist-sp-800-86-p58-20', 0, 26, '04-nist-sp-800-86', 'retrieved', '5166BF9E7289F9FA6288EECCA5869D0BD72CA6D602A387E226080C33E51BC6E7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
