VALUES ('doc-04-nist-sp-800-86-p58-23', 'doc-04-nist-sp-800-86', '', 58, '78 More information on the syslog protocol is available in RFC 3164, The BSD Syslog Protocol, available at http://www.ietf.org/rfc/rfc3164.txt.', 'kb-doc-04-nist-sp-800-86-p58-23', 0, 19, '04-nist-sp-800-86', 'retrieved', 'CE45C58CBC20856523F769690F8B70C376A08D6480C7F1E5574D0B458478FC86', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
