VALUES ('doc-04-nist-sp-800-86-p58-24', 'doc-04-nist-sp-800-86', '', 58, '79 Hard drive information presented in the BIOS might be inaccurate for larger hard drives.', 'kb-doc-04-nist-sp-800-86-p58-24', 0, 15, '04-nist-sp-800-86', 'retrieved', '798007DF96D26FAF57F2E16295D9453D84509FDC218F2E0D404FC909EB0456A1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
