VALUES ('doc-04-nist-sp-800-86-p58-25', 'doc-04-nist-sp-800-86', '', 58, 'Many drives now use Logical Block Addressing, which causes the BIOS to display incorrect drive geometry information.', 'kb-doc-04-nist-sp-800-86-p58-25', 0, 17, '04-nist-sp-800-86', 'retrieved', '6F9A70D0565D3348D53DB1DE44DA720FA103677C6220006884783BE518515A96', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
