VALUES ('doc-04-nist-sp-800-86-p58-26', 'doc-04-nist-sp-800-86', '', 58, 'Analysts should be able to acquire the correct information by examining the physical label on the hard drive itself.', 'kb-doc-04-nist-sp-800-86-p58-26', 0, 19, '04-nist-sp-800-86', 'retrieved', '33094DA863BF69369CA1F44F1908669A3435589C013C91C63D2D2D91B06FB142', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
