VALUES ('doc-04-nist-sp-800-86-p58-27', 'doc-04-nist-sp-800-86', '', 58, '80 More information about bypassing BIOS passwords is available at http://www.freelabs.com/~whitis/security/backdoor.html and http://labmice.techtarget.com/articles/BIOS_hack.htm.', 'kb-doc-04-nist-sp-800-86-p58-27', 0, 13, '04-nist-sp-800-86', 'retrieved', '1F706DF226193366F25764F4D61B5D4DF8EB50CA527B6A19212C73FE5CAFAC85', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
