VALUES ('doc-04-nist-sp-800-86-p58-28', 'doc-04-nist-sp-800-86', '', 58, '81 Several Web sites indicate ways to circumvent specific screen savers, such as taking advantage of known OS vulnerabilities.', 'kb-doc-04-nist-sp-800-86-p58-28', 0, 19, '04-nist-sp-800-86', 'retrieved', 'B424FEB4E8DCC6D8DC0E374570CAFFE4F9335DFC5DD3D96CBF721E709400EE71', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
