VALUES ('doc-04-nist-sp-800-86-p58-29', 'doc-04-nist-sp-800-86', '', 58, 'However, the screen saver bypass methods are of little use if the OS is unknown or the user has eliminated the vulnerabilities.', 'kb-doc-04-nist-sp-800-86-p58-29', 0, 22, '04-nist-sp-800-86', 'retrieved', 'D8DF35812AF1CBAA76E86999ABF5F49DEEE3939AA591D57AAE79869C06F14CEA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
