VALUES ('doc-04-nist-sp-800-86-p58-30', 'doc-04-nist-sp-800-86', '', 58, 'General information regarding passwords is available from the Microsoft Knowledge Base article Information About Unlocking a Workstation (http://support.microsoft.com/kb/q281250/) and the article titled Password Information in Windows XP (http://www.kellys-korner-xp.com/win_xp_passwords.htm).', 'kb-doc-04-nist-sp-800-86-p58-30', 0, 28, '04-nist-sp-800-86', 'retrieved', '5C3DB667F67C7309DF21E984147C02F069C2AF1C4E5ACF0D79DF0CFEB66C751E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
