VALUES ('doc-04-nist-sp-800-86-p59-1', 'doc-04-nist-sp-800-86', '', 59, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE saver passwords without rebooting the system.', 'kb-doc-04-nist-sp-800-86-p59-1', 0, 14, '04-nist-sp-800-86', 'retrieved', '116C9E6D71111D3B5558CDE167D8EFDD5D43D39155965DC9665DEE2B29F8AD5A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
