INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-2', 'doc-04-nist-sp-800-86', '', 59, 'These utilities generally rely on the CD drives autorun feature; the utility automatically runs in the background, then locates the encrypted password and attempts to decrypt it.', 'kb-doc-04-nist-sp-800-86-p59-2', 0, 27, '04-nist-sp-800-86', 'retrieved', '80DDF039B464C71E9123C621C75B66700D46AA3DE881CA5C13D6E7B6171FF3C8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
