INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-4', 'doc-04-nist-sp-800-86', '', 59, 'The user might try to reduce the usefulness of logs by disabling log features, modifying log settings so that there is little storage available for logs, or writing many spurious events to the logs.', 'kb-doc-04-nist-sp-800-86-p59-4', 0, 34, '04-nist-sp-800-86', 'retrieved', 'DECB242B3BEAF820BA80C128F5057103D38E1E974183D8777C0B0D86659BDDF0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-5', 'doc-04-nist-sp-800-86', '', 59, 'One way of reducing the impact of logging changes is to configure systems to archive their log entries on a centralized server.', 'kb-doc-04-nist-sp-800-86-p59-5', 0, 22, '04-nist-sp-800-86', 'retrieved', 'FC117B55A1AABCDD8A3DFA11C3B675D06BAFA91D65FECA679DA12FF725DBA74D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
