VALUES ('doc-04-nist-sp-800-86-p59-7', 'doc-04-nist-sp-800-86', '', 59, 'Occasionally, an analyst might come across a hard drive that also contains flash memory.', 'kb-doc-04-nist-sp-800-86-p59-7', 0, 14, '04-nist-sp-800-86', 'retrieved', 'D3706ACF21A4A54D38972B5D744DEB5B1F02F4DB72947A6C9DB32175C76C2B1D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
