VALUES ('doc-04-nist-sp-800-86-p59-8', 'doc-04-nist-sp-800-86', '', 59, 'This flash memory could contain a password that is needed to access the drive, even when the drive has been removed from the computer.', 'kb-doc-04-nist-sp-800-86-p59-8', 0, 24, '04-nist-sp-800-86', 'retrieved', '149E65D54472219957369D86DE698CB856AE12B4930F594740A352E88CC1BCB1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
