INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-9', 'doc-04-nist-sp-800-86', '', 59, 'Typically, the analyst must then find, guess, or crack the password to gain access to the drive.', 'kb-doc-04-nist-sp-800-86-p59-9', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A7CDA5EBF1ED7D3301981F9DD0D1B0129580FB098080CAAC39AB2315408C2F81', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-11', 'doc-04-nist-sp-800-86', '', 59, 'On some computers, individual keys or combinations of keystrokes can be remapped to perform a different function from their initial purpose.', 'kb-doc-04-nist-sp-800-86-p59-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '36544BDAB4473CC0732B36526B71E4E4C62463AF54968A287B3AA8F4D1E774F3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-12', 'doc-04-nist-sp-800-86', '', 59, 'For example, a person could map the Ctrl, Alt, and Del keys so that they wipe the computers hard drive instead of the expected action, rebooting the system.', 'kb-doc-04-nist-sp-800-86-p59-12', 0, 28, '04-nist-sp-800-86', 'retrieved', 'F5C8A6179973D045A760C88382A63FF7CFFAF9C084A76FBD5256CA585A545633', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-13', 'doc-04-nist-sp-800-86', '', 59, 'An analyst who uses the keyboard of a computer of interest could enter keystrokes that cause unexpected actions to be performed.', 'kb-doc-04-nist-sp-800-86-p59-13', 0, 21, '04-nist-sp-800-86', 'retrieved', 'E9547BE5068BEBC0057D826DCDAA1B2D306D183CA0D9D34EA6847A184747417B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-14', 'doc-04-nist-sp-800-86', '', 59, 'The best way to avoid key remapping problems is by collecting data from the computer without using its keyboard.', 'kb-doc-04-nist-sp-800-86-p59-14', 0, 19, '04-nist-sp-800-86', 'retrieved', '6A4FB858FC074A6C61960639013E1535D339EEF6E447096B813F91C4D6086A87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-15', 'doc-04-nist-sp-800-86', '', 59, 'For example, the analyst could attach a forensic workstation to a computer of interest using a crossover network cable and run scripts from the forensic workstation.', 'kb-doc-04-nist-sp-800-86-p59-15', 0, 26, '04-nist-sp-800-86', 'retrieved', 'C674F8ABB8959E9AB49B24B92797719830248AB3AFE3AE8014BD187C35E9FA48', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-16', 'doc-04-nist-sp-800-86', '', 59, '5.3 Examining and Analyzing OS Data Various tools and techniques can be used to support the examination process.', 'kb-doc-04-nist-sp-800-86-p59-16', 0, 18, '04-nist-sp-800-86', 'retrieved', 'A46D21247A2F2AF2E8C9E1FB2952405E1686751B596463401DC80B7CA0A6D3EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-17', 'doc-04-nist-sp-800-86', '', 59, 'Many of the tools and techniques discussed in Section 4.3 for examining collected data files can also be used with collected OS data.', 'kb-doc-04-nist-sp-800-86-p59-17', 0, 23, '04-nist-sp-800-86', 'retrieved', '42B50FE557D48171AC80D7E4258E12F5CC150C5AC0DDCA6AE8577DF2B13CB0DA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-18', 'doc-04-nist-sp-800-86', '', 59, 'In addition, as described in Section 7, security applications, such as file integrity checkers and host IDSs, can be very helpful in identifying malicious activity against OSs.', 'kb-doc-04-nist-sp-800-86-p59-18', 0, 27, '04-nist-sp-800-86', 'retrieved', '46CA1A42C3D990B57858123E200ADAA3096E8BC473DCB3C3F6A8173D678EC6A6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-19', 'doc-04-nist-sp-800-86', '', 59, 'For instance, file integrity checkers can be used to compute the message digests of OS files and compare them against databases of known message digests to determine whether any files have been compromised.', 'kb-doc-04-nist-sp-800-86-p59-19', 0, 33, '04-nist-sp-800-86', 'retrieved', '2617AEB7A0A94DE062E618980BC92CCD565D2AD1B41E00446BC4D22C872665E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-20', 'doc-04-nist-sp-800-86', '', 59, 'If intrusion detection software is installed on the computer, it might contain logs that indicate the actions performed against the OS.', 'kb-doc-04-nist-sp-800-86-p59-20', 0, 21, '04-nist-sp-800-86', 'retrieved', '5AE57734365FFEF2A6FB5711E27B8DC152520D34782FD3ED83239842B2EC95BB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-21', 'doc-04-nist-sp-800-86', '', 59, 'Another issue that analysts face is the examination of swap files and RAM dumps, which are large binary data files containing unstructured data.', 'kb-doc-04-nist-sp-800-86-p59-21', 0, 23, '04-nist-sp-800-86', 'retrieved', '310BA0042BCE7AB668851A94A22FD9E53CF72B0911D7465107FB57A7335B29DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-22', 'doc-04-nist-sp-800-86', '', 59, 'Hex editors can be used to open these files and examine their contents; however, on large files, manually trying to locate intelligible data using a hex editor can be a time-consuming process.', 'kb-doc-04-nist-sp-800-86-p59-22', 0, 32, '04-nist-sp-800-86', 'retrieved', '56ECE45C22CD4F4B1A7AA289A5EE5ED448F920767911F38627C3E71687C5F9D7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-23', 'doc-04-nist-sp-800-86', '', 59, 'Filtering tools automate the process of examining swap and RAM dump files by identifying text patterns and numerical values that might represent phone numbers, names of people, e- mail addresses, Web addresses, and other types of critical information.', 'kb-doc-04-nist-sp-800-86-p59-23', 0, 38, '04-nist-sp-800-86', 'retrieved', '85904B1D2F81C8BF258D0444EC67ED75F782A8E11FBDD7888CFC6AF974E729AC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-24', 'doc-04-nist-sp-800-86', '', 59, 'Analysts often want to gather additional information about a particular program running on a system, such as the processs purpose and manufacturer.', 'kb-doc-04-nist-sp-800-86-p59-24', 0, 22, '04-nist-sp-800-86', 'retrieved', '30F473B06DDE25E0327CB88CEF527A87148FE70F958642EDFF9A75B7B36C89B6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-25', 'doc-04-nist-sp-800-86', '', 59, 'After obtaining a list of the processes currently running on a system, analysts can look up the process name to obtain such additional information.', 'kb-doc-04-nist-sp-800-86-p59-25', 0, 24, '04-nist-sp-800-86', 'retrieved', '35D3C2C3104519B19C0611F61EDFE7AFA9D318ED5E54B527F2F1D97AA3DD8C0E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-26', 'doc-04-nist-sp-800-86', '', 59, 'However, users might change the names of programs to conceal their functions, such as naming a Trojan program calculator.exe.', 'kb-doc-04-nist-sp-800-86-p59-26', 0, 19, '04-nist-sp-800-86', 'retrieved', 'B2DB253D69D79ABFE5EA990A32E445E6C597FA9B3AF340432CB8EEC224A4B3BA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-27', 'doc-04-nist-sp-800-86', '', 59, 'Therefore, process name lookups should be performed only after verifying the identity of the processs files by computing and comparing their message digests.', 'kb-doc-04-nist-sp-800-86-p59-27', 0, 23, '04-nist-sp-800-86', 'retrieved', '99E59BCA5503C61934395A7E495BD6FD7AB1D9AE95ADA63CE94847CB4A857E3B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-28', 'doc-04-nist-sp-800-86', '', 59, 'Similar lookups can be performed on library files, such as DLLs on Windows systems, to determine which libraries are loaded and what their typical purposes are.', 'kb-doc-04-nist-sp-800-86-p59-28', 0, 26, '04-nist-sp-800-86', 'retrieved', '228370E3630D68977E80D082D7FE08F9AC8171AFD8CAF4B5CCF0BC2705706833', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-29', 'doc-04-nist-sp-800-86', '', 59, 'As described in Section 5.2, analysts may collect many different types of OS data, including multiple filesystems.', 'kb-doc-04-nist-sp-800-86-p59-29', 0, 17, '04-nist-sp-800-86', 'retrieved', '582B58D6A247E460B3887A6D9706C467CDE464F6CE9AE568A0992921D79AF802', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p59-30', 'doc-04-nist-sp-800-86', '', 59, 'Trying to sift through each type of data to find relevant information can be a time-intensive 5-11', 'kb-doc-04-nist-sp-800-86-p59-30', 0, 17, '04-nist-sp-800-86', 'retrieved', '9D0A4EB4AA1D19BD3CBF9AEBF667F39C47CCA9537B15D96D2B13CF4FEF783F00', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p60-2', 'doc-04-nist-sp-800-86', '', 60, 'Analysts generally find it useful to identify a few data sources to review initially, then find other likely sources of important information on the basis of that review.', 'kb-doc-04-nist-sp-800-86-p60-2', 0, 28, '04-nist-sp-800-86', 'retrieved', '993540F206C07A1F912B5F88A260AFAF273983AE01ACEA5E66A87A0C06DC5274', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p60-3', 'doc-04-nist-sp-800-86', '', 60, 'In addition, in many cases, analysis can involve data from other types of sources, such as network traffic or applications.', 'kb-doc-04-nist-sp-800-86-p60-3', 0, 20, '04-nist-sp-800-86', 'retrieved', '8A6A621C905D828CF4208B9DC94D0F170A5AD3DE652ABD86B82B3FCB2E6B6FD0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p60-4', 'doc-04-nist-sp-800-86', '', 60, 'Section 8 provides examples of how data from OSs and other sources can be correlated through analysis.', 'kb-doc-04-nist-sp-800-86-p60-4', 0, 17, '04-nist-sp-800-86', 'retrieved', '48409253251184739B72E03466E89E8C8A919C40ED546E6BCBD039000E872794', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p60-5', 'doc-04-nist-sp-800-86', '', 60, '5.4 Re commendations The key recommendations presented in this section for using data from OSs are as follows.', 'kb-doc-04-nist-sp-800-86-p60-5', 0, 18, '04-nist-sp-800-86', 'retrieved', 'EFFCCA4186DBF262D8469E2C7000FF9612DC08831108C2F657535A6C26EEF133', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p60-7', 'doc-04-nist-sp-800-86', '', 60, 'The criteria for determining whether volatile OS data must be preserved should be documented in advance so that analysts can make informed decisions as quickly as possible.', 'kb-doc-04-nist-sp-800-86-p60-7', 0, 27, '04-nist-sp-800-86', 'retrieved', 'F548832052682CF261D47CB450331C29F8534A7B4962993CF54143CA1F6AF9DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
