INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p60-8', 'doc-04-nist-sp-800-86', '', 60, 'To determine whether the effort required to collect volatile OS data is warranted, the risks associated with such collection should be weighed against the potential for recovering important information.', 'kb-doc-04-nist-sp-800-86-p60-8', 0, 29, '04-nist-sp-800-86', 'retrieved', 'BA21FC764C5CCFF9DEEA4972B97639A527190D34B489501D726AAC21D6013B74', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
