VALUES ('doc-04-nist-sp-800-86-p60-10', 'doc-04-nist-sp-800-86', '', 60, 'Use of a forensic toolkit enables accurate OS data to be collected while minimizing the disturbance to the system and protecting the tools from changes.', 'kb-doc-04-nist-sp-800-86-p60-10', 0, 25, '04-nist-sp-800-86', 'retrieved', 'C65A1A063523EA633FF3AAA429580F96BDDCEEC79C4EDED8DEDE70103A1081D2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
