VALUES ('doc-04-nist-sp-800-86-p60-11', 'doc-04-nist-sp-800-86', '', 60, 'The analyst should know how each tool is likely to affect or alter the system during collection of data.', 'kb-doc-04-nist-sp-800-86-p60-11', 0, 19, '04-nist-sp-800-86', 'retrieved', 'B72DB8FB4C4440BB36B6E6446C93244B3188624E520E128B7DCE733A46B3856E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
