VALUES ('doc-04-nist-sp-800-86-p60-13', 'doc-04-nist-sp-800-86', '', 60, 'Each method of shutting down a particular OS can cause different types of data to be preserved or corrupted; analysts should be aware of the typical shutdown behavior of each OS.', 'kb-doc-04-nist-sp-800-86-p60-13', 0, 31, '04-nist-sp-800-86', 'retrieved', 'AA548F13BE40BA40A2F3398CC4E876284248BD5AB50E8604ABA528D0A52BC881', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
