VALUES ('doc-04-nist-sp-800-86-p61-1', 'doc-04-nist-sp-800-86', '', 61, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 6. Using Data From Network Traffic Analysts can use data from network traffic to reconstruct and analyze network-based attacks and inappropriate network usage, as well as to troubleshoot various types of operational problems.', 'kb-doc-04-nist-sp-800-86-p61-1', 0, 41, '04-nist-sp-800-86', 'retrieved', 'F33578FEA7D20EA0EB0E0E942A88AEB20D6CC291EFA15355ED9E28EE07937023', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
