INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-2', 'doc-04-nist-sp-800-86', '', 61, 'The content of communications carried over networks, such as e-mail messages or audio, might also be collected in support of an investigation.', 'kb-doc-04-nist-sp-800-86-p61-2', 0, 22, '04-nist-sp-800-86', 'retrieved', '7CF190F763BE5B776C1B6636129A2FAD4020E6EBFDB25819E00E6F1BC720B4B8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
