INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-3', 'doc-04-nist-sp-800-86', '', 61, 'The term network traffic refers to computer network communications that are carried over wired or wireless networks between hosts.82 This section provides an introduction to network traffic, including descriptions of major sources of network traffic data (e.g., intrusion detection software, firewalls).', 'kb-doc-04-nist-sp-800-86-p61-3', 0, 41, '04-nist-sp-800-86', 'retrieved', '249105C1ED0817DAE43497035119D5FEA7DC91E633CF26DF7AD9BC399864291D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
