VALUES ('doc-04-nist-sp-800-86-p61-4', 'doc-04-nist-sp-800-86', '', 61, 'In addition, it discusses techniques for collecting data from these sources and points out the potential legal and technical issues in such data collection.', 'kb-doc-04-nist-sp-800-86-p61-4', 0, 24, '04-nist-sp-800-86', 'retrieved', '010471E63EAE3B3DB35A9839CC4AB91F3C63ECD5411A9E63473E3DE44FE38D6B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
