VALUES ('doc-04-nist-sp-800-86-p61-5', 'doc-04-nist-sp-800-86', '', 61, 'The remainder of the section focuses on the techniques and tools for examining and analyzing data from network traffic.', 'kb-doc-04-nist-sp-800-86-p61-5', 0, 19, '04-nist-sp-800-86', 'retrieved', '1874479EDAF08CA5467A34A5DBCDAD0D59328DE8528E44EC9570656DE472D8F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
