INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-6', 'doc-04-nist-sp-800-86', '', 61, 'The section begins with an overview of Transmission Control Protocol/Internet Protocol (TCP/IP)a basic knowledge of TCP/IP is necessary to understand the data, tools, and methodologies presented in this section.', 'kb-doc-04-nist-sp-800-86-p61-6', 0, 29, '04-nist-sp-800-86', 'retrieved', '0BB998FB206065078B802F77A06A01EB1A9E92A6A62C44F95F12B7481E83EA53', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
