INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-7', 'doc-04-nist-sp-800-86', '', 61, '6.1 T CP/IP Basics TCP/IP is widely used throughout the world to provide network communications.', 'kb-doc-04-nist-sp-800-86-p61-7', 0, 15, '04-nist-sp-800-86', 'retrieved', 'B2CD9E231C7D8AB46E340F87D79C5B7A602D163B23AE98104008ED1B27B2D369', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
