INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-9', 'doc-04-nist-sp-800-86', '', 61, 'When a user wants to transfer data across networks, the data is passed from the highest layer through intermediate layers to the lowest layer, with each layer adding additional information.', 'kb-doc-04-nist-sp-800-86-p61-9', 0, 30, '04-nist-sp-800-86', 'retrieved', '356C2A91353875A660B9800C1321E33B27FA6AE217D995C5B5CF66D004BB559A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-10', 'doc-04-nist-sp-800-86', '', 61, 'The lowest layer sends the accumulated data through the physical network; the data is then passed up through the layers to its destination.', 'kb-doc-04-nist-sp-800-86-p61-10', 0, 23, '04-nist-sp-800-86', 'retrieved', '601D61CE27FB95BDC98B25AB36E903EEC7EFAD60D71E68BB725C877F3CF6A8A8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-11', 'doc-04-nist-sp-800-86', '', 61, 'Essentially, the data produced by a layer is encapsulated in a larger container by the layer below it.', 'kb-doc-04-nist-sp-800-86-p61-11', 0, 18, '04-nist-sp-800-86', 'retrieved', '62CBB8B63F34DF6FD1479E50757DDC9C35B9686D257EDA1D3A7CCC4832AD043C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-14', 'doc-04-nist-sp-800-86', '', 61, 'This layer sends and receives data for particular applications, such as Domain Name System (DNS), Hypertext Transfer Protocol (HTTP), and Simple Mail Transfer Protocol (SMTP).', 'kb-doc-04-nist-sp-800-86-p61-14', 0, 25, '04-nist-sp-800-86', 'retrieved', '3AC9A16DB93F697FDF03D82B1E524F9089C9B28E7CC934F5B318AF8002E87934', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-16', 'doc-04-nist-sp-800-86', '', 61, 'This layer provides connection-oriented or connectionless services for transporting application layer services between networks.', 'kb-doc-04-nist-sp-800-86-p61-16', 0, 14, '04-nist-sp-800-86', 'retrieved', '78AABD9C40FF81160B5BE53A49E1A3C90C3FF72177F88E87418411B34A05642B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-18', 'doc-04-nist-sp-800-86', '', 61, 'Transmission Control Protocol (TCP) and User Datagram Protocol (UDP) are commonly used transport layer protocols.', 'kb-doc-04-nist-sp-800-86-p61-18', 0, 15, '04-nist-sp-800-86', 'retrieved', '8468808BE44FC3C340A6AAA674D00616E7EA7BA40036DD0577DE3EA25CBE8A63', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
