INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-22', 'doc-04-nist-sp-800-86', '', 61, 'Other commonly used protocols at the network layer are Internet Control Message Protocol (ICMP) and Internet Group Management Protocol (IGMP).', 'kb-doc-04-nist-sp-800-86-p61-22', 0, 20, '04-nist-sp-800-86', 'retrieved', '9330D9976958932FBAFE19129ED11991A7B76A54F3C7CB69E2EFC6744F2922BA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-31', 'doc-04-nist-sp-800-86', '', 61, '82 Because nearly all network traffic of interest to organizations uses the TCP/IP protocol suite, this section addresses only TCP/IP-based communications.', 'kb-doc-04-nist-sp-800-86-p61-31', 0, 21, '04-nist-sp-800-86', 'retrieved', '04BCD4EE0EC6F4BE76A21D361B46C2F53F279390B0C65BB77281810AD245359F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p61-32', 'doc-04-nist-sp-800-86', '', 61, 'However, most of the principles discussed in this section can be applied to other types of network traffic as well.', 'kb-doc-04-nist-sp-800-86-p61-32', 0, 20, '04-nist-sp-800-86', 'retrieved', '201E7BF2FA2652504DEBB75759EDB0B3F354625EFCF63B328AEC1D33AE0242AA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
