VALUES ('doc-04-nist-sp-800-86-p62-1', 'doc-04-nist-sp-800-86', '', 62, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE indicate the characteristics that are most pertinent to network forensics.', 'kb-doc-04-nist-sp-800-86-p62-1', 0, 18, '04-nist-sp-800-86', 'retrieved', '3D31B033E6F7C2EE01551F7A073B1DEEF0C461F7E8B3CFD20ACBD12FD1F6B1CA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
