VALUES ('doc-04-nist-sp-800-86-p62-6', 'doc-04-nist-sp-800-86', '', 62, 'Application Layer The application layer enables applications to transfer data between an application server and client.', 'kb-doc-04-nist-sp-800-86-p62-6', 0, 16, '04-nist-sp-800-86', 'retrieved', 'A282D45A42C3AE01B54133EB62929CB2AA06D8B45130ACF68A113EA0EDAE99F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
