INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-7', 'doc-04-nist-sp-800-86', '', 62, 'An example of an application layer protocol is Hypertext Transfer Protocol (HTTP), which transfers data between a Web server and a Web browser.', 'kb-doc-04-nist-sp-800-86-p62-7', 0, 23, '04-nist-sp-800-86', 'retrieved', 'F2774810E5C4CA6E1C171C35D66C39999E07B6750BFE6073BB9E857F9D893507', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-8', 'doc-04-nist-sp-800-86', '', 62, 'Other common application layer protocols include Domain Name System (DNS), File Transfer Protocol (FTP), Simple Mail Transfer Protocol (SMTP), and Simple Network Management Protocol (SNMP).', 'kb-doc-04-nist-sp-800-86-p62-8', 0, 25, '04-nist-sp-800-86', 'retrieved', 'A81A1CBFB68916DFC765B62F1169014B6BFE742E32C45969F699B88D6E98395A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-9', 'doc-04-nist-sp-800-86', '', 62, 'There are hundreds of unique application layer protocols in common use, and many more that are not so common.83 Regardless of the protocol in use, application data is generated and then passed to the transport layer for further processing.', 'kb-doc-04-nist-sp-800-86-p62-9', 0, 39, '04-nist-sp-800-86', 'retrieved', 'BA95C7B14DE294C5062C9EF7F9AE032701DBA035FA680E64FA60E711C181E303', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
