VALUES ('doc-04-nist-sp-800-86-p62-10', 'doc-04-nist-sp-800-86', '', 62, 'Section 7 focuses on application-related data collection, examination, and analysis.', 'kb-doc-04-nist-sp-800-86-p62-10', 0, 10, '04-nist-sp-800-86', 'retrieved', 'A78840297A7EE1C253EADB27BE15804E7D7C9D6EA5826420B81DB5CC93654951', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
