INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-11', 'doc-04-nist-sp-800-86', '', 62, 'Transport Layer The transport layer is responsible for packaging data so that it can be transmitted between hosts.', 'kb-doc-04-nist-sp-800-86-p62-11', 0, 18, '04-nist-sp-800-86', 'retrieved', '23E2EC6C57CD2ABA78D82D6E58BC16BC500F9710E9C1708923D8FF3064CDB9EF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-12', 'doc-04-nist-sp-800-86', '', 62, 'After the transport layer has encapsulated application data, the resulting logical units are referred to as packets.', 'kb-doc-04-nist-sp-800-86-p62-12', 0, 17, '04-nist-sp-800-86', 'retrieved', 'DC5776CDDE8C697245B2C21AA3F7EB336AFFE5F7985A30A7DC9EA45767230D05', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-13', 'doc-04-nist-sp-800-86', '', 62, '(A packet can also be created without application datafor example, when a connection is first negotiated.) Each packet contains a header, which is composed of various fields that specify characteristics of the transport protocol in use; optionally, packets may also contain a payload, which holds the application data.', 'kb-doc-04-nist-sp-800-86-p62-13', 0, 48, '04-nist-sp-800-86', 'retrieved', '714E5B3FCAE9C56C0FB00D7A741D4CFBD5D6B63CC02AC7C55406C07A975F3DC1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-14', 'doc-04-nist-sp-800-86', '', 62, 'Most applications that communicate over networks rely on the transport layer to ensure reliable delivery of data.', 'kb-doc-04-nist-sp-800-86-p62-14', 0, 17, '04-nist-sp-800-86', 'retrieved', '39A3F7305C031D7F1AB92F4DFD32852AC015839BF277C40694DE15B26CACFFB2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-15', 'doc-04-nist-sp-800-86', '', 62, 'Generally, this is accomplished by using the TCP transport layer protocol, which establishes a connection between two hosts and then makes a best effort to ensure the reliable transfer of data over that connection.', 'kb-doc-04-nist-sp-800-86-p62-15', 0, 34, '04-nist-sp-800-86', 'retrieved', '57BF26714E0E978FEE832C55ECC9BF60011CAEB4E09B3C0B85C99A5902013618', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-17', 'doc-04-nist-sp-800-86', '', 62, 'One of the ports is associated with a server application on one system; the other port is associated with a corresponding client application on the other system.', 'kb-doc-04-nist-sp-800-86-p62-17', 0, 27, '04-nist-sp-800-86', 'retrieved', '026E3B538F549B4FF4092D077BBA85FBC7D5BB79EA3D9F89D096B0340FE9F5B5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-18', 'doc-04-nist-sp-800-86', '', 62, 'Client systems typically select any available port number for application use, whereas server systems normally have a static port number dedicated to each application.', 'kb-doc-04-nist-sp-800-86-p62-18', 0, 24, '04-nist-sp-800-86', 'retrieved', 'A02A27D9446147BA1D25B2261C537268586AEF9F4F5B98DAD94A16A7561AC659', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-19', 'doc-04-nist-sp-800-86', '', 62, 'Although many server ports are usually used by particular applications (e.g., FTP servers at port 21, HTTP servers', 'kb-doc-04-nist-sp-800-86-p62-19', 0, 18, '04-nist-sp-800-86', 'retrieved', '25B5313839CC45DA7FCED0CDB2D4A0B0197BF1AA5BBA03CD4C69DE98EA568A47', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p62-20', 'doc-04-nist-sp-800-86', '', 62, '83 For this reason, a detailed discussion of individual application layer protocols is beyond the scope of this document.', 'kb-doc-04-nist-sp-800-86-p62-20', 0, 19, '04-nist-sp-800-86', 'retrieved', 'D505D2E5CAC043695397A93C50BB5DBB45D930BFF027778362E8668B8D126BAC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
