INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-1', 'doc-04-nist-sp-800-86', '', 63, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE at port 80), many server applications can be run from any port number, so it is unwise to assume that network traffic contains data from a certain application solely on the basis of server port number.', 'kb-doc-04-nist-sp-800-86-p63-1', 0, 44, '04-nist-sp-800-86', 'retrieved', '88643A123FE97B8101E8D5B233BF7D4BC0A22732CC4578F7F2C3131960174AED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-2', 'doc-04-nist-sp-800-86', '', 63, 'When loss of some application data is not a concern (e.g., streaming audio, video), the User Datagram Protocol (UDP) is typically used.', 'kb-doc-04-nist-sp-800-86-p63-2', 0, 22, '04-nist-sp-800-86', 'retrieved', '983C1D4693D5093B786BA4A93912720A6EBE158FA7C0D7713904C2357A466878', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-3', 'doc-04-nist-sp-800-86', '', 63, 'UDP involves less overhead and latency than TCP because UDP is connectionless; one host simply sends data to another host without any preliminary negotiations.', 'kb-doc-04-nist-sp-800-86-p63-3', 0, 24, '04-nist-sp-800-86', 'retrieved', 'D352ACE81940E8609FC8F8FDB2B80EC9B2884F4C521A1A70604DC71E050C7465', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-4', 'doc-04-nist-sp-800-86', '', 63, 'UDP is also used for applications that are willing to take responsibility for ensuring reliable delivery of data, such as DNS, and applications that are intended for use only on local area networks, such as Dynamic Host Configuration Protocol (DHCP) and SNMP.', 'kb-doc-04-nist-sp-800-86-p63-4', 0, 42, '04-nist-sp-800-86', 'retrieved', '8491CC8DFAA478F9C109832FBC0306CB2095F407100CA255CFEBA8AD12E734BA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-5', 'doc-04-nist-sp-800-86', '', 63, 'As is the case with TCP, each UDP packet contains a source port and a destination port.', 'kb-doc-04-nist-sp-800-86-p63-5', 0, 17, '04-nist-sp-800-86', 'retrieved', 'AC1D162497AA81CB41DDFD4D2EFC06C7D55100D9B47A15C93FE87BB925615556', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-6', 'doc-04-nist-sp-800-86', '', 63, 'Although UDP and TCP ports are very similar, they are distinct from each other and are not interchangeable.', 'kb-doc-04-nist-sp-800-86-p63-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '14DB3BDF426C828B9BB982006B15785EC1A5AFF5C1E0258537DD5EAE41DBB609', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-7', 'doc-04-nist-sp-800-86', '', 63, 'Some applications (such as DNS) can use both TCP and UDP ports; although such applications typically use the same number for the TCP port and the UDP port, this is not required.', 'kb-doc-04-nist-sp-800-86-p63-7', 0, 32, '04-nist-sp-800-86', 'retrieved', '9B6D52359714D12726880F13FAF9A8C7FA0268E0D022E36950DD00CF1A0EC9C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-9', 'doc-04-nist-sp-800-86', '', 63, 'IP Layer The IP layer can also be called the network layer, because it is responsible for handling the addressing and routing of data that it receives from the transport layer.', 'kb-doc-04-nist-sp-800-86-p63-9', 0, 31, '04-nist-sp-800-86', 'retrieved', 'DF82C78E5DF9F593F02C1ACF93B37632C527AC2CBBB2A0C3BBB5A5A7C95A5FB7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-10', 'doc-04-nist-sp-800-86', '', 63, 'The IP header contains a field called IP Version, which indicates which version of IP is in use.', 'kb-doc-04-nist-sp-800-86-p63-10', 0, 18, '04-nist-sp-800-86', 'retrieved', '68FB63E20ACD63BD007CC1186E534BBF84EEF4F55D75721AD211B8A89DCBAE68', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-11', 'doc-04-nist-sp-800-86', '', 63, 'Typically this is set to 4 for IPv4; but the use of IPv6 is increasing, so this field may be set to 6 instead.84 Other significant IP header fields are as follows: ! Source and Destination IP Addresses.', 'kb-doc-04-nist-sp-800-86-p63-11', 0, 38, '04-nist-sp-800-86', 'retrieved', '1E8AB9E01C356658EE269F4E10C324EDEBA6A44768978E64BEAA6FAB2A2FA89D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-12', 'doc-04-nist-sp-800-86', '', 63, 'These are the from and to addresses that are intended to indicate the endpoints of the communication.85 Examples of IP addresses are 10.3.1.70 (IPv4) and 1000:0:0:2F:8A:400:0427:9BD1 (IPv6).', 'kb-doc-04-nist-sp-800-86-p63-12', 0, 27, '04-nist-sp-800-86', 'retrieved', 'E9519DA8B682D357CE7E0ACCB370265FD97B5AA2BCB79C3AA43961DD5933DC2D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-14', 'doc-04-nist-sp-800-86', '', 63, 'This indicates which transport layer protocol the IP payload contains.86 Commonly used IP numbers include 1 (Internet Control Message Protocol [ICMP]), 6 (TCP), 17 (UDP), and 50 (Encapsulating Security Payload [ESP]).', 'kb-doc-04-nist-sp-800-86-p63-14', 0, 31, '04-nist-sp-800-86', 'retrieved', 'EB9ABCB6895AED14FDFFDC2A789EE5EEC56C259DAAE9B204B62D495A39142196', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-15', 'doc-04-nist-sp-800-86', '', 63, 'The IP layer is also responsible for providing error and status information involving the addressing and routing of data; it does this with ICMP.', 'kb-doc-04-nist-sp-800-86-p63-15', 0, 24, '04-nist-sp-800-86', 'retrieved', '4EC0ED0CC27849AB845C6AA983467646D8E8FBF1D940FDE4CAE24341F938C8F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-16', 'doc-04-nist-sp-800-86', '', 63, 'ICMP is a connectionless protocol that makes no attempt to guarantee that its error and status messages are delivered.', 'kb-doc-04-nist-sp-800-86-p63-16', 0, 19, '04-nist-sp-800-86', 'retrieved', '4719F80FCE2398020454AC5D716191A1F3695549B4282431BA8CD71CF38041A0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
