INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-17', 'doc-04-nist-sp-800-86', '', 63, 'Because it is designed to transfer limited information, not application data, ICMP does not have ports; instead, it has message types, which indicate the purpose of each ICMP message.87 Some message types also have message codes, which can be thought of as subtypes.', 'kb-doc-04-nist-sp-800-86-p63-17', 0, 43, '04-nist-sp-800-86', 'retrieved', '1E49C29D7D2FD664B4F0517E5D09AAB298F6F1E6CF1CAF10BEE06AEE4F41D31A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-18', 'doc-04-nist-sp-800-86', '', 63, 'For example, the ICMP message type Destination Unreachable has several possible message codes that indicate what is unreachable (e.g., network, host, protocol).', 'kb-doc-04-nist-sp-800-86-p63-18', 0, 22, '04-nist-sp-800-86', 'retrieved', '1D299D3A8B95194F11E5B912D32C47C4E46AFDC2A9ACB09BEF1C20B9D0200079', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-19', 'doc-04-nist-sp-800-86', '', 63, 'Most ICMP messages are not intended to elicit a response.88 IP addresses are often used through a layer of indirection.', 'kb-doc-04-nist-sp-800-86-p63-19', 0, 20, '04-nist-sp-800-86', 'retrieved', '556B6282D44B2B2C9FBAF3CADB137C9E9707B489049732A666F7B42776FFA5AB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-20', 'doc-04-nist-sp-800-86', '', 63, 'When people need to access a resource on a network, such as a Web server or e-mail server, they typically enter the servers name, such as www.nist.gov, rather than the servers IP address.', 'kb-doc-04-nist-sp-800-86-p63-20', 0, 33, '04-nist-sp-800-86', 'retrieved', 'BF5F40560454467AF402099CAB1D41C378F8FF47EF0A83626D173F1BF646F3DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-22', 'doc-04-nist-sp-800-86', '', 63, '84 There are other possible IP version numbers as well, although none are commonly used.', 'kb-doc-04-nist-sp-800-86-p63-22', 0, 15, '04-nist-sp-800-86', 'retrieved', 'BD86B16779F8B251595E356D2572489563AD0394012312CA46B87720C7A5D26A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-23', 'doc-04-nist-sp-800-86', '', 63, 'The official list of valid IP Version field values is available at http://www.iana.org/assignments/version-numbers. This document assumes the use of IPv4, but the techniques described can easily be adapted for use with IPv6 (assuming that comparable tools are available that support IPv6).', 'kb-doc-04-nist-sp-800-86-p63-23', 0, 41, '04-nist-sp-800-86', 'retrieved', 'C7CFEB71447982DAD6DBC7D0B859F59FBF6497C93CE6A74F8D74DBC897730065', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-24', 'doc-04-nist-sp-800-86', '', 63, '85 IP addresses are often inaccurate or misleading for identifying the actual endpoints of communication.', 'kb-doc-04-nist-sp-800-86-p63-24', 0, 15, '04-nist-sp-800-86', 'retrieved', '7CC0452751EE49E030EE3050BE3D2A0C62E0B7A614DF13035290AE25574817C4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
