INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-26', 'doc-04-nist-sp-800-86', '', 63, '86 The official list of valid IP Protocol Number values is available at http://www.iana.org/assignments/protocol-numbers.', 'kb-doc-04-nist-sp-800-86-p63-26', 0, 14, '04-nist-sp-800-86', 'retrieved', 'D9499C3A6357FA741A1497C305BB4571EA47ED31965B55BCE3504C674976CE21', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
