INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-27', 'doc-04-nist-sp-800-86', '', 63, '87 The current list of valid ICMP types is available at http://www.iana.org/assignments/icmp-parameters.', 'kb-doc-04-nist-sp-800-86-p63-27', 0, 12, '04-nist-sp-800-86', 'retrieved', '99214C0CFECAC22915F1ABDC87583FAA3DB5B5E836A623674B3D976515279298', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p63-30', 'doc-04-nist-sp-800-86', '', 63, 'For example, if Host A received an ICMP error message from Host B and responded with an error message, and Host B responded to that error message with an error message, the two hosts could continue sending error messages regarding the error messages.', 'kb-doc-04-nist-sp-800-86-p63-30', 0, 43, '04-nist-sp-800-86', 'retrieved', '7150FDADCFD4332BCD97077A5E813B6C8F8F87145DAEDF329D8915AD6E838574', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-1', 'doc-04-nist-sp-800-86', '', 64, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE to the IP address through the DNS application layer protocol.', 'kb-doc-04-nist-sp-800-86-p64-1', 0, 18, '04-nist-sp-800-86', 'retrieved', 'CEE38DC599D446875073FB3BE393689D024E91283D2941A83196915A9F443DBF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-2', 'doc-04-nist-sp-800-86', '', 64, 'The primary reason for entering a domain name instead of an IP address is that the former is generally easier for people to remember.', 'kb-doc-04-nist-sp-800-86-p64-2', 0, 24, '04-nist-sp-800-86', 'retrieved', '6FCAFBD0E31EEF3CD2AC73FE1AD12E9EE596E6C7F3172DBEF97AAAA8B58DD0E3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-3', 'doc-04-nist-sp-800-86', '', 64, 'In addition, where a domain name is likely to remain the same, a hosts IP address can change over time; by referencing a host by domain name, which is then mapped to the hosts IP address, users can reach the host no matter what IP address the host is currently using.', 'kb-doc-04-nist-sp-800-86-p64-3', 0, 51, '04-nist-sp-800-86', 'retrieved', '4C3C07B098EEF35EEDEF6342D55F1AC1C175B5F5DFB4F3811A2514B6E55DEED4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-5', 'doc-04-nist-sp-800-86', '', 64, 'Hardware Layer As the name implies, the hardware layer involves the physical components of the network, including cables, routers, switches, and NIC.', 'kb-doc-04-nist-sp-800-86-p64-5', 0, 22, '04-nist-sp-800-86', 'retrieved', 'F34218C39A5DCB451C8BC8B61B27069231D8EAE47236ED151C50F92F39E327F0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-6', 'doc-04-nist-sp-800-86', '', 64, 'The hardware layer also includes various hardware layer protocols; Ethernet is the most widely used of these protocols.', 'kb-doc-04-nist-sp-800-86-p64-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '20BFDA016586075DDDAF6D5D7C2A6FDCF37F87B0B8907A521F5F49F89EBB8392', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-7', 'doc-04-nist-sp-800-86', '', 64, 'Ethernet relies on the concept of a MAC address, which is a unique 6-byte value (such as 00-02-B4-DA-92-2C) that is permanently assigned to a particular NIC.89 Each frame contains two MAC addresses, which indicate the MAC address of the NIC that just routed the frame and the MAC address of the next NIC to which the frame is being sent.', 'kb-doc-04-nist-sp-800-86-p64-7', 0, 60, '04-nist-sp-800-86', 'retrieved', '31C7A250BEB2343C4CBE6658421944BB3AAFCE621F6EC1B28289040870372EBC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-8', 'doc-04-nist-sp-800-86', '', 64, 'As a frame passes through networking equipment (such as routers and firewalls) on its way between the original source host and the final destination host, the MAC addresses are updated to refer to the local source and destination.', 'kb-doc-04-nist-sp-800-86-p64-8', 0, 38, '04-nist-sp-800-86', 'retrieved', '585F1DE1FF1AAF631D7705E1247CFA40AA06A3DC3763136F83F2BEF9D6240752', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-9', 'doc-04-nist-sp-800-86', '', 64, 'Several separate hardware layer transmissions may be linked together within a single IP layer transmission.', 'kb-doc-04-nist-sp-800-86-p64-9', 0, 15, '04-nist-sp-800-86', 'retrieved', '694C383D34C9A0B8B90C5B70B2F03B40A47D633D25FA28EE41AF00DAA393C20F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-10', 'doc-04-nist-sp-800-86', '', 64, 'In addition to the MAC addresses, each frame also contains an EtherType value, which indicates the protocol that the frames payload contains (typically IP or Address Resolution Protocol [ARP]).90 When IP is used, each IP address maps to a particular MAC address.', 'kb-doc-04-nist-sp-800-86-p64-10', 0, 42, '04-nist-sp-800-86', 'retrieved', '900B7FBCB10CFF49441746E72E3C20BAC40AF9F7A528EF97E7B223685D45AC1F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-11', 'doc-04-nist-sp-800-86', '', 64, '(Because multiple IP addresses can map to a single MAC address, a MAC address does not necessarily uniquely identify an IP address.) Layers Significance in Network Forensics Each of the four layers of the TCP/IP protocol suite contains important information.', 'kb-doc-04-nist-sp-800-86-p64-11', 0, 40, '04-nist-sp-800-86', 'retrieved', '4132B82A9EBB22BA3A907EA5771018CD1CF9EB1C8AEB4B2094CB4D5CCFC6E5EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-12', 'doc-04-nist-sp-800-86', '', 64, 'The hardware layer provides information about physical components, while other layers describe logical aspects.', 'kb-doc-04-nist-sp-800-86-p64-12', 0, 14, '04-nist-sp-800-86', 'retrieved', '8492E527C99D65EE3E9276B679A645725637A3B62FF81A0BC790A15EEA32625F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-13', 'doc-04-nist-sp-800-86', '', 64, 'For events within a network, an analyst can map an IP address (logical identifier at the IP layer) to the MAC address of a particular NIC (physical identifier at the physical layer), thereby identifying a host of interest.', 'kb-doc-04-nist-sp-800-86-p64-13', 0, 38, '04-nist-sp-800-86', 'retrieved', '83AD8663018D9675CF981E5CFDCA22546523127819C691FABD6A745738E31E5C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-14', 'doc-04-nist-sp-800-86', '', 64, 'The combination of the IP protocol number (IP layer field) and port numbers (transport layer fields) can tell an analyst which application was most likely being used or targeted.', 'kb-doc-04-nist-sp-800-86-p64-14', 0, 29, '04-nist-sp-800-86', 'retrieved', '0E1F243998E902AC2132803155CE3FB95521BDEB002FC5FD45579D58B5490CC2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-17', 'doc-04-nist-sp-800-86', '', 64, 'When analysts begin to examine data, they typically have limited informationmost likely an IP address of interest and perhaps protocol and port information.', 'kb-doc-04-nist-sp-800-86-p64-17', 0, 23, '04-nist-sp-800-86', 'retrieved', 'BA18A397296264D7328798F3736CB102F42E4A55C8914B17671B318C8B55DCC3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-18', 'doc-04-nist-sp-800-86', '', 64, 'Nevertheless, this is enough information to support searching common data sources for more information.', 'kb-doc-04-nist-sp-800-86-p64-18', 0, 14, '04-nist-sp-800-86', 'retrieved', '006D59C90DEAA6D9BE9A9C0188AE479E8F01E7C2ECFD747ED98DE5DB2A2000D4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-19', 'doc-04-nist-sp-800-86', '', 64, 'In most cases, the application layer contains the actual activity of interestmost attacks are against vulnerabilities in applications (including services), and nearly all misuse involves misuse of applications.', 'kb-doc-04-nist-sp-800-86-p64-19', 0, 28, '04-nist-sp-800-86', 'retrieved', '70F72D9F9C702B75C6C0A4994301B951DBB26058F053B88CA88A5B2D015BEF33', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-20', 'doc-04-nist-sp-800-86', '', 64, 'Analysts need IP addresses so that they can identify the hosts that may have been involved in the activity.', 'kb-doc-04-nist-sp-800-86-p64-20', 0, 19, '04-nist-sp-800-86', 'retrieved', '5E70604D3BEAB509701333F43E5D51A8D2E09A585158755721A08EBE4BE60C2B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-21', 'doc-04-nist-sp-800-86', '', 64, 'The hosts may also contain additional data that would be of use in analyzing the activity.', 'kb-doc-04-nist-sp-800-86-p64-21', 0, 16, '04-nist-sp-800-86', 'retrieved', '9F06A37DF06EBE8ACCA6A7C71EF442A8FC60213DE7C30BFCDD67589E60059434', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-22', 'doc-04-nist-sp-800-86', '', 64, 'Although some events of interest may not have relevant application-level data (e.g., a distributed denial of service attack designed to consume all network bandwidth), most do; network forensics provides important support to the analysis of application-layer activities.', 'kb-doc-04-nist-sp-800-86-p64-22', 0, 37, '04-nist-sp-800-86', 'retrieved', 'CF7F5BDDABACB5D6FA9A1448B41C1D5452E505BA67F4C597DD15E03C40191C1E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
