VALUES ('doc-04-nist-sp-800-86-p64-23', 'doc-04-nist-sp-800-86', '', 64, '89 The first 3 bytes of each MAC address indicate the vendor of the NIC; a list of mappings is available at http://standards.ieee.org/regauth/oui/oui.txt.', 'kb-doc-04-nist-sp-800-86-p64-23', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B400F7A263E87CB1C02F59AED52ED08E10FA70380E75A131C4CC67C4ADBA0F77', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
