INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-24', 'doc-04-nist-sp-800-86', '', 64, 'However, various software utilities are publicly available that allow people to configure systems to spoof other MAC addresses.', 'kb-doc-04-nist-sp-800-86-p64-24', 0, 18, '04-nist-sp-800-86', 'retrieved', '780D7B35695E6A1CEFB300F2782489E82CBF5CCB552774811E00C42525F1BDAE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
