INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p64-25', 'doc-04-nist-sp-800-86', '', 64, 'There have also been cases in which manufacturers accidentally created NICs with duplicate MAC addresses.', 'kb-doc-04-nist-sp-800-86-p64-25', 0, 15, '04-nist-sp-800-86', 'retrieved', '79FBD4875B81EAE63D886EA2A677E99CF97D4A90BB4124E48C8F0D6EBD5C2032', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
