VALUES ('doc-04-nist-sp-800-86-p64-27', 'doc-04-nist-sp-800-86', '', 64, 'See http://www.iana.org/assignments/ethernet-numbers for more information on EtherType values.', 'kb-doc-04-nist-sp-800-86-p64-27', 0, 8, '04-nist-sp-800-86', 'retrieved', '353D458C377CE17342B61D0D4389B348DBADE546AD411299E65522B7C1C8E8BF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
