INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-1', 'doc-04-nist-sp-800-86', '', 65, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 6.2 Network Traffic Data Sources Organizations typically have several types of information sources concerning network traffic that might be useful for network forensics.', 'kb-doc-04-nist-sp-800-86-p65-1', 0, 31, '04-nist-sp-800-86', 'retrieved', 'F4B1EBF7C164E6F798819DCC096929FB2555B2B0379B0F6A1DB3585ED45D0E74', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-3', 'doc-04-nist-sp-800-86', '', 65, 'The following subsections highlight the major categories of network traffic data sources firewalls and routers, packet sniffers and protocol analyzers, IDSs, remote access, security event management software, and network forensic analysis toolsas well as several other types of data sources.', 'kb-doc-04-nist-sp-800-86-p65-3', 0, 40, '04-nist-sp-800-86', 'retrieved', 'F6EC3AE1316C7629737B4AB7B90208AEDAF28C7ADA743AAC1BD078035A2359CC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-4', 'doc-04-nist-sp-800-86', '', 65, 'The subsections explain the purpose of each source described and the type of data that is typically collected and can potentially be collected.', 'kb-doc-04-nist-sp-800-86-p65-4', 0, 23, '04-nist-sp-800-86', 'retrieved', 'A09072B91D1804D0140747FEA15B7ABEBDF4188C36542B327D18A26EEA0293E4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-6', 'doc-04-nist-sp-800-86', '', 65, 'Firewalls and Routers Network-based devices such as firewalls and routers, and host-based devices such as personal firewalls, examine network traffic and permit or deny it based on a set of rules.', 'kb-doc-04-nist-sp-800-86-p65-6', 0, 31, '04-nist-sp-800-86', 'retrieved', '8FD0757579A55D6E67915673ED4A2BF0E43A7DD493B7546E924CC1EFF1D7DD52', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-7', 'doc-04-nist-sp-800-86', '', 65, 'Firewalls and routers are usually configured to log basic information for most or all denied connection attempts and connectionless packets; some log every packet.91 Information logged typically includes the date and time the packet was processed, the source and destination IP addresses, the transport layer protocol (e.g., TCP, UDP, ICMP), and basic protocol information (e.g., TCP or UDP port numbers, ICMP type and code).', 'kb-doc-04-nist-sp-800-86-p65-7', 0, 64, '04-nist-sp-800-86', 'retrieved', '028404098EC0BD437343F3C04BADB9A84A51E5E40B5EF008068AE0D6DD9268D6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-9', 'doc-04-nist-sp-800-86', '', 65, 'Network-based firewalls and routers that perform network address translation (NAT) may contain additional valuable data regarding network traffic.', 'kb-doc-04-nist-sp-800-86-p65-9', 0, 18, '04-nist-sp-800-86', 'retrieved', '057FB0F751172D2C2E02BEEA6E53C3906A0C19DA9051A06F86A83B2CEBE7796B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-10', 'doc-04-nist-sp-800-86', '', 65, 'NAT is the process of mapping addresses on one network to addresses on another network; this is most often accomplished by mapping private addresses92 from an internal network to one or more public addresses on a network that is connected to the Internet.', 'kb-doc-04-nist-sp-800-86-p65-10', 0, 43, '04-nist-sp-800-86', 'retrieved', '3ABD707B36CC63DD33D6048809F49FD0B6EC256F2FEFB5ADA5D4CC383A880479', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-11', 'doc-04-nist-sp-800-86', '', 65, 'NAT differentiates multiple internal addresses that are mapped to a single external address by assigning a different source port number to the external address for each internal address.', 'kb-doc-04-nist-sp-800-86-p65-11', 0, 28, '04-nist-sp-800-86', 'retrieved', '65834158188C4D10ABDC43B28E369DAA69FA9751DA89259A5CC5920BEB35EC46', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-14', 'doc-04-nist-sp-800-86', '', 65, 'A proxy receives a request from a client, and then sends a request on the clients behalf to the desired destination.', 'kb-doc-04-nist-sp-800-86-p65-14', 0, 21, '04-nist-sp-800-86', 'retrieved', '83EA7128F769C94F169B34284196595250C9C48736659A87D736F8D393D6187B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-15', 'doc-04-nist-sp-800-86', '', 65, 'When a proxy is used, each successful connection attempt actually results in the creation of two separate connections: one between the client and the proxy server, and another between the proxy server and the true destination.', 'kb-doc-04-nist-sp-800-86-p65-15', 0, 36, '04-nist-sp-800-86', 'retrieved', 'F24007832810CCF2C2FCD2C7C665139BCDE21C95D817B1DFA351179F1E86E869', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-17', 'doc-04-nist-sp-800-86', '', 65, 'Many proxies are application-specific, and some actually perform some analysis and validation of application protocols, such as HTTP.', 'kb-doc-04-nist-sp-800-86-p65-17', 0, 18, '04-nist-sp-800-86', 'retrieved', 'B4F288D656CA2456D4A74726C7AECBE1A6C25DD55E26D1498C287C47149EFE34', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-18', 'doc-04-nist-sp-800-86', '', 65, 'The proxy may reject client requests that appear to be invalid and log information regarding these requests.93 In addition to providing NAT and proxying services, firewalls and routers may perform such other functions as intrusion detection and VPN.', 'kb-doc-04-nist-sp-800-86-p65-18', 0, 38, '04-nist-sp-800-86', 'retrieved', '31B5759E95BD54C7F98E379CCDBA7F76F6418ACAD5AEC16EC024D57047A052DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-19', 'doc-04-nist-sp-800-86', '', 65, 'The intrusion detection and VPN functions are discussed in more detail in Sections 6.2.3 and 6.2.4, respectively.', 'kb-doc-04-nist-sp-800-86-p65-19', 0, 17, '04-nist-sp-800-86', 'retrieved', 'F4FAB28CA43C9375D7B6171F3FF416EFD9A48DD0387B27706B7BD88979E78334', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-20', 'doc-04-nist-sp-800-86', '', 65, 'Packet Sniffers and Protocol Analyzers Packet sniffers are designed to monitor network traffic on wired or wireless networks and capture packets.', 'kb-doc-04-nist-sp-800-86-p65-20', 0, 21, '04-nist-sp-800-86', 'retrieved', '082D597FAA5A906D2899CC9452496491B4447CD97B2514B87BD5928CADE0EBE7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-21', 'doc-04-nist-sp-800-86', '', 65, 'Normally, a NIC accepts only the incoming packets that are specifically intended for it.', 'kb-doc-04-nist-sp-800-86-p65-21', 0, 14, '04-nist-sp-800-86', 'retrieved', '046ABBECB7F74F77BB62457691261C132FBDA7ED64F1044D1FC564A4341564C0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-23', 'doc-04-nist-sp-800-86', '', 65, '91 Although logging all packets records more information about recent network activity than does logging information for connections and connection attempts, space limitations might permit packets to be kept for a short time only.', 'kb-doc-04-nist-sp-800-86-p65-23', 0, 34, '04-nist-sp-800-86', 'retrieved', 'ECD73408569A6BD6F2A83173803AAAA65FA857CC9684D13526D2D95173A21277', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
