VALUES ('doc-04-nist-sp-800-86-p65-24', 'doc-04-nist-sp-800-86', '', 65, 'In addition, the overhead required to record all packets might cause the systems performance to degrade.', 'kb-doc-04-nist-sp-800-86-p65-24', 0, 16, '04-nist-sp-800-86', 'retrieved', '5240C2C066BA9755FC827C4AF928EBA9DD2ED39004CCDA958F50EBC0D2366E91', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
