VALUES ('doc-04-nist-sp-800-86-p65-26', 'doc-04-nist-sp-800-86', '', 65, 'RFC 1918, Address Allocation for Private Internets, is available at http://www.ietf.org/rfc/rfc1918.txt.', 'kb-doc-04-nist-sp-800-86-p65-26', 0, 11, '04-nist-sp-800-86', 'retrieved', '006172E39D8EB2FF479DB1E0673EE0E6156FE85D2076538FAC574D9B9AE2FA7A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
