INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-27', 'doc-04-nist-sp-800-86', '', 65, '93 Some organizations configure their networks and network security so that all network traffic passing through the network perimeter for common applications is proxied, preventing individual users from bypassing the proxies.', 'kb-doc-04-nist-sp-800-86-p65-27', 0, 31, '04-nist-sp-800-86', 'retrieved', '37F749D36311233EB35D4DB2A5926748EF57BACE04A0A5AD9853561BB521DF22', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p65-28', 'doc-04-nist-sp-800-86', '', 65, 'In such an environment, the proxy server logs can be particularly valuable for network forensics.', 'kb-doc-04-nist-sp-800-86-p65-28', 0, 15, '04-nist-sp-800-86', 'retrieved', 'F71A9B569A739F12AE610D2E9EA30F1022CDD89F2F2941008F30E4C25438B26F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-1', 'doc-04-nist-sp-800-86', '', 66, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE is placed in promiscuous mode, it accepts all incoming packets that it sees, regardless of their intended destinations.', 'kb-doc-04-nist-sp-800-86-p66-1', 0, 26, '04-nist-sp-800-86', 'retrieved', 'FA3769FFF2BD10F89B9935AC837B9BCE911F0375A245905C3DA21CE5752C91CE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-2', 'doc-04-nist-sp-800-86', '', 66, 'Packet sniffers generally work by placing the NIC in promiscuous mode; the user then configures the sniffer to capture all packets or only those with particular characteristics (e.g., certain TCP ports, certain source or destination IP addresses).', 'kb-doc-04-nist-sp-800-86-p66-2', 0, 37, '04-nist-sp-800-86', 'retrieved', '5F90687118CC734D3605A2875D75CAE4DEC23AF5E02812BD718BFBE718B1CBFE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-3', 'doc-04-nist-sp-800-86', '', 66, 'Packet sniffers are commonly used to capture a particular type of traffic for troubleshooting or investigative purposes.', 'kb-doc-04-nist-sp-800-86-p66-3', 0, 17, '04-nist-sp-800-86', 'retrieved', 'EEEDDB513070D058972F7C493E94598786DD8701D58B8635BBF6A4A3641AC54E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-4', 'doc-04-nist-sp-800-86', '', 66, 'For example, if IDS alerts indicate unusual network activity between two hosts, a packet sniffer could record all of the packets traveling between the hosts, potentially providing additional information for analysts.', 'kb-doc-04-nist-sp-800-86-p66-4', 0, 31, '04-nist-sp-800-86', 'retrieved', 'F9B4B918C787B1DE58E273E3D86DD13E17286ED2F019B4611EE13E7EE5A8529C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-5', 'doc-04-nist-sp-800-86', '', 66, 'Most packet sniffers are also protocol analyzers, which means that they can reassemble streams from individual packets and decode communications that use any of hundreds or thousands of different protocols.94 Protocol analyzers usually can process not only live network traffic but also packets that have been recorded previously in capture files by packet sniffers.', 'kb-doc-04-nist-sp-800-86-p66-5', 0, 54, '04-nist-sp-800-86', 'retrieved', '407CD94AE94197A585CC1E998113A93A3F9330388573A56D0DD627F209B34413', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-6', 'doc-04-nist-sp-800-86', '', 66, 'Protocol analyzers are extremely valuable in displaying raw packet data in an understandable format.', 'kb-doc-04-nist-sp-800-86-p66-6', 0, 14, '04-nist-sp-800-86', 'retrieved', '678A4849A35E9F3B56571C0FFFC7C8254874245CD57BBEB532EDFE929A70145C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-9', 'doc-04-nist-sp-800-86', '', 66, 'Intrusion Detection Systems Network IDSs perform packet sniffing and analyze network traffic to identify suspicious activity and record relevant information.95 Host IDSs monitor characteristics of a particular system and events occurring within the system, which can include network traffic.96 Unlike network IDS sensors, which can monitor all network traffic on a particular network segment, host IDS software is intended to monitor network traffic only for the host on which it is installed.97 For each suspicious event, IDS software typically records the same basic event characteristics that firewalls and routers record (e.g., date and time, source and destination IP addresses, protocol, basic protocol characteristics), as well as application- specific information (e.g., username, filename, command, status code).', 'kb-doc-04-nist-sp-800-86-p66-9', 0, 115, '04-nist-sp-800-86', 'retrieved', 'F858C8721762A9897D604DF3B01041D7711003ADC32558D6FCEF87D46DC9B2E7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-10', 'doc-04-nist-sp-800-86', '', 66, 'IDS software also records information that indicates the possible intent of the activity.', 'kb-doc-04-nist-sp-800-86-p66-10', 0, 13, '04-nist-sp-800-86', 'retrieved', '94BCD7BA6752CCCDB16DFAE6D37373F62837CBC10BB1BBDEBDFC0B84E9B30163', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-11', 'doc-04-nist-sp-800-86', '', 66, 'Examples include the type of attack (e.g., buffer overflow), the targeted vulnerability, the apparent success or failure of the attack, and pointers to more information about the attack.98 Some IDSs can be configured to capture packets related to suspicious activity.', 'kb-doc-04-nist-sp-800-86-p66-11', 0, 40, '04-nist-sp-800-86', 'retrieved', '4A66C86D67FD2E0CD4A8728D6A7A577F453E4F3E4F07D8D2E92A2C47DD77D5C0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-12', 'doc-04-nist-sp-800-86', '', 66, 'This can range from recording only the packet that triggered the IDS to label the activity suspicious, to recording the rest of the session.', 'kb-doc-04-nist-sp-800-86-p66-12', 0, 24, '04-nist-sp-800-86', 'retrieved', '1B1E6B522FBE977F28AF27DE61656D010A3387AA420BFF1FFDE5FF47495AD90B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-13', 'doc-04-nist-sp-800-86', '', 66, 'Some IDSs even have the ability to store all sessions for a short period of time so that if something suspicious is detected, the previous activity in the same session can be preserved.', 'kb-doc-04-nist-sp-800-86-p66-13', 0, 33, '04-nist-sp-800-86', 'retrieved', '4A119ECB7DB166845BE3A52365CE7F35E7B939232FBC1864FCEDD43F6F5C42A8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-15', 'doc-04-nist-sp-800-86', '', 66, '94 Examples of open source packet sniffer and protocol analyzer software for wired networks include Ethereal (http://www.ethereal.com/), TCPDump (http://www.tcpdump.org/), and WinDump (http://www.winpcap.org/windump/).', 'kb-doc-04-nist-sp-800-86-p66-15', 0, 22, '04-nist-sp-800-86', 'retrieved', '99A91A00CC8BD5A0911FB9EB35B9472E64E6EB919CFCA6E985584967DD16DA9A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-16', 'doc-04-nist-sp-800-86', '', 66, 'Open source software is also available for wireless networks, including Ethereal and Kismet (http://www.kismetwireless.net/).', 'kb-doc-04-nist-sp-800-86-p66-16', 0, 14, '04-nist-sp-800-86', 'retrieved', 'D53B93A3FCA89295583C3D9877F9907578D71E72EE3898B000348D5E99F047DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-17', 'doc-04-nist-sp-800-86', '', 66, 'Additional packet sniffer and protocol analyzer software products are listed on various Web sites, including the Talisker Security Wizardry Portal (http://www.networkintrusion.co.uk/protanalyzers.htm), Softpedia (http://www.softpedia.com/get/Network-Tools/Protocol-Analyzers-Sniffers/), Packet Storm (http://packetstormsecurity.org/defense/sniff/), and other Web sites listed in Appendix F.', 'kb-doc-04-nist-sp-800-86-p66-17', 0, 34, '04-nist-sp-800-86', 'retrieved', 'D4799738B7E860DCA37E3A5B58BA67109D1F7E2E7A3183553243320067D3CD1B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-18', 'doc-04-nist-sp-800-86', '', 66, '95 Some network IDSs allow administrators to identify misuse as well as attacks.', 'kb-doc-04-nist-sp-800-86-p66-18', 0, 13, '04-nist-sp-800-86', 'retrieved', 'E2AC19700256AF14370DE4F7E8F6B32ACC868070D20C6AE0125ECA48DEBB1ACA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-19', 'doc-04-nist-sp-800-86', '', 66, 'For example, an administrator (with proper approval) could configure the IDS with character strings of interest, such as an acronym or phrase associated with a sensitive project.', 'kb-doc-04-nist-sp-800-86-p66-19', 0, 27, '04-nist-sp-800-86', 'retrieved', 'D97B8D11A17BD5FD928403E15B9CB1FB759DBA743004B42372C2E3D0441CA489', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-20', 'doc-04-nist-sp-800-86', '', 66, 'The IDS could then search network traffic for file transfers, e-mails, and other forms of communication that used one of those character strings.', 'kb-doc-04-nist-sp-800-86-p66-20', 0, 23, '04-nist-sp-800-86', 'retrieved', '4F60F923343E0A88304C6AF33B1851410A5E24EF23CC08777A9942338C21A882', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-21', 'doc-04-nist-sp-800-86', '', 66, '96 Examples of open source network IDS products include Bro (http://www.bro-ids.org/) and Snort (http://www.snort.org/).', 'kb-doc-04-nist-sp-800-86-p66-21', 0, 14, '04-nist-sp-800-86', 'retrieved', '650B35B9A7BBDF1957A2F4DC786B70816ECD00957F20427D3AF599F68C86DA85', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-22', 'doc-04-nist-sp-800-86', '', 66, 'For more information about network and host IDS products, see the Talisker Security Wizardry Portal (http://www.networkintrusion.co.uk/ids.htm), Honeypots.net (http://www.honeypots.net/ids/products/), the Common Vulnerabilities and Exposures Web site (http://www.cve.mitre.org/compatible/product.html), and other Web sites listed in Appendix F.', 'kb-doc-04-nist-sp-800-86-p66-22', 0, 34, '04-nist-sp-800-86', 'retrieved', 'AA344B0D583B208D9DC08D2CFF34A796E784ADABDBD0E4381DB54B7CDC5914DD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
