VALUES ('doc-04-nist-sp-800-86-p66-23', 'doc-04-nist-sp-800-86', '', 66, '97 See NIST SP 800-31, Intrusion Detection Systems, for more information on network and host IDS.', 'kb-doc-04-nist-sp-800-86-p66-23', 0, 16, '04-nist-sp-800-86', 'retrieved', '8054AC2A7B0C125686C30557BE4F2866D97F9C52B072D9E2E9B9AD604200B7B7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
