VALUES ('doc-04-nist-sp-800-86-p66-25', 'doc-04-nist-sp-800-86', '', 66, '98 Many IDS vendors provide help files that contain detailed information about each type of activity.', 'kb-doc-04-nist-sp-800-86-p66-25', 0, 16, '04-nist-sp-800-86', 'retrieved', 'C4EE1CE5A525DEAA912C304C1102EBDACDF34DAD5D03AA3F31017EC1AB497CBD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
