INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p66-26', 'doc-04-nist-sp-800-86', '', 66, 'IDS vendors also typically provide pointers to external sources of information, such as CERT®/CC advisories, Common Vulnerabilities and Exposures (CVE) numbers, and software vendor vulnerability announcements.', 'kb-doc-04-nist-sp-800-86-p66-26', 0, 26, '04-nist-sp-800-86', 'retrieved', 'F4AE794341F754DBE8E535E09C0A67FEA89270C4C85A2AB078A26854CDEE2772', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-1', 'doc-04-nist-sp-800-86', '', 67, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE are captured primarily so that intrusion detection analysts can review them when validating IDS alerts and investigating suspicious activity.', 'kb-doc-04-nist-sp-800-86-p67-1', 0, 27, '04-nist-sp-800-86', 'retrieved', '536F93660D735D723C8CB323692FDAD099D9C44780977686A83D218BCB770153', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
