INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-2', 'doc-04-nist-sp-800-86', '', 67, 'Some IDSs also have intrusion prevention capabilities, which means that they actively attempt to stop attacks in progress.', 'kb-doc-04-nist-sp-800-86-p67-2', 0, 18, '04-nist-sp-800-86', 'retrieved', '39F3A7B9325A06A873B5351C0A22B0106E8002F48860C7049F8D6CD366338B57', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-5', 'doc-04-nist-sp-800-86', '', 67, 'Remote Access Remote access servers are devices such as VPN gateways and modem servers that facilitate connections between networks.', 'kb-doc-04-nist-sp-800-86-p67-5', 0, 19, '04-nist-sp-800-86', 'retrieved', 'B2B4FD38E0D2F6B0450549B0D656289E5EBF86C5001273D3C400C7C085662BC5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-6', 'doc-04-nist-sp-800-86', '', 67, 'This often involves external systems connecting to internal systems through the remote access server but could also include internal systems connecting to external or internal systems.', 'kb-doc-04-nist-sp-800-86-p67-6', 0, 26, '04-nist-sp-800-86', 'retrieved', '592A909A0CE5D195446D7613170BDCD502314C8AFA9B28604CC2DC85F7E8ABE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-7', 'doc-04-nist-sp-800-86', '', 67, 'Remote access servers typically record the origin of each connection and might also indicate which user account was authenticated for each session.', 'kb-doc-04-nist-sp-800-86-p67-7', 0, 22, '04-nist-sp-800-86', 'retrieved', '3F8AB36DCFF87379080354CAA01B0F0B2BEA1B53194B5033AA9C96B105D93D3C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-8', 'doc-04-nist-sp-800-86', '', 67, 'If the remote access server assigns an IP address to the remote user, this is also likely to be logged.', 'kb-doc-04-nist-sp-800-86-p67-8', 0, 20, '04-nist-sp-800-86', 'retrieved', '4FA63755E4E58386937894B22C9179263D42401F2C2A2785A10D8EFB7279085C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-9', 'doc-04-nist-sp-800-86', '', 67, 'Some remote access servers also provide packet filtering functions, which typically perform logging similar to that provided by firewalls and routers, as described in Section 6.2.1.', 'kb-doc-04-nist-sp-800-86-p67-9', 0, 26, '04-nist-sp-800-86', 'retrieved', '992AEC8ED0860EE34970C20D282144251851918764DB0905FE342C9814EA2630', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-10', 'doc-04-nist-sp-800-86', '', 67, 'Remote access servers typically work at a network level, supporting the use of many different applications.', 'kb-doc-04-nist-sp-800-86-p67-10', 0, 16, '04-nist-sp-800-86', 'retrieved', '22C45A2B95BBB37C2DBB896F920816ACB75BFE53005703FCACAA7C0910822AB4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-11', 'doc-04-nist-sp-800-86', '', 67, 'Because the servers have no understanding of the applications functions, they usually do not record any application-specific data.', 'kb-doc-04-nist-sp-800-86-p67-11', 0, 18, '04-nist-sp-800-86', 'retrieved', 'E9C6277FD67E2A6A1BE07C68936E7AC1AE95A875954A40DDC6E6C909E99D1896', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-12', 'doc-04-nist-sp-800-86', '', 67, 'In addition to remote access servers, organizations typically use multiple applications that are specifically designed to provide remote access to a particular hosts OS.', 'kb-doc-04-nist-sp-800-86-p67-12', 0, 24, '04-nist-sp-800-86', 'retrieved', '4919729A5A3DC98573530CDEE2A1309319D3D4213C47D5C02E5D0640CAF37F67', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-13', 'doc-04-nist-sp-800-86', '', 67, 'Examples include secure shell (SSH), telnet, terminal servers,99 and remote control software.', 'kb-doc-04-nist-sp-800-86-p67-13', 0, 12, '04-nist-sp-800-86', 'retrieved', '908F1753CEF7A7C7DB1A6A92CDE77D39C8626057300FE7A02CEBBCD6BCDE9DE0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-14', 'doc-04-nist-sp-800-86', '', 67, 'Such applications can typically be configured to log basic information for each connection, including source IP address and user account.', 'kb-doc-04-nist-sp-800-86-p67-14', 0, 20, '04-nist-sp-800-86', 'retrieved', '1D27D2C7BA27EA4911D130EFF14A888D12CB8CE021BC28DAE45A6AD484769BF0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-15', 'doc-04-nist-sp-800-86', '', 67, 'Organizations also typically use many applications that are accessed remotely, such as client/server applications.', 'kb-doc-04-nist-sp-800-86-p67-15', 0, 14, '04-nist-sp-800-86', 'retrieved', 'C782564F7ECAE494720F3EA8121C7142AB3E0C1A99641398CE9EE99DA157F274', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-17', 'doc-04-nist-sp-800-86', '', 67, 'Although most remote accessrelated logging occurs on the remote access server or the application server, in some cases the client also logs information related to the connection.', 'kb-doc-04-nist-sp-800-86-p67-17', 0, 27, '04-nist-sp-800-86', 'retrieved', 'D755DD85A60E9784124E38AEFE584BC4A555C415D0C1A3094F51DF4421B3CDC7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-18', 'doc-04-nist-sp-800-86', '', 67, 'Security Event Management Software Security event management (SEM)100 software is capable of importing security event information from various network trafficrelated security event data sources (e.g., IDS logs, firewall logs) and correlating events among the sources.101 It generally works by receiving copies of logs from various data sources over secure channels, normalizing the logs into a standard format, then identifying related events by matching IP addresses, timestamps, and other characteristics.', 'kb-doc-04-nist-sp-800-86-p67-18', 0, 69, '04-nist-sp-800-86', 'retrieved', '431904A23B908790E2FFF18DA33DEEB0587CB7EC587D885476390CED543BBD7E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-19', 'doc-04-nist-sp-800-86', '', 67, 'SEM products usually do not generate original event data; instead, they generate meta-events based on imported event data.', 'kb-doc-04-nist-sp-800-86-p67-19', 0, 18, '04-nist-sp-800-86', 'retrieved', '58DFF088BCCDE7D7242DDAF26776843A5D522FC6966940EC4C48220E4736F778', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-20', 'doc-04-nist-sp-800-86', '', 67, 'Many SEM products not only can identify malicious activity, such as attacks and virus infections, but also can detect misuse and inappropriate usage of systems and networks.', 'kb-doc-04-nist-sp-800-86-p67-20', 0, 27, '04-nist-sp-800-86', 'retrieved', '51CC5AD987DC04E8AA4BA7F57A5B42B5BA45A973B4761266439B7568F75A5755', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-21', 'doc-04-nist-sp-800-86', '', 67, 'SEM software can be helpful in making many sources of network traffic information accessible through a single interface.', 'kb-doc-04-nist-sp-800-86-p67-21', 0, 18, '04-nist-sp-800-86', 'retrieved', '6C8AC20C4D5D8F3C607A8B1DDF997A19EFF84C5A6A74A4806A9EA345ABAD496C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-22', 'doc-04-nist-sp-800-86', '', 67, 'Because SEM products can handle nearly any security event data source, such as OS logs, antivirus software alerts, and physical security device logs, SEM products may contain a wide variety of information regarding events.', 'kb-doc-04-nist-sp-800-86-p67-22', 0, 34, '04-nist-sp-800-86', 'retrieved', '90EEA35A7193533643737D9116C3D9DDF99B5A8165EB958DC01B682D0FB9A726', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-24', 'doc-04-nist-sp-800-86', '', 67, 'For example, if an IDS records packets, the packets may not be transferred to the SEM because of bandwidth and storage limitations.', 'kb-doc-04-nist-sp-800-86-p67-24', 0, 22, '04-nist-sp-800-86', 'retrieved', 'AB5223A3077A7B3DCE5DE7FB190971B612B7E0BCB50CCF2CD879E3C61243DFAF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-25', 'doc-04-nist-sp-800-86', '', 67, 'In addition, because most data sources record information in different formats, SEM products typically normalize the dataconverting each data field to a standard format and labeling', 'kb-doc-04-nist-sp-800-86-p67-25', 0, 26, '04-nist-sp-800-86', 'retrieved', '48B386A121F6BFAB47E7C8406C65F5BE9607B7E84C4701B8BF8975CA9F4ADA68', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p67-26', 'doc-04-nist-sp-800-86', '', 67, '99 In this context, terminal server refers to products such as Microsoft Windows Terminal Services and Citrix Metaframe that provide graphical remote access to operating systems and applications.', 'kb-doc-04-nist-sp-800-86-p67-26', 0, 28, '04-nist-sp-800-86', 'retrieved', '14FA78E44573C39B0409ABE44D14B210C193AE3399FBF583EA5B3ED28D78E562', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
