VALUES ('doc-04-nist-sp-800-86-p67-27', 'doc-04-nist-sp-800-86', '', 67, '100 SEM software is listed on several Web sites listed in Appendix F, including the Common Vulnerabilities and Exposures (CVE) Web site (http://www.cve.mitre.org/compatible/product.html).', 'kb-doc-04-nist-sp-800-86-p67-27', 0, 23, '04-nist-sp-800-86', 'retrieved', '7AD802C307F6E0053F11452C0C7232A0D9D74811F4A5C5B0C8F4230A81B9B1B6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
