VALUES ('doc-04-nist-sp-800-86-p68-1', 'doc-04-nist-sp-800-86', '', 68, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the data consistently.', 'kb-doc-04-nist-sp-800-86-p68-1', 0, 11, '04-nist-sp-800-86', 'retrieved', 'CB7718D5456615C7DC8B2B7EF1F96BC155538E7BF4E1758A88D2C0F7CE7A860C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
