INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-2', 'doc-04-nist-sp-800-86', '', 68, 'Although this is beneficial for analysis (as described in Section 6.4), the normalization process occasionally introduces errors in the data or causes some data to be lost.', 'kb-doc-04-nist-sp-800-86-p68-2', 0, 27, '04-nist-sp-800-86', 'retrieved', 'D71BC728FE1F71EA5EC297B472864C4D65D6013CAE3D0DDFBA8BED1BFBC69C6D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
