INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-3', 'doc-04-nist-sp-800-86', '', 68, 'Fortunately, SEM products typically do not alter the original data sources, so analysts should retain copies of the original logs and use them to verify the accuracy of the data if needed.', 'kb-doc-04-nist-sp-800-86-p68-3', 0, 32, '04-nist-sp-800-86', 'retrieved', '86687D64E143251FDED57C2ED3ABEF3D3B69EC1D6BBBFE6916E0182115DB8C46', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
