INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-5', 'doc-04-nist-sp-800-86', '', 68, 'Network Forensic Analysis Tools Network forensic analysis tools (NFAT)102 typically provide the same functionality as packet sniffers, protocol analyzers, and SEM software in a single product.', 'kb-doc-04-nist-sp-800-86-p68-5', 0, 26, '04-nist-sp-800-86', 'retrieved', 'F1370FE258ADE34521E67EA57D0B6EBD1C489D7769442E620A6E5E5F45401A5D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-6', 'doc-04-nist-sp-800-86', '', 68, 'Whereas SEM software concentrates on correlating events among existing data sources (which typically include multiple network trafficrelated sources), NFAT software focuses primarily on collecting, examining, and analyzing network traffic.', 'kb-doc-04-nist-sp-800-86-p68-6', 0, 29, '04-nist-sp-800-86', 'retrieved', '184AD2F5005218861942ED2C61F918BD2BDD014B2CA07A98F9FD7C7495F3C4FE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-7', 'doc-04-nist-sp-800-86', '', 68, 'NFAT software also offers additional features that further facilitate network forensics, such as the following: ! Reconstructing events by replaying network traffic within the tool, ranging from an individual session (e.g., instant messaging [IM] between two users) to all sessions during a particular time period.', 'kb-doc-04-nist-sp-800-86-p68-7', 0, 45, '04-nist-sp-800-86', 'retrieved', 'C27ACAD4F2BE138AE1032A571C256E30E586A5D374C447685F03C39510C8C57F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-10', 'doc-04-nist-sp-800-86', '', 68, 'Some tools can even tie IP addresses, domain names, or other data to physical locations and produce a geographic map of the activity.', 'kb-doc-04-nist-sp-800-86-p68-10', 0, 23, '04-nist-sp-800-86', 'retrieved', '6E15731B44E6EC449FEB4C354E8CE5A106272A8364B2097EA2DB13078E84720D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
