VALUES ('doc-04-nist-sp-800-86-p68-12', 'doc-04-nist-sp-800-86', '', 68, '! Searching application content for keywords (e.g., confidential, proprietary).', 'kb-doc-04-nist-sp-800-86-p68-12', 0, 9, '04-nist-sp-800-86', 'retrieved', 'FCDC3E8B5C9E8779C50370C7D2D43B85C9FA79BA653FB255AAF1905267D159D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
