VALUES ('doc-04-nist-sp-800-86-p68-13', 'doc-04-nist-sp-800-86', '', 68, 'Other Sources Most organizations have other sources of network traffic information that can be of use for forensics in some capacity, including the following: ! Dynamic Host Configuration Protocol Servers.', 'kb-doc-04-nist-sp-800-86-p68-13', 0, 30, '04-nist-sp-800-86', 'retrieved', '099EC878F970B7A567F8696E8BB5C1FE66B31E1EB40FAB4A414880F4B439A176', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
