INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-15', 'doc-04-nist-sp-800-86', '', 68, 'Some hosts might have static IP addresses, which means that they always receive the same IP address assignment; however, most hosts typically receive dynamic assignments.', 'kb-doc-04-nist-sp-800-86-p68-15', 0, 25, '04-nist-sp-800-86', 'retrieved', '13125E408396023EB9F5D755E6EA6DA9B32C7D9238E03A9588E1DEC65666719A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-16', 'doc-04-nist-sp-800-86', '', 68, 'This means that the hosts are required to renew their IP address assignments regularly and that there is no guarantee that they will be assigned the same addresses.', 'kb-doc-04-nist-sp-800-86-p68-16', 0, 28, '04-nist-sp-800-86', 'retrieved', '71D43529DE68110E5EC958E6F937140B46997A7803F5555974EC881E95146EB2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
