INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-17', 'doc-04-nist-sp-800-86', '', 68, 'DHCP servers may contain assignment logs that include the MAC address, the IP address assigned to that MAC address, and the time the assignment occurred.', 'kb-doc-04-nist-sp-800-86-p68-17', 0, 25, '04-nist-sp-800-86', 'retrieved', 'A8B06C193C869FE6A6D0BD4A88EE72BE7CB3E8AB8EB007A963807D8C66B18FC3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-19', 'doc-04-nist-sp-800-86', '', 68, 'Network monitoring software is designed to observe network traffic and gather statistics about it.103 For example, it may record high-level information about traffic flows for a particular network segment, such as the amount of bandwidth typically consumed by various protocols.', 'kb-doc-04-nist-sp-800-86-p68-19', 0, 40, '04-nist-sp-800-86', 'retrieved', 'A1993014FC337399638AA20D434266EE7FC9B3C1B7A054A80045CB8FD5E25379', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-20', 'doc-04-nist-sp-800-86', '', 68, 'Network monitoring software may also collect more detailed information about network activity, such as the payload size and the source and destination IP addresses and ports for each packet.', 'kb-doc-04-nist-sp-800-86-p68-20', 0, 29, '04-nist-sp-800-86', 'retrieved', '80D4ADB920B29DF81319FA4B08D5E2CABD62FEA29294BB268EE491B8C47BB00B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p68-21', 'doc-04-nist-sp-800-86', '', 68, 'Some managed switches and other network devices offer basic network monitoring capabilities, such as collecting statistics concerning bandwidth usage.', 'kb-doc-04-nist-sp-800-86-p68-21', 0, 19, '04-nist-sp-800-86', 'retrieved', '1744A39840A09D1327C6C5CCD3C15D4E106243C3F697F32B92AC9A9F1EDBD4D1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
