VALUES ('doc-04-nist-sp-800-86-p68-22', 'doc-04-nist-sp-800-86', '', 68, '102 Listings of NFAT software are available from Web sites listed in Appendix F, such as the Talisker Security Wizardry Portal (http://www.networkintrusion.co.uk/fornettools.htm).', 'kb-doc-04-nist-sp-800-86-p68-22', 0, 22, '04-nist-sp-800-86', 'retrieved', '6B3A5BF55E7FDDD5679918531B4F7DCA2345283B0C7EE2A2D18096B94209FC80', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
