VALUES ('doc-04-nist-sp-800-86-p68-23', 'doc-04-nist-sp-800-86', '', 68, '103 Open source network monitoring software includes EtherApe (http://etherape.sourceforge.net/) and IPaudit (http://ipaudit.sourceforge.net/).', 'kb-doc-04-nist-sp-800-86-p68-23', 0, 12, '04-nist-sp-800-86', 'retrieved', '4B0DA79B9203433CFFCAB0A3D0AFD96B1C77800E3BAD0AF62EEA035054EE432B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
