VALUES ('doc-04-nist-sp-800-86-p68-24', 'doc-04-nist-sp-800-86', '', 68, 'Packet sniffers, protocol analyzers, and IDS software may also perform basic network monitoring functions.', 'kb-doc-04-nist-sp-800-86-p68-24', 0, 14, '04-nist-sp-800-86', 'retrieved', '80A101D8A356E58F1CDF033912E17D831E810BC21B594FAC2BAA5A0F650828A9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
