VALUES ('doc-04-nist-sp-800-86-p69-2', 'doc-04-nist-sp-800-86', '', 69, 'ISPs may collect network traffic-related data as part of their normal operations and when investigating unusual activity, such as extremely high volumes of traffic or an apparent attack.', 'kb-doc-04-nist-sp-800-86-p69-2', 0, 28, '04-nist-sp-800-86', 'retrieved', '4712D821A634417B2FCC2671176801687743831805A7A03125AA0ED7D76FC67E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
