VALUES ('doc-04-nist-sp-800-86-p69-4', 'doc-04-nist-sp-800-86', '', 69, 'Section 6.3.1 discusses legal considerations involved in collecting network traffic data from ISPs and other third parties.', 'kb-doc-04-nist-sp-800-86-p69-4', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A7FD487F093DED778E081E81C7FA99D660FF1E028054F654539DAABB3F668051', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
