INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-6', 'doc-04-nist-sp-800-86', '', 69, 'Some client/server applications used over networks may record information regarding successful and failed usage attempts, which could include connection- related data such as the clients IP address and port.', 'kb-doc-04-nist-sp-800-86-p69-6', 0, 29, '04-nist-sp-800-86', 'retrieved', '6210589962D974711ED1C8A013C643774250FEAE57EED2244F6F3D11059551B0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-9', 'doc-04-nist-sp-800-86', '', 69, 'Sections 5.1.2 and 5.2.1 describe the types of network information that can be collected from individual hosts, including the TCP and UDP ports at which a host is listening.', 'kb-doc-04-nist-sp-800-86-p69-9', 0, 29, '04-nist-sp-800-86', 'retrieved', '89B65300A8A3C11B97363F37EFE111E7B86BF7EDBAD61470A65632B00C8DC8EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
