INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-10', 'doc-04-nist-sp-800-86', '', 69, '6.3 Collecting Network Traffic Data As described in Section 6.2, organizations typically have network traffic data recorded in many places during normal operations.', 'kb-doc-04-nist-sp-800-86-p69-10', 0, 23, '04-nist-sp-800-86', 'retrieved', '2DBF4D10CBDC73A9E1F29AF07FA70069A5EC4C0BA7D70C0A8D0DD4D82383E968', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
