INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-11', 'doc-04-nist-sp-800-86', '', 69, 'Organizations also use the same data recording mechanisms to collect additional data on an as-needed basis when investigating incidents or troubleshooting problems.', 'kb-doc-04-nist-sp-800-86-p69-11', 0, 22, '04-nist-sp-800-86', 'retrieved', 'AD2FE584163C2F9D8F580E8B7F9C40A67CB569ACD79C75B18CDD1DA227DD7EE2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-12', 'doc-04-nist-sp-800-86', '', 69, 'For example, a network administrator or incident handler might deploy a packet sniffer to examine unusual packets sent by a host.', 'kb-doc-04-nist-sp-800-86-p69-12', 0, 21, '04-nist-sp-800-86', 'retrieved', '148FD84A55853E335988BABFC9DE1A7CDF7F640401142AB95297C7A66AD81A4B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-13', 'doc-04-nist-sp-800-86', '', 69, 'Network traffic data is usually recorded to a log or stored in a packet capture file.', 'kb-doc-04-nist-sp-800-86-p69-13', 0, 16, '04-nist-sp-800-86', 'retrieved', 'F04B7A9ECD5045B957478A46B69777B0FBFFF427B2A2621B55CBB540628A029F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-14', 'doc-04-nist-sp-800-86', '', 69, 'In most cases, collecting the data is as simple as collecting the logs and packet capture files.', 'kb-doc-04-nist-sp-800-86-p69-14', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A635E8CD22F165D5B94A7F37135015EA5A43DCDED4220C0689C61A20FCA30ED4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-15', 'doc-04-nist-sp-800-86', '', 69, 'Section 4 describes how to collect files in an appropriate manner for evidentiary purposes.', 'kb-doc-04-nist-sp-800-86-p69-15', 0, 14, '04-nist-sp-800-86', 'retrieved', '51B9E3F03F2D5434EF516AA539A7472CE9C146677A14ACABBFFC4674E280429B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-16', 'doc-04-nist-sp-800-86', '', 69, 'If data is not stored in a file (e.g., traffic flow map displayed graphically, data displayed on the console screen only), screen captures or photographs of the screen might be needed.', 'kb-doc-04-nist-sp-800-86-p69-16', 0, 31, '04-nist-sp-800-86', 'retrieved', 'C00A17E3765DAF4C9F70D69400E17013E538159C413DDC09F8AE4A5344E04416', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-17', 'doc-04-nist-sp-800-86', '', 69, 'Although collecting network traffic data is typically straightforward, there are several important legal and technical issues that can make data collection more complicated.', 'kb-doc-04-nist-sp-800-86-p69-17', 0, 23, '04-nist-sp-800-86', 'retrieved', 'F23F292AEE9B9EBD0FD46F5FDC4B9C2B903ED7D6C4B4C14E2A879555A8FD7CAE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-19', 'doc-04-nist-sp-800-86', '', 69, 'Among these issues is the capture (intentional or incidental) of information with privacy or security implications, such as passwords or the contents of e- mails.', 'kb-doc-04-nist-sp-800-86-p69-19', 0, 25, '04-nist-sp-800-86', 'retrieved', '8C6C14961ABC3DEE3162D4FCE2CFEA7A4A755340DBB0CC227D973F810E5BFFDA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-20', 'doc-04-nist-sp-800-86', '', 69, 'This could expose the information to the staff members who are analyzing the collected data or administering the recording systems (e.g., IDS sensors).', 'kb-doc-04-nist-sp-800-86-p69-20', 0, 23, '04-nist-sp-800-86', 'retrieved', '869FC1E7735DCA74FB3A304F43652E216CA3C3AE3FA758C1BA089794D1BB3DBC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-21', 'doc-04-nist-sp-800-86', '', 69, 'Organizations should have policies in place regarding the handling of inadvertent disclosures of sensitive information.', 'kb-doc-04-nist-sp-800-86-p69-21', 0, 15, '04-nist-sp-800-86', 'retrieved', 'A0AF38E61674A1E181615D42C5A7DD2BB4BF3B909FEDE0106ADD68B063835F27', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-22', 'doc-04-nist-sp-800-86', '', 69, 'Another problem with capturing data such as e-mails and text documents is that long-term storage of such information might violate an organizations data retention policy.', 'kb-doc-04-nist-sp-800-86-p69-22', 0, 25, '04-nist-sp-800-86', 'retrieved', '7DA850125F1A49923703C5EDBCEE6040252FDF0BE5E7C183B32975F9394DA5EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-23', 'doc-04-nist-sp-800-86', '', 69, 'It is also important to have policies regarding the monitoring of networks and to have warning banners on systems that indicate that activity may be monitored.', 'kb-doc-04-nist-sp-800-86-p69-23', 0, 26, '04-nist-sp-800-86', 'retrieved', 'D38E9465296E981F72463CBFFA588ECEDCABC7A04B4CF4365A5023047C4F6A12', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-24', 'doc-04-nist-sp-800-86', '', 69, 'Although most network traffic data collection occurs as part of regular operations, it can also occur as part of troubleshooting or incident handling.', 'kb-doc-04-nist-sp-800-86-p69-24', 0, 23, '04-nist-sp-800-86', 'retrieved', '4396D0F0C0CC4966569FD6C30D989384B6D34AD4FF8F30A9D2FF5C31F16228C4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-25', 'doc-04-nist-sp-800-86', '', 69, 'In the latter case, it is important to follow consistent processes and to document all actions performed.', 'kb-doc-04-nist-sp-800-86-p69-25', 0, 17, '04-nist-sp-800-86', 'retrieved', 'AC498E011810292C05E29770332BAE79E379E5E1B0716CA70192C470BE7807E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-26', 'doc-04-nist-sp-800-86', '', 69, 'For example, recording all packets sent and received by a particular user should be initiated only after the successful completion of a formal request and approval process.', 'kb-doc-04-nist-sp-800-86-p69-26', 0, 27, '04-nist-sp-800-86', 'retrieved', 'B9E7E8132313DC83015F544782F3FC9A4D2B718F4618FC2931E1A3A1E5E10226', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p69-27', 'doc-04-nist-sp-800-86', '', 69, 'Organizations should have policies that clearly explain what types of monitoring can and cannot be performed without approval, and that describe or reference the procedures that detail the request and approval process.', 'kb-doc-04-nist-sp-800-86-p69-27', 0, 32, '04-nist-sp-800-86', 'retrieved', '1CF39A512DFAEB86E04F53FB3FE3F8295F65C5639E8DA20383558551E0BCDC88', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-1', 'doc-04-nist-sp-800-86', '', 70, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Another potential legal issue is the preservation of original logs.', 'kb-doc-04-nist-sp-800-86-p70-1', 0, 18, '04-nist-sp-800-86', 'retrieved', '393F9367FA39A2AB36D6526AFAD7942FF7DAF2A2BEC5427AA2F4D00C33B3D422', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-2', 'doc-04-nist-sp-800-86', '', 70, 'As described in Section 6.4, many organizations send copies of network traffic logs to centralized devices, as well as use tools that interpret and analyze network traffic.', 'kb-doc-04-nist-sp-800-86-p70-2', 0, 27, '04-nist-sp-800-86', 'retrieved', '640896D740AF2F484B1F1E63CE21A1AE1054EA829E25CC3F8E7A3DAF96C269E8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-3', 'doc-04-nist-sp-800-86', '', 70, 'In cases where logs may be needed as evidence, organizations may wish to collect copies of the original log files, the centralized log files, and interpreted log data, in case there are any questions regarding the fidelity of the copying and interpretation processes.', 'kb-doc-04-nist-sp-800-86-p70-3', 0, 43, '04-nist-sp-800-86', 'retrieved', 'B9EF3610FAF384BB85EF57D76DD7BDC7ABB10BFBC64D61B565244016A8BB83AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-5', 'doc-04-nist-sp-800-86', '', 70, 'As privacy has become a greater concern to organizations, many have become less willing to share information with each other, including network forensic data.', 'kb-doc-04-nist-sp-800-86-p70-5', 0, 24, '04-nist-sp-800-86', 'retrieved', 'B3DF6F4E75B78A73CE7C9B49F6FA9056CA052A59180F9F4BBE499C05D1B70BBF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-6', 'doc-04-nist-sp-800-86', '', 70, 'For example, most ISPs now require a court order before providing any information related to suspicious network activity that might have passed through their infrastructure.', 'kb-doc-04-nist-sp-800-86-p70-6', 0, 25, '04-nist-sp-800-86', 'retrieved', 'A569C8CDA5E89A6C7F17A1260863FDCA0AAA0D0BF05643920D700D134C49F276', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-7', 'doc-04-nist-sp-800-86', '', 70, 'Although this preserves privacy and reduces the burden on and liability of the ISPs, it also slows down the investigative process.', 'kb-doc-04-nist-sp-800-86-p70-7', 0, 21, '04-nist-sp-800-86', 'retrieved', 'EBD58F7277D06C5AC489598AEABCE7249C1FC67D34237613E7EBE9F359E2D48F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-8', 'doc-04-nist-sp-800-86', '', 70, 'This is particularly challenging when an organization is attempting to trace an ongoing network-based attack to its source, especially if the traffic passes through several ISPs.', 'kb-doc-04-nist-sp-800-86-p70-8', 0, 26, '04-nist-sp-800-86', 'retrieved', '159214CA106340530A63349367835941A972C8F98252E57331A7AD78D58686EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-10', 'doc-04-nist-sp-800-86', '', 70, 'Technical Issues Several technical issues might impede the collection of data about network traffic.', 'kb-doc-04-nist-sp-800-86-p70-10', 0, 14, '04-nist-sp-800-86', 'retrieved', 'D0BC7BDC35002CB95B7FC16C894228A6350F10B3F250BCC81E2B0952E5BC07D9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-11', 'doc-04-nist-sp-800-86', '', 70, 'This section describes several of the major issues and provides guidance on what, if anything, can be done to mitigate each.', 'kb-doc-04-nist-sp-800-86-p70-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '0EAF4C4ED7FAB91B5B26F7458903816FC6B7C6B03395FC14EE33BA68306EAB26', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-13', 'doc-04-nist-sp-800-86', '', 70, 'When there is a large volume of network activity, particularly during adverse events such as attacks, logs may record many events in a short time.', 'kb-doc-04-nist-sp-800-86-p70-13', 0, 25, '04-nist-sp-800-86', 'retrieved', '954357155253B41BC0D67002C9BA13F8F2218E2931A6A5540820CCD78E212EAA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-14', 'doc-04-nist-sp-800-86', '', 70, 'If insufficient storage is available, information about recent activity may be overwritten and lost.', 'kb-doc-04-nist-sp-800-86-p70-14', 0, 14, '04-nist-sp-800-86', 'retrieved', '8BB821BB881B1F0CE8396057EA8C8924E2F3114819D42BF61EB5D99BDAA8F67F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-15', 'doc-04-nist-sp-800-86', '', 70, 'Organizations should estimate typical and peak log usage, determine how many hours or days worth of data should be retained, and ensure that systems and applications have sufficient storage available to meet those goals.104 ! Encrypted Traffic.', 'kb-doc-04-nist-sp-800-86-p70-15', 0, 37, '04-nist-sp-800-86', 'retrieved', 'AF6DF96B76D7305F26E04A33320BBA6D942AC2E3CE50C18E5CDA453303DAE16B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-16', 'doc-04-nist-sp-800-86', '', 70, 'When protocols such as IP Security (IPsec), SSH, and Secure Sockets Layer (SSL) are used to encrypt network traffic, devices monitoring network traffic along the encrypted path can see only the most basic characteristics of the traffic, such as source and destination IP addresses.', 'kb-doc-04-nist-sp-800-86-p70-16', 0, 44, '04-nist-sp-800-86', 'retrieved', '79A78360A12A9D237BA07EDF7D6879127DD3285709904E7EB5573248AECA87A0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-17', 'doc-04-nist-sp-800-86', '', 70, 'If VPNs or other tunneling techniques are being used, the IP addresses might be for the tunnel itself and not the true source and destination of the activity.', 'kb-doc-04-nist-sp-800-86-p70-17', 0, 28, '04-nist-sp-800-86', 'retrieved', 'C2CF65096D22CF94EFAF6F8F93AB44EC820413CF2C85E4910A322D986AFC2493', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-18', 'doc-04-nist-sp-800-86', '', 70, 'To collect data about the decrypted traffic, a data source must be positioned where it can see the decrypted activity.', 'kb-doc-04-nist-sp-800-86-p70-18', 0, 20, '04-nist-sp-800-86', 'retrieved', 'E734A7E29FD90314465183C74BC3B7DD6B882860AE92F0B9DB87566F7F06DC9A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-19', 'doc-04-nist-sp-800-86', '', 70, 'For example, placing an IDS sensor immediately behind a VPN gateway can be effective at identifying anomalous activity in the decrypted communications.', 'kb-doc-04-nist-sp-800-86-p70-19', 0, 22, '04-nist-sp-800-86', 'retrieved', 'E0CDC375E249199BA07E4B54F666E602979F6CAA5CC873930614080D5DE489FD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-20', 'doc-04-nist-sp-800-86', '', 70, 'If communications are encrypted all the way to the internal host (e.g., an SSL-encrypted Web session), then devices monitoring network traffic cannot see the decrypted packets.', 'kb-doc-04-nist-sp-800-86-p70-20', 0, 26, '04-nist-sp-800-86', 'retrieved', '2CE8523635C60DC444C90F12011BDC1678B7141BF95CDA69FC12A469970D3AC9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-21', 'doc-04-nist-sp-800-86', '', 70, 'Organizations should consider establishing policies that specify the appropriate use of traffic encryption technologies, so that security controls such as IDS sensors can monitor the contents of traffic that does not need to be or should not be encrypted.', 'kb-doc-04-nist-sp-800-86-p70-21', 0, 39, '04-nist-sp-800-86', 'retrieved', '0A63333070C07BCD089053DC6C17422E40D0098EC0994A5899E4A91523E87259', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-23', 'doc-04-nist-sp-800-86', '', 70, 'Applications such as IDSs and protocol analyzers often rely on port numbers to identify which service is in use for a given connection.', 'kb-doc-04-nist-sp-800-86-p70-23', 0, 23, '04-nist-sp-800-86', 'retrieved', '98E301ACFC2CCD4C593EE8D5BC7BC608EFAC0C49C139070B1D697B4E1F8CB6C3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-24', 'doc-04-nist-sp-800-86', '', 70, 'Unfortunately, as described in Section 6.1.2, most services can be run on any port number.', 'kb-doc-04-nist-sp-800-86-p70-24', 0, 15, '04-nist-sp-800-86', 'retrieved', '11AFEF5141F62ADAB0877DA84E930C3014768838B692AE7226C2E44EFC869066', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-25', 'doc-04-nist-sp-800-86', '', 70, 'Because traffic involving services running on unexpected port numbers may not be captured, monitored, or analyzed properly, use of unauthorized services (e.g., providing Web services on an', 'kb-doc-04-nist-sp-800-86-p70-25', 0, 27, '04-nist-sp-800-86', 'retrieved', '76E895BA8EA1BA807EE55E58DC89671A3D0E1A8162247F7F1FEB88FBD3380F9F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-26', 'doc-04-nist-sp-800-86', '', 70, '104 Organizations should also provide sufficient data storage to keep logs associated with computer security incidents for a substantially longer time than other logs, as needed.', 'kb-doc-04-nist-sp-800-86-p70-26', 0, 26, '04-nist-sp-800-86', 'retrieved', 'EAC5DC92D79AE753DA2BB861EF9D6DE881674BCBFE8C865CCAEC533A5D1BF92F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p70-27', 'doc-04-nist-sp-800-86', '', 70, 'For example, General Records Schedule (GRS) 24, Information Technology Operations and Management Records, specifies that computer security incident handling, reporting and follow-up records should be destroyed 3 years after all necessary follow-up actions have been completed. GRS 24 is available from the National Archives and Records Administration at http://www.archives.gov/records-mgmt/ardor/.', 'kb-doc-04-nist-sp-800-86-p70-27', 0, 49, '04-nist-sp-800-86', 'retrieved', 'C4667FE5C4635A3CF2825ED49FF5370BF24092EC272834F041D73836A002AF86', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-1', 'doc-04-nist-sp-800-86', '', 71, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE atypical port) might not be detected.', 'kb-doc-04-nist-sp-800-86-p71-1', 0, 14, '04-nist-sp-800-86', 'retrieved', '14E86799419E7F115AD8476462EF1368E260CC5D682EDF82139201707A6AC1B5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
