INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-2', 'doc-04-nist-sp-800-86', '', 71, 'Another motivation for using unexpected port numbers is to slip traffic through perimeter devices that filter based on port numbers.', 'kb-doc-04-nist-sp-800-86-p71-2', 0, 20, '04-nist-sp-800-86', 'retrieved', '4668E19A442FF2898269D73CF0F1136FBAEFA16142F23E74FE42346B153620ED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-3', 'doc-04-nist-sp-800-86', '', 71, 'There are several ways to attempt to identify unexpected port usage, including the following:  Configuring IDS sensors to alert on connections involving unknown server ports  Configuring application proxies or IDS sensors that perform protocol analysis to alert on connections that use an unexpected protocol (e.g., FTP traffic using the standard HTTP port)  Performing traffic flow monitoring and identifying new and unusual traffic flows  Configuring a protocol analyzer to analyze a particular stream as something else.', 'kb-doc-04-nist-sp-800-86-p71-3', 0, 79, '04-nist-sp-800-86', 'retrieved', '2C553A62360E0884D36B778E9876F3B1499A33149DB4EE55372A88E041FC60F3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-5', 'doc-04-nist-sp-800-86', '', 71, 'Attackers often enter networks from alternate access points to avoid detection by security controls that are monitoring major access points, such as the organizations Internet gateway.', 'kb-doc-04-nist-sp-800-86-p71-5', 0, 26, '04-nist-sp-800-86', 'retrieved', '4068942A51D9A02501EE11CC33ECAA48A1F88D1B6D1125866EE92B482DED0323', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-6', 'doc-04-nist-sp-800-86', '', 71, 'A classic example of an alternate access point is a modem in a users workstation.', 'kb-doc-04-nist-sp-800-86-p71-6', 0, 15, '04-nist-sp-800-86', 'retrieved', '2E1AAC5D27F6FAEEE186BFC04BA7091A4CD94E1C8EAF5771588CD68203226C87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-7', 'doc-04-nist-sp-800-86', '', 71, 'If an attacker can dial into the workstation and gain access, attacks can be launched from that workstation against other hosts.', 'kb-doc-04-nist-sp-800-86-p71-7', 0, 21, '04-nist-sp-800-86', 'retrieved', '62C9087473C59FC68F1C7FF0760DED2B2AA88E5079CF0E1ED0CDDBDAF4AACB56', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-8', 'doc-04-nist-sp-800-86', '', 71, 'In such cases, little or no information regarding the network activity might be logged because the activity would not pass through firewalls, IDS- monitored network segments, and other common data collection points.', 'kb-doc-04-nist-sp-800-86-p71-8', 0, 32, '04-nist-sp-800-86', 'retrieved', 'E3C367154865748CF4864CDE24C5D4940989EE11C4AC46D01BB1663C64967844', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-9', 'doc-04-nist-sp-800-86', '', 71, 'Organizations typically address this potential problem by limiting alternate access points, such as modems and wireless access points, and ensuring that each is monitored and restricted through firewalls, IDS sensors, and other controls.', 'kb-doc-04-nist-sp-800-86-p71-9', 0, 33, '04-nist-sp-800-86', 'retrieved', '2FAB9B912023206910807867B2DF7877463B5DEAB35B2FD1718DF789A52F7A17', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-11', 'doc-04-nist-sp-800-86', '', 71, 'Inevitably, systems and applications will occasionally experience failures or outages for various reasons (e.g., system maintenance, software failures, attacks).', 'kb-doc-04-nist-sp-800-86-p71-11', 0, 19, '04-nist-sp-800-86', 'retrieved', '347B8BA4AEEB264EE0899F63D57BC7B7B2FB3CA1BAAAEF5B0BB21158F045C046', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-12', 'doc-04-nist-sp-800-86', '', 71, 'In the case of dedicated monitoring systems such as IDS sensors, use of redundant equipment (e.g., two sensors monitoring the same activity) can lessen the impact of monitoring failures.105 Another strategy is to perform multiple levels of monitoring, such as configuring network-based and host- based firewalls to log connections.', 'kb-doc-04-nist-sp-800-86-p71-12', 0, 49, '04-nist-sp-800-86', 'retrieved', 'A5B9067B20D3F679507F4B0CC28856785705FFDC8206F6719E7744816D7DB236', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-13', 'doc-04-nist-sp-800-86', '', 71, '6.4 Examining and Analyzing Network Traffic Data When an event of interest has been identified, analysts assess, extract, and analyze network traffic data with the goal of determining what has happened and how the organizations systems and networks have been affected.', 'kb-doc-04-nist-sp-800-86-p71-13', 0, 41, '04-nist-sp-800-86', 'retrieved', 'B700AA7B9F5CB228A723CA481234237F0F3FC67EFD6D3099560F3D343657AA4C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-14', 'doc-04-nist-sp-800-86', '', 71, 'This process might be as simple as reviewing a few log entries on a single data source and determining that the event was a false alarm, or as complex as sequentially examining and analyzing dozens of sources (most of which might contain no relevant data), manually correlating data among several sources, then analyzing the collective data to determine the probable intent and significance of the event.', 'kb-doc-04-nist-sp-800-86-p71-14', 0, 66, '04-nist-sp-800-86', 'retrieved', 'C89448FC4A05A303205A4818C09A8C24282E03FF31A249B912A8C2D669BF098E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-15', 'doc-04-nist-sp-800-86', '', 71, 'However, even the relatively simple case of validating a few log entries can be surprisingly involved and time-consuming.', 'kb-doc-04-nist-sp-800-86-p71-15', 0, 18, '04-nist-sp-800-86', 'retrieved', '24C7B11AAA7EF31BD3830F1C16AC07A642153173D744DAAD78B71EF0B0D41B6C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-16', 'doc-04-nist-sp-800-86', '', 71, 'Although current tools (e.g., SEM software, NFAT software) can be helpful in gathering and presenting network traffic data, such tools have rather limited analysis abilities and can be used effectively only by well-trained, experienced analysts.', 'kb-doc-04-nist-sp-800-86-p71-16', 0, 35, '04-nist-sp-800-86', 'retrieved', 'A2A39958BE39C403BC643EC30ADEA8F0CF6F952871D1BCC9F54E2E905C9E372D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-17', 'doc-04-nist-sp-800-86', '', 71, 'In addition to understanding the tools, analysts should also have reasonably comprehensive knowledge of networking principles, common network and application protocols, network and application security products, and network-based threats and attack methods.106 It is also very important that analysts have knowledge of the organizations environment, such as the network architecture and the IP addresses used by critical assets (e.g., firewalls, publicly accessible', 'kb-doc-04-nist-sp-800-86-p71-17', 0, 62, '04-nist-sp-800-86', 'retrieved', 'FC74F31F2585C0DA9862239A715ED201A9289EE30DAC4428F549A8E3E228B5C1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-18', 'doc-04-nist-sp-800-86', '', 71, '105 In most organizations, the cost of redundant monitoring makes it feasible only for the highest risk areas.', 'kb-doc-04-nist-sp-800-86-p71-18', 0, 18, '04-nist-sp-800-86', 'retrieved', '4B954F78F841C11A271439436ABB9D7527AEFA16886839BFC020CCE51B0069B7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p71-19', 'doc-04-nist-sp-800-86', '', 71, '106 Helpful references for analysts include lists of commonly used protocols and their typical port numbers, and Request for Comment (RFC) documents that explain the standards for various network and application protocols.', 'kb-doc-04-nist-sp-800-86-p71-19', 0, 32, '04-nist-sp-800-86', 'retrieved', 'D4CB914707A8E8916D50882A7F5D5343A16BD88B7A4D06EFE596B16DF4D46E67', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-1', 'doc-04-nist-sp-800-86', '', 72, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE servers), as well as knowledge of the information supporting the applications and OSs used by the organization.', 'kb-doc-04-nist-sp-800-86-p72-1', 0, 25, '04-nist-sp-800-86', 'retrieved', '8E2DB91616760CA06A29A9A06F80C8EDC9DBC398AE46ED4796B9F8CE583DCBBA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-2', 'doc-04-nist-sp-800-86', '', 72, 'If analysts understand the organizations normal computing baseline, such as typical patterns of usage on systems and networks across the enterprise, they should be able to perform their work easier and faster.', 'kb-doc-04-nist-sp-800-86-p72-2', 0, 32, '04-nist-sp-800-86', 'retrieved', 'CD9748FEA2A059D44DB989C06B6A2031F98DDBB15020998C23D503ECBB589AA0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-3', 'doc-04-nist-sp-800-86', '', 72, 'Analysts should also have a firm understanding of each of the network traffic data sources, as well as access to supporting materials, such as intrusion detection signature documentation.', 'kb-doc-04-nist-sp-800-86-p72-3', 0, 28, '04-nist-sp-800-86', 'retrieved', 'B51FF83AA5C5F5A42B7D55769DA506262391A43969BE6D5A33FA3046589CFDFD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-4', 'doc-04-nist-sp-800-86', '', 72, 'Analysts should understand the characteristics and relative value of each data source so that they can locate the relevant data quickly.', 'kb-doc-04-nist-sp-800-86-p72-4', 0, 21, '04-nist-sp-800-86', 'retrieved', '49150B9D3114F86088504BEC8212E92861A35206EC50403A9E16B75AF7FB0278', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-5', 'doc-04-nist-sp-800-86', '', 72, 'Given the potential complexities of the analysis process and the extensive knowledge of networking and information security required for analyzing network traffic data effectively, a full description of techniques needed for analyzing data and drawing conclusions in complex situations is beyond the scope of this document.', 'kb-doc-04-nist-sp-800-86-p72-5', 0, 46, '04-nist-sp-800-86', 'retrieved', '16C97B9E17D96BA4E078F204A4677E1A755AF077D8FAA127165FF977866D7F75', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-6', 'doc-04-nist-sp-800-86', '', 72, 'Instead, the section focuses on the basic steps of the examination and analysis processes and highlights some significant technical issues that analysts should consider.', 'kb-doc-04-nist-sp-800-86-p72-6', 0, 24, '04-nist-sp-800-86', 'retrieved', '7852C1D0FEBD46529883BB65A9BA9EBF3D3C8B1101562C673132AD7C6C8AA19A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-7', 'doc-04-nist-sp-800-86', '', 72, '6.4.1 6.4.2 Identify an Event of Interest The first step in the examination process is the identification of an event of interest.', 'kb-doc-04-nist-sp-800-86-p72-7', 0, 22, '04-nist-sp-800-86', 'retrieved', '334F5334D8DC0607DB76AB8BF5AF044ADC9C682153A39C5DF6C7559F682DB4ED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-8', 'doc-04-nist-sp-800-86', '', 72, 'Typically, this identification is made through one of two methods: ! Someone within the organization (e.g., help desk agent, system administrator, security administrator) receives an indication, such as an automated alert or a user complaint, that there is a security or operational-related issue.', 'kb-doc-04-nist-sp-800-86-p72-8', 0, 43, '04-nist-sp-800-86', 'retrieved', '41500E22184954864D724E84C472A2CCE932EF55E5C4E1817DBA6B2561E69682', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-10', 'doc-04-nist-sp-800-86', '', 72, '! During a review of security event data (e.g., IDS monitoring, network monitoring, firewall log review), which is part of the analysts regular duties, the analyst identifies an event of interest and determines that it should be researched further.', 'kb-doc-04-nist-sp-800-86-p72-10', 0, 39, '04-nist-sp-800-86', 'retrieved', '1BF96C2383CCC26C659E5EE77B612473158B6A96BD536A6DA361D5C80F82DD83', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-11', 'doc-04-nist-sp-800-86', '', 72, 'When an event of interest has been identified, the analyst needs to know some basic information about the event as a basis for research.', 'kb-doc-04-nist-sp-800-86-p72-11', 0, 24, '04-nist-sp-800-86', 'retrieved', 'D9424F0F926E3CB68D757909CCF4442D7C145ABBFF4BEFF4FB7E382B8F661FB8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-12', 'doc-04-nist-sp-800-86', '', 72, 'In most cases, the event will have been detected through a network traffic data source, such as an IDS sensor or a firewall, so the analyst can simply be pointed to that data source for more information.', 'kb-doc-04-nist-sp-800-86-p72-12', 0, 37, '04-nist-sp-800-86', 'retrieved', '62689BA4FD7161404F0A2B2CCC8ECF9AA0D3F80490A48B80984818C430067A6F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-13', 'doc-04-nist-sp-800-86', '', 72, 'However, in some cases, such as a user complaint, it might not be apparent which data sources (if any) contain relevant information or which hosts or networks might be involved.', 'kb-doc-04-nist-sp-800-86-p72-13', 0, 30, '04-nist-sp-800-86', 'retrieved', '7E1742BB914E4B953D9636F56DE86BF34A415540351C4595657578111F6BC9CC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-14', 'doc-04-nist-sp-800-86', '', 72, 'Therefore, analysts might need to rely on more general informationfor example, reports that several systems on the fourth floor have been rebooting themselves.', 'kb-doc-04-nist-sp-800-86-p72-14', 0, 23, '04-nist-sp-800-86', 'retrieved', '2B1CA7260E0BE7B91EE40FCC43C8F19129FECF0412075ADED5EFEF09F7E9BBE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-15', 'doc-04-nist-sp-800-86', '', 72, 'Although data examination is easier if the event information is specific (e.g., IP addresses of affected systems), even general information provides the analyst with a starting point for finding the relevant data sources.', 'kb-doc-04-nist-sp-800-86-p72-15', 0, 33, '04-nist-sp-800-86', 'retrieved', 'D4BEBA09111CC76780C097F46B57717738B5D601442842481302A55BD00F95D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-16', 'doc-04-nist-sp-800-86', '', 72, 'Examine Data Sources As described in Section 6.2, organizations may have many sources of network traffic-related data.', 'kb-doc-04-nist-sp-800-86-p72-16', 0, 17, '04-nist-sp-800-86', 'retrieved', 'EAA2CFB649E3ADEC57CD7F859CAB59A81C23CCFA37D5D88DCE6A68D18450F397', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-17', 'doc-04-nist-sp-800-86', '', 72, 'A single event of interest could be noted by many of these data sources, but it may be inefficient or impractical to check each source individually.', 'kb-doc-04-nist-sp-800-86-p72-17', 0, 26, '04-nist-sp-800-86', 'retrieved', '19CA1815063C860C3D802EC877EDE19AFF545E5EB5D46417F3A1EAB72121C2E0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-18', 'doc-04-nist-sp-800-86', '', 72, 'For initial event data examination, analysts typically rely on a few primary data sources, such as an IDS console that displays alerts from all IDS sensors, or SEM or NFAT software that consolidates many other data sources and organizes the data.', 'kb-doc-04-nist-sp-800-86-p72-18', 0, 41, '04-nist-sp-800-86', 'retrieved', '440BC87677E2D43E2D4D14E7746694F3D405F0A1033B0C281BD70D7F3CA2DB1C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-19', 'doc-04-nist-sp-800-86', '', 72, 'Not only is this an efficient solution, but also in most cases the event of interest will be identified by an alert from one of these primary data sources.', 'kb-doc-04-nist-sp-800-86-p72-19', 0, 29, '04-nist-sp-800-86', 'retrieved', 'F769784F24F5DC5D8CA9D45CBFC0535A9647C67BE7614E67033075C2BC1FB3A7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-21', 'doc-04-nist-sp-800-86', '', 72, 'In general, analysts should have more confidence in original data sources than in data sources that receive normalized (modified) data from other sources.', 'kb-doc-04-nist-sp-800-86-p72-21', 0, 23, '04-nist-sp-800-86', 'retrieved', '553F49C6404D650D4873D3CE5ABB84001E516B868196D3B116333013CCE9AEA0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-22', 'doc-04-nist-sp-800-86', '', 72, 'In addition, analysts should validate data that is based on interpretation, such as IDS and SEM alerts.', 'kb-doc-04-nist-sp-800-86-p72-22', 0, 17, '04-nist-sp-800-86', 'retrieved', 'F5709D229D5C95C190D064F16722EFEB5D9BC0E8A1C6A36245A918869870CBF1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p72-23', 'doc-04-nist-sp-800-86', '', 72, 'No tool for identifying malicious activity is completely accurate; they produce both false 6-12', 'kb-doc-04-nist-sp-800-86-p72-23', 0, 14, '04-nist-sp-800-86', 'retrieved', '38514A6DB89E6E274D9E29CB056F6C89F86DC25B27C22D3D2680524FC17D0739', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-1', 'doc-04-nist-sp-800-86', '', 73, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE positives (incorrectly reporting benign activity as malicious) and false negatives (incorrectly classifying malicious activity as benign).107 Tools such as NFAT and IDS might also produce inaccurate alerts if they do not process all packets within a connection.108 Validation should be based on an analysis of additional data (e.g., raw packets, supporting information captured by other sources), a review of available information on alert validity (e.g., vendor comments on known false positives), and past experience with the tool in question.', 'kb-doc-04-nist-sp-800-86-p73-1', 0, 87, '04-nist-sp-800-86', 'retrieved', 'FDC72A16ABA40823FE1DF1679DE28C1D7CB5B5573CB8286C0C5D4A81F7C3E61D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-2', 'doc-04-nist-sp-800-86', '', 73, 'In many cases, an experienced analyst can quickly examine the supporting data and determine that an alert is a false positive and does not need further investigation.', 'kb-doc-04-nist-sp-800-86-p73-2', 0, 27, '04-nist-sp-800-86', 'retrieved', 'FF2EE776FE38D0FC29E480A607FF3C3A89E9560E61A6B89DCBD1D7F3EF5F00C0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-3', 'doc-04-nist-sp-800-86', '', 73, 'Analysts may also need to examine secondary network traffic data sources, such as host-based firewall logs and packet captures, and non-network traffic data sources, such as host OS audit logs and antivirus software logs.', 'kb-doc-04-nist-sp-800-86-p73-3', 0, 34, '04-nist-sp-800-86', 'retrieved', 'E90964A2DA23451D6B002E3581F2A6D653FBCF5262219FB6ED057426B45A7B19', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-4', 'doc-04-nist-sp-800-86', '', 73, 'The most common reasons for doing this are as follows: ! No Data on Primary Sources.', 'kb-doc-04-nist-sp-800-86-p73-4', 0, 16, '04-nist-sp-800-86', 'retrieved', '63F716DD77BD81964BD24B589D4232DADD49E342B23CA2033F5A8FA9F4B2F83D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-5', 'doc-04-nist-sp-800-86', '', 73, 'In some cases, the typical primary network traffic data sources do not contain evidence of the activity.', 'kb-doc-04-nist-sp-800-86-p73-5', 0, 17, '04-nist-sp-800-86', 'retrieved', '26DE03AFFB53A62178E399E6129C22B0B81C564823EFA0E0B6BA5564FBE8C499', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-6', 'doc-04-nist-sp-800-86', '', 73, 'For example, an attack might have occurred between two hosts on an internal network segment that is not monitored or controlled by network security devices.', 'kb-doc-04-nist-sp-800-86-p73-6', 0, 25, '04-nist-sp-800-86', 'retrieved', '781F3D8A5A87CFB43B1C9EE80C2B1AD6E8752166F510C292136097086308CE44', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-7', 'doc-04-nist-sp-800-86', '', 73, 'In these cases, analysts should identify other likely data sources and examine them for evidence.', 'kb-doc-04-nist-sp-800-86-p73-7', 0, 15, '04-nist-sp-800-86', 'retrieved', '55F04DF9D292D4B095B1D84B04498A953CC2BFCC11F6EA670EFEABA2DB3E00CF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-9', 'doc-04-nist-sp-800-86', '', 73, 'Analysts might need to examine secondary data sources if primary data sources do not contain sufficient information or analysts need to validate the data.', 'kb-doc-04-nist-sp-800-86-p73-9', 0, 24, '04-nist-sp-800-86', 'retrieved', 'B7CC627C566F071F4670BC842D971E39C27D749ED6567146EE18E612E5567B05', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-10', 'doc-04-nist-sp-800-86', '', 73, 'After reviewing one or more primary data sources, analysts should query the appropriate secondary data sources based on the pertinent data from the primary data sources.', 'kb-doc-04-nist-sp-800-86-p73-10', 0, 26, '04-nist-sp-800-86', 'retrieved', '921BB17F06497C2A6BBFADC13E4BCFEB9A1700AF3B3971FAC62C73461782660B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-11', 'doc-04-nist-sp-800-86', '', 73, 'For example, if IDS records indicate an attack against the system at IP address 10.20.30.40 with an apparent origin of IP address 10.3.0.1, querying other data sources using one or both IP addresses might uncover additional data regarding the activity.', 'kb-doc-04-nist-sp-800-86-p73-11', 0, 40, '04-nist-sp-800-86', 'retrieved', '1CF2688683A0934A94BB7C9B90DD3D160933640C8B9F6FB893067B0B45606479', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-12', 'doc-04-nist-sp-800-86', '', 73, 'Analysts also use timestamps,109 protocols, port numbers, and other common data fields to narrow their search as necessary.', 'kb-doc-04-nist-sp-800-86-p73-12', 0, 18, '04-nist-sp-800-86', 'retrieved', 'BB67B75E2F5DB7A3B42F6886623E067857F8CED8E9DB88D02F92A66A72B19F4B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-14', 'doc-04-nist-sp-800-86', '', 73, 'Occasionally, the best sources of network traffic data are located on a particular host, such as host-based firewall and IDS logs on a system that was attacked.', 'kb-doc-04-nist-sp-800-86-p73-14', 0, 27, '04-nist-sp-800-86', 'retrieved', 'C194561FD5AD6E307D4F708EE4CBC75EE1F098DA49F3FCD13E98DE331A9B7291', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-15', 'doc-04-nist-sp-800-86', '', 73, 'Although such data sources can be very helpful, their data may be altered or destroyed during a successful attack.', 'kb-doc-04-nist-sp-800-86-p73-15', 0, 19, '04-nist-sp-800-86', 'retrieved', '9E6CDD2330865512BD1CBE8E68DF6E562FDA4EA2B86776A3CAACA7F0CB115FC1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-16', 'doc-04-nist-sp-800-86', '', 73, 'If additional data is needed but cannot be located and the suspicious activity is still occurring, analysts might need to perform more data collection activities.', 'kb-doc-04-nist-sp-800-86-p73-16', 0, 25, '04-nist-sp-800-86', 'retrieved', '3D0E9D61FBD4324163339836823CBB871BC93F7ED535E4C4D2B3B6C689E7CA9E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-17', 'doc-04-nist-sp-800-86', '', 73, 'For example, an analyst could perform packet captures at an appropriate point on the network to gather more information.', 'kb-doc-04-nist-sp-800-86-p73-17', 0, 19, '04-nist-sp-800-86', 'retrieved', '5B19CD16271F706C3D7EE0DA66F451289254DE363F0C26E58340863A8ECF11EF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-18', 'doc-04-nist-sp-800-86', '', 73, 'Other ways to collect more information include configuring firewalls or routers to log more information on certain activity, setting an IDS signature to capture packets for the activity, and writing a custom IDS signature that alerts when a specific activity occurs.', 'kb-doc-04-nist-sp-800-86-p73-18', 0, 41, '04-nist-sp-800-86', 'retrieved', '0D74FB5EED6865BDEF868300B59240F7100BBB73E5F203CAFBE310CD161141CC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-20', 'doc-04-nist-sp-800-86', '', 73, 'Collecting additional data may be helpful if the activity is ongoing or intermittent; if the activity has ended, there is no opportunity to collect additional data.', 'kb-doc-04-nist-sp-800-86-p73-20', 0, 26, '04-nist-sp-800-86', 'retrieved', '647AE62E4AD20D2A1C95BC27590F5E67EF6EEB7E8F3C0F4E051CECF18AA54958', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-21', 'doc-04-nist-sp-800-86', '', 73, '107 From an analysts perspective, the concept of false negatives is important because it means that security devices sometimes fail to report attacks that they have observed.', 'kb-doc-04-nist-sp-800-86-p73-21', 0, 27, '04-nist-sp-800-86', 'retrieved', '5A35FFB0EA0B954791D1F53FD0AECFD35AE926AA74BE1773A6121ABDE4713A20', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-22', 'doc-04-nist-sp-800-86', '', 73, 'Analysts should not assume that an activity is benign if security devices have not reported it as malicious.', 'kb-doc-04-nist-sp-800-86-p73-22', 0, 18, '04-nist-sp-800-86', 'retrieved', '9F1EEAD44B680C4310396432BF4A5CDBC90AAD32FFC095F68A407B7CC8861040', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-23', 'doc-04-nist-sp-800-86', '', 73, '108 There are several possible causes for not processing all packets, including security device failure (e.g., outage, software bug), security device overload (e.g., unusually high volume of packets to process), and asynchronous routing.', 'kb-doc-04-nist-sp-800-86-p73-23', 0, 33, '04-nist-sp-800-86', 'retrieved', '9183351ED0DB88F5750E37393A9832BF0B0F0C73A4CF28DC4AB1D309F44E3A8A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-24', 'doc-04-nist-sp-800-86', '', 73, 'In asynchronous routing, the incoming packets and outgoing packets for a connection take different routes.', 'kb-doc-04-nist-sp-800-86-p73-24', 0, 15, '04-nist-sp-800-86', 'retrieved', 'E170EFC7038D972541DEC0A673BB54DEBF2080DDAAA97DF550DF51457259D25B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-25', 'doc-04-nist-sp-800-86', '', 73, 'If only one of these routes is monitored by a device such as an IDS sensor, the device can see only part of the connection.', 'kb-doc-04-nist-sp-800-86-p73-25', 0, 25, '04-nist-sp-800-86', 'retrieved', '3754E6262B4107E9D33B39C933728A169B86DA2FB194EAC1CC23E0CCCAA4186D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-26', 'doc-04-nist-sp-800-86', '', 73, '109 As mentioned in Section 4.3.3, organizations should use time synchronization to keep systems clocks consistent.', 'kb-doc-04-nist-sp-800-86-p73-26', 0, 16, '04-nist-sp-800-86', 'retrieved', 'C4DE6CDE3A00425D99E7A771E537DD30B8F1DAFFAD7624AC02EF0148B44EA4E8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
