INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-27', 'doc-04-nist-sp-800-86', '', 73, 'Correlating an event among multiple network traffic sources is easier and more effective if the clocks are in synch.', 'kb-doc-04-nist-sp-800-86-p73-27', 0, 19, '04-nist-sp-800-86', 'retrieved', '828E4A869489144EB64AD3DD74C2E5E046FBDC78549BD07A7F9F93DC511CF9B8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-28', 'doc-04-nist-sp-800-86', '', 73, 'If event data sources are on separate devices, timestamps can be helpful in confirming the path that the packets used.', 'kb-doc-04-nist-sp-800-86-p73-28', 0, 20, '04-nist-sp-800-86', 'retrieved', 'D7E48F001A77F83DC2299E5DF974D7AE988B8DFF48608494DC3569B5133AFEC4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p73-29', 'doc-04-nist-sp-800-86', '', 73, '(When packets traverse a network, it takes them some amount of time to get from one device to the next.) 6-13', 'kb-doc-04-nist-sp-800-86-p73-29', 0, 21, '04-nist-sp-800-86', 'retrieved', '710D26E9475222E3B871997F411B7B50DE21BA267BF9553E61950622BA1DC22F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
