INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-1', 'doc-04-nist-sp-800-86', '', 74, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 6.4.2.1 Data Source Value As described in Section 6.2, organizations typically have many different sources of network traffic data.', 'kb-doc-04-nist-sp-800-86-p74-1', 0, 27, '04-nist-sp-800-86', 'retrieved', '4D58F830645E0C071BB5EA333075281221A772E63CA63AEAD3B63E52A5533879', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-2', 'doc-04-nist-sp-800-86', '', 74, 'Because the information collected by these sources varies, the sources may have different value to the analyst, both in general and for specific cases.', 'kb-doc-04-nist-sp-800-86-p74-2', 0, 24, '04-nist-sp-800-86', 'retrieved', '72D3A0E24F9A8A1E04388EBC9FBC5A0F92CC765E950A20352744C22F67A604E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-3', 'doc-04-nist-sp-800-86', '', 74, 'The following items describe the typical value of the most common data sources in network forensics: ! IDS Software.', 'kb-doc-04-nist-sp-800-86-p74-3', 0, 19, '04-nist-sp-800-86', 'retrieved', '948FBC186FC82BE7A3733B0211A182F5E1852AFA30FC89F1219B8E83BA368028', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-5', 'doc-04-nist-sp-800-86', '', 74, 'Not only do IDSs typically attempt to identify malicious network traffic at all TCP/IP layers, but also they log many data fields (and sometimes raw packets) that can be useful in validating events and correlating them with other data sources.', 'kb-doc-04-nist-sp-800-86-p74-5', 0, 40, '04-nist-sp-800-86', 'retrieved', 'D5BC7BC4A0CDFF1936BF8F582027E62EA0267786EB26FABE37C666BED099FF30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-6', 'doc-04-nist-sp-800-86', '', 74, 'Nevertheless, as noted previously, IDS software does produce false positives, so IDS alerts should be validated.', 'kb-doc-04-nist-sp-800-86-p74-6', 0, 16, '04-nist-sp-800-86', 'retrieved', '5094EFAA4D7BE6BF55F541B5A4EF9231FCF99D512480BDC2FDFCF0EAEC98BCD6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-7', 'doc-04-nist-sp-800-86', '', 74, 'The extent to which this can be done depends on the amount of data recorded related to the alert and the information available to the analyst about the signature characteristics or anomaly detection method that triggered the alert.', 'kb-doc-04-nist-sp-800-86-p74-7', 0, 38, '04-nist-sp-800-86', 'retrieved', '1ADD9543B526268F404968E5780414FE6486065C779EE2CF84FE9A87671615AE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-9', 'doc-04-nist-sp-800-86', '', 74, 'Ideally, SEM can be extremely useful for forensics because it can automatically correlate events among several data sources, then extract the relevant information and present it to the user.', 'kb-doc-04-nist-sp-800-86-p74-9', 0, 29, '04-nist-sp-800-86', 'retrieved', 'BEBDA6BF13C48ACA8943924AE8023450EAEE5516BD28C18E4647DD4C385F9164', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-10', 'doc-04-nist-sp-800-86', '', 74, 'However, because SEM software functions by bringing in data from many other sources, the value of SEM depends on which data sources are fed into it, how reliable each data source is, and how well the software can normalize the data and correlate events.', 'kb-doc-04-nist-sp-800-86-p74-10', 0, 44, '04-nist-sp-800-86', 'retrieved', 'F13E8BADC07F264BB4C594F12A5397FDC71BADC367D31DD64CC9F15FEA49B145', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-12', 'doc-04-nist-sp-800-86', '', 74, 'NFAT software is designed specifically to aid in network traffic analysis, so it is valuable if it has monitored an event of interest.', 'kb-doc-04-nist-sp-800-86-p74-12', 0, 23, '04-nist-sp-800-86', 'retrieved', '5D812F773E159AA30DB52EA249A7103F610CC0567F2C58292AFF237BC2FD9780', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-13', 'doc-04-nist-sp-800-86', '', 74, 'NFAT software usually offers features that support analysis, such as traffic reconstruction and visualization; Section 6.2.6 describes these in more depth.', 'kb-doc-04-nist-sp-800-86-p74-13', 0, 21, '04-nist-sp-800-86', 'retrieved', 'BEA543A8145519F15D1267D65401C70E35480109B5269F133308D22325E95015', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-16', 'doc-04-nist-sp-800-86', '', 74, 'Analyzing the data over time can indicate overall trends, such as an increase in blocked connection attempts.', 'kb-doc-04-nist-sp-800-86-p74-16', 0, 17, '04-nist-sp-800-86', 'retrieved', '67833403915E7EC6995481673DEDE198112A5C31DAEBDAF6BF1A8C6E9E8B5401', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-17', 'doc-04-nist-sp-800-86', '', 74, 'However, because these sources typically record little information about each event, the data provides little insight into the nature of the events.', 'kb-doc-04-nist-sp-800-86-p74-17', 0, 22, '04-nist-sp-800-86', 'retrieved', '1BDED7B19A97DABB232E545DD969F8CC3474CE1209CC51287DC1AAA9AC9B0ECE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-18', 'doc-04-nist-sp-800-86', '', 74, 'Also, many events might be logged each day, so the sheer volume of data can be overwhelming.', 'kb-doc-04-nist-sp-800-86-p74-18', 0, 17, '04-nist-sp-800-86', 'retrieved', '0E1D61A9BADB0DDCFF228B5F2E8AA79B5FF61BA5512E6A725A54D2DA555CF355', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-20', 'doc-04-nist-sp-800-86', '', 74, 'For example, if a host is compromised and a network IDS sensor detected the attack, querying the firewall logs for events involving the apparent attacking IP address might confirm where the attack entered the network and might indicate other hosts that the attacker attempted to compromise.', 'kb-doc-04-nist-sp-800-86-p74-20', 0, 46, '04-nist-sp-800-86', 'retrieved', 'E1DDDA7BC7B8A71245156357E52F2ABD47221AB062F6C4622D12A30644A1EEA5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-21', 'doc-04-nist-sp-800-86', '', 74, 'In addition, address mapping (e.g., NAT) performed by these devices is important for network forensics because the apparent IP address of an attacker or a victim might actually have been used by hundreds or thousands of hosts.', 'kb-doc-04-nist-sp-800-86-p74-21', 0, 37, '04-nist-sp-800-86', 'retrieved', '19E688E8ED244B22BBAC24F863A4E3BDCBFB2DFF794337F3FFE682D448118FBF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-22', 'doc-04-nist-sp-800-86', '', 74, 'Fortunately, analysts usually can review the logs to determine which internal address was in use.', 'kb-doc-04-nist-sp-800-86-p74-22', 0, 15, '04-nist-sp-800-86', 'retrieved', '1DFC857DB47C2E1E5E91A4FC132AEE247FED0039D25F863E258FDBA711DC7AAF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-24', 'doc-04-nist-sp-800-86', '', 74, 'DHCP servers typically can be configured to log each IP address assignment and the associated MAC address, along with a timestamp.', 'kb-doc-04-nist-sp-800-86-p74-24', 0, 21, '04-nist-sp-800-86', 'retrieved', '529BE28B0A67C2BF42254B0ED9D33AEE383245B7FD78D2611B6EA3225C0A31FD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-25', 'doc-04-nist-sp-800-86', '', 74, 'This information can be helpful to analysts in identifying which host performed an activity using a particular IP address.', 'kb-doc-04-nist-sp-800-86-p74-25', 0, 19, '04-nist-sp-800-86', 'retrieved', '5106274BD5AC927AA1F7651C8147EA472E77113782A57195F3EBB2E843EE9C34', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-26', 'doc-04-nist-sp-800-86', '', 74, 'However, analysts should be mindful of the possibility that attackers on an organizations internal networks falsified their MAC addresses or IP addresses, a practice known as spoofing.', 'kb-doc-04-nist-sp-800-86-p74-26', 0, 27, '04-nist-sp-800-86', 'retrieved', 'FAD9BC4584D9DEFEDF4E7AE58B51F62353B19545E6D2B41264519B2A3F4843D0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-28', 'doc-04-nist-sp-800-86', '', 74, 'Of all the network traffic data sources, packet sniffers can collect the most information on network activity.', 'kb-doc-04-nist-sp-800-86-p74-28', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A02CFD71D46751FC0578A04818D97A366C4CE7672F00193FB33DABF12A6E4A4B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-29', 'doc-04-nist-sp-800-86', '', 74, 'However, sniffers might capture huge volumes of benign data as wellmillions or billions of packetsand typically provide no indication as to which packets might contain malicious activity.', 'kb-doc-04-nist-sp-800-86-p74-29', 0, 27, '04-nist-sp-800-86', 'retrieved', '5A57AB7CFB22822B76EC3B51E3E889B7A2C4CE79FB238A89B0637EF4C0DF9EF3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-30', 'doc-04-nist-sp-800-86', '', 74, 'In most cases, packet sniffers are best used to provide more data on events that other devices or software has identified as possibly malicious.', 'kb-doc-04-nist-sp-800-86-p74-30', 0, 24, '04-nist-sp-800-86', 'retrieved', '3ED6E6B7F90223FCEDA601352E5677AA7A36A7EC55ED67DEBCA5F995253CFB40', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
