INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p74-31', 'doc-04-nist-sp-800-86', '', 74, 'Some organizations record most or all packets for some period of time so that when an incident occurs, 6-14', 'kb-doc-04-nist-sp-800-86-p74-31', 0, 19, '04-nist-sp-800-86', 'retrieved', 'DB6B079DD873CDD7E02CB4AC6883B0F26D7F867B6F346A940E7B4B131C8CDAB2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
