INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-1', 'doc-04-nist-sp-800-86', '', 75, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the raw network data is available for examination and analysis.110 Packet sniffer data is best reviewed with a protocol analyzer, which interprets the data for the analyst based on knowledge of protocol standards and common implementations.', 'kb-doc-04-nist-sp-800-86-p75-1', 0, 44, '04-nist-sp-800-86', 'retrieved', '40C39A01B6DC9735A770BFCA9415FE4240D9A93E6ADF36D0668B33D7AEA30955', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-3', 'doc-04-nist-sp-800-86', '', 75, 'Network monitoring software is helpful in identifying significant deviations from normal traffic flows, such as those caused by DDoS attacks, during which, hundreds or thousands of systems launch simultaneous attacks against particular hosts or networks.', 'kb-doc-04-nist-sp-800-86-p75-3', 0, 35, '04-nist-sp-800-86', 'retrieved', '43DD176DA3B6FA8935DB1C8FAC096C4794D5A19875AF26E583A4D48B71F94E2D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-4', 'doc-04-nist-sp-800-86', '', 75, 'Network monitoring software can document the impact of these attacks on network bandwidth and availability, as well as providing information about the apparent targets.', 'kb-doc-04-nist-sp-800-86-p75-4', 0, 24, '04-nist-sp-800-86', 'retrieved', '5149D8524D0CB30F15124F46FC26230CB931D103AFC01FEC25CBCFDFDCD2152E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-5', 'doc-04-nist-sp-800-86', '', 75, 'Traffic flow data can also be helpful in investigating suspicious activity identified by other sources.', 'kb-doc-04-nist-sp-800-86-p75-5', 0, 15, '04-nist-sp-800-86', 'retrieved', '005644676C7ABE33F4028D772E71C24D1ACF8D9B2119E75101805B25BB826BA6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-6', 'doc-04-nist-sp-800-86', '', 75, 'For example, it might indicate whether a particular communications pattern has occurred in the preceding days or weeks.', 'kb-doc-04-nist-sp-800-86-p75-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '7F9391097F19BEE38ABAF1F9209F721458FF1412CB8E7A75DDEAA599042DEAB8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-8', 'doc-04-nist-sp-800-86', '', 75, 'Information from an ISP is primarily of value in tracing an attack back to its source, particularly when the attack uses spoofed IP addresses.', 'kb-doc-04-nist-sp-800-86-p75-8', 0, 24, '04-nist-sp-800-86', 'retrieved', '530AE90C1886F13861BE2E23DEA56D4563DAA5B14CE83E2FB33919B2B37AE68E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-10', 'doc-04-nist-sp-800-86', '', 75, '6.4.2.2 Examination and Analysis Tools Because network forensics can be performed for many purposes with dozens of data source types, analysts may use several different tools on a regular basis, each well-suited to certain situations.', 'kb-doc-04-nist-sp-800-86-p75-10', 0, 35, '04-nist-sp-800-86', 'retrieved', '82F6789C427DCD3020CFCDF9AF552664136FC2F6067E7877E491E2D719B80598', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-11', 'doc-04-nist-sp-800-86', '', 75, 'Analysts should be aware of the possible approaches to examining and analyzing network traffic data and should select the best tools for each case, rather than applying the same tool to every situation.', 'kb-doc-04-nist-sp-800-86-p75-11', 0, 33, '04-nist-sp-800-86', 'retrieved', 'C5C1B91055ED7AECB106EA1258DC4AF5A6745D0A44AC5671A528888DB9A83EEF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-12', 'doc-04-nist-sp-800-86', '', 75, 'Analysts should also be mindful of the shortcomings of tools; for example, a particular protocol analyzer might not be able to translate a certain protocol or handle unexpected protocol data (e.g., illegal data field value).', 'kb-doc-04-nist-sp-800-86-p75-12', 0, 35, '04-nist-sp-800-86', 'retrieved', '79E5B30FBFF6273A13C2B8F3FCD2F66606DBF154A40CAED4D4546888561E1AA5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-13', 'doc-04-nist-sp-800-86', '', 75, 'It can be helpful to have an alternate tool available that might not have the same deficiency.', 'kb-doc-04-nist-sp-800-86-p75-13', 0, 17, '04-nist-sp-800-86', 'retrieved', '27BA901FD212B5275B4730B648A4AF0C1777666F8DC96F7C2C22E8F8CB7DFF2E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-15', 'doc-04-nist-sp-800-86', '', 75, 'For example, an analyst might need to search data without any concrete information that could narrow the search.', 'kb-doc-04-nist-sp-800-86-p75-15', 0, 18, '04-nist-sp-800-86', 'retrieved', 'A5E04BC10492B28E4689DFBCCA0DFFEF159196BEB0D4C4A96B3F8830F6B98722', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-16', 'doc-04-nist-sp-800-86', '', 75, 'This is most likely to occur when the analyst is responsible for performing periodic or ongoing reviews of security event data logs and alerts.', 'kb-doc-04-nist-sp-800-86-p75-16', 0, 24, '04-nist-sp-800-86', 'retrieved', '3C0361EC81519881E2638DE3A9411BDC29F89C1ED5129F5D289BFC83570B3D61', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-17', 'doc-04-nist-sp-800-86', '', 75, 'If the volume of log entries and alerts is low, reviewing the data is relatively easybut in some cases, there may be many thousands of events listed per day.', 'kb-doc-04-nist-sp-800-86-p75-17', 0, 29, '04-nist-sp-800-86', 'retrieved', '75B9DEBB62FE29E36E0AC38596DA2AEF2324A570FE0B51686718DB53EDE91340', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-18', 'doc-04-nist-sp-800-86', '', 75, 'When a manual data review is not possible or practical, analysts should use an automated solution that filters the events and presents the analysts with only the events that are most likely to be of interest.', 'kb-doc-04-nist-sp-800-86-p75-18', 0, 36, '04-nist-sp-800-86', 'retrieved', '072623728E9BEFAEACD80597349A44905F0FB0F22D99567AE4C3CF7B1C6C5C77', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-19', 'doc-04-nist-sp-800-86', '', 75, 'One effective review technique is to import the logs into a database and run queries against them, either eliminating types of activity highly likely to be benign and reviewing the rest, or focusing on the types of activity most likely to be malicious.', 'kb-doc-04-nist-sp-800-86-p75-19', 0, 43, '04-nist-sp-800-86', 'retrieved', '4D732BA892937A5E3D2B5B2DDC9DB74961C83558375144B2F3F45912BD45EAE6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-20', 'doc-04-nist-sp-800-86', '', 75, 'For example, if the initial suspicion is that the server was compromised through HTTP activity, then log filtering might start by eliminating everything except HTTP activity from consideration.', 'kb-doc-04-nist-sp-800-86-p75-20', 0, 28, '04-nist-sp-800-86', 'retrieved', 'E8E668EA3379236D068F9B1A8EC5B0220144A6C89525AD9DD1AB3E180B8E037E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-21', 'doc-04-nist-sp-800-86', '', 75, 'An analyst who is very familiar with a particular data source can generally perform a blind search on it relatively quickly, but, on unfamiliar data sources, blind searches can take an extremely long time, because there might be little or no basis for eliminating certain types of activity from consideration.', 'kb-doc-04-nist-sp-800-86-p75-21', 0, 50, '04-nist-sp-800-86', 'retrieved', '076826388D1427A65E6A87E2CFDCDA91B53983AE99BBD2E909ED8BCE28E40470', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-24', 'doc-04-nist-sp-800-86', '', 75, 'This is most often used to represent network traffic flows visually, which can be very helpful in troubleshooting operational issues and identifying misuse.', 'kb-doc-04-nist-sp-800-86-p75-24', 0, 23, '04-nist-sp-800-86', 'retrieved', 'D81CE54EE4834992129B05DCD4D6AED33483525CC6D28E644840DABF615FBB74', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-25', 'doc-04-nist-sp-800-86', '', 75, 'For example, attackers might use covert channelsusing protocols in unintended ways to secretly communicate information (e.g., setting certain values in network protocol headers or application payloads).', 'kb-doc-04-nist-sp-800-86-p75-25', 0, 26, '04-nist-sp-800-86', 'retrieved', 'CC6A8A60B26FDD50114A81445F98EE1AB52470D0A9C227C9869ADBD07E6A7711', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-26', 'doc-04-nist-sp-800-86', '', 75, 'The use of covert channels is generally hard to detect, but one useful method is identifying deviations in expected network traffic flows.', 'kb-doc-04-nist-sp-800-86-p75-26', 0, 22, '04-nist-sp-800-86', 'retrieved', 'E64F0465684963EC2421632D402A4515B1EB19BE8D67008324E243BC844269DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p75-27', 'doc-04-nist-sp-800-86', '', 75, '110 Many NFAT programs, as described in Section 6.2.6, provide this function, as well as additional capabilities.', 'kb-doc-04-nist-sp-800-86-p75-27', 0, 17, '04-nist-sp-800-86', 'retrieved', '83ACCA37A8AA1893AE6A62DBC92300B44036F6AD8BA912056AFC3F0707B44B7C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
