INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-1', 'doc-04-nist-sp-800-86', '', 76, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Visualization tools are often included in NFAT software, as described in Section 6.2.6.', 'kb-doc-04-nist-sp-800-86-p76-1', 0, 21, '04-nist-sp-800-86', 'retrieved', '918565FB5AF590F721FA9732F26D24E4F18504273372DDC1C5F3C6A6EED287C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-2', 'doc-04-nist-sp-800-86', '', 76, 'Some visualization tools can perform traffic reconstructionby using timestamp and sequential data fields, the tools can determine the sequence of events and graphically display how the packets traversed the organizations networks.', 'kb-doc-04-nist-sp-800-86-p76-2', 0, 31, '04-nist-sp-800-86', 'retrieved', '69DCBA434AE5FED73FBF194626B82CEFFF4C0931A741C6A7973548D15227D72C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
