INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-3', 'doc-04-nist-sp-800-86', '', 76, 'Some visualization tools can also be used to display other types of security event data.', 'kb-doc-04-nist-sp-800-86-p76-3', 0, 15, '04-nist-sp-800-86', 'retrieved', '3626869B5CD7B47F8819D8B7950D958F633B28932DA1155E234F97C77951E54D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-4', 'doc-04-nist-sp-800-86', '', 76, 'For example, an analyst could import intrusion detection records into a visualization tool, which would then display the data according to several different characteristics, such as source or destination IP address or port.', 'kb-doc-04-nist-sp-800-86-p76-4', 0, 33, '04-nist-sp-800-86', 'retrieved', '704C35DD1D3E30279E385D1E1869FFAD4C6217940A350438D7B14FF8B77468EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-5', 'doc-04-nist-sp-800-86', '', 76, 'An analyst could then suppress the display of known good activity so that only unknown events are shown.', 'kb-doc-04-nist-sp-800-86-p76-5', 0, 18, '04-nist-sp-800-86', 'retrieved', '794D69D1BF01254B0DDAA94496F967DAE917273217EC2AA7DBDFC21D74BAF6B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-6', 'doc-04-nist-sp-800-86', '', 76, 'Although visualization tools can be very effective for analyzing certain types of data, analysts typically experience a steep learning curve with such tools.', 'kb-doc-04-nist-sp-800-86-p76-6', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B72DF6B11BB5F366DA05F329C94A44CE18066361E43CB621E6B9E677BCAEDC5F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-7', 'doc-04-nist-sp-800-86', '', 76, 'Importing data into the tool and displaying it is usually relatively straightforward, but learning how to use the tool efficiently to reduce large datasets to a few events of interest can take considerable effort.', 'kb-doc-04-nist-sp-800-86-p76-7', 0, 34, '04-nist-sp-800-86', 'retrieved', '5D8606E2F64C1464CC2952993136D9C150C38F70547E1DB2BCB58765FA26C2D9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-9', 'doc-04-nist-sp-800-86', '', 76, 'Although these tools generally lack visualization capabilities, they can turn individual packets into data streams and provide sequential context for activities.', 'kb-doc-04-nist-sp-800-86-p76-9', 0, 21, '04-nist-sp-800-86', 'retrieved', '16C8ECAD23C8F4820C8D3E0F4AA4E014575C1EED2534E3F23CA8C7C6CD8F86E9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-10', 'doc-04-nist-sp-800-86', '', 76, '6.4.3 Draw Conclusions One of the most challenging aspects of network forensics is that the available data is typically not comprehensive.', 'kb-doc-04-nist-sp-800-86-p76-10', 0, 21, '04-nist-sp-800-86', 'retrieved', 'BB27020F41CD9707B38857BA10E3FAFE020B523D071CB9F78979E693D629C80D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-11', 'doc-04-nist-sp-800-86', '', 76, 'In many cases, if not most, some network traffic data has not been recorded and consequently has been lost.', 'kb-doc-04-nist-sp-800-86-p76-11', 0, 19, '04-nist-sp-800-86', 'retrieved', '731550BFA8B877AE739004234336F2920146CF53DBB57C6723DA64150EB73B77', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-12', 'doc-04-nist-sp-800-86', '', 76, 'Generally, analysts should think of the analysis process as a methodical approach that develops conclusions based on the data that is available and assumptions regarding the missing data (which should be based on technical knowledge and expertise).', 'kb-doc-04-nist-sp-800-86-p76-12', 0, 37, '04-nist-sp-800-86', 'retrieved', '666C9D4D18A98360986F4F6B1A315CDF0AE7F1BF0A1A3ECA597573AA83C841F2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-13', 'doc-04-nist-sp-800-86', '', 76, 'Although analysts should strive to locate and examine all available data regarding an event, this is not practical in some cases, particularly when there are many redundant data sources.', 'kb-doc-04-nist-sp-800-86-p76-13', 0, 29, '04-nist-sp-800-86', 'retrieved', '8A897B5A4D822F0E0E08E25712D0E85388EBE69EC1E90E8D073CEC5C563F36B1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-14', 'doc-04-nist-sp-800-86', '', 76, 'The analyst should eventually locate, validate, and analyze enough data to be able to reconstruct the event, understand its significance, and determine its impact.', 'kb-doc-04-nist-sp-800-86-p76-14', 0, 24, '04-nist-sp-800-86', 'retrieved', '933D89E761F9A9D863ABC95BA90902D1B771328D22C4EC56DEF17CDE66944438', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-15', 'doc-04-nist-sp-800-86', '', 76, 'In many cases, additional data is available from sources other than network trafficrelated sources (e.g., data files or host OSs).', 'kb-doc-04-nist-sp-800-86-p76-15', 0, 20, '04-nist-sp-800-86', 'retrieved', '23EB4458EF4A2D1E8956D3A849A235D005B1D2EF731A09E6A5AC7230E6D318CB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-16', 'doc-04-nist-sp-800-86', '', 76, 'Section 8 provides examples of how analysis can correlate this other data with data from network traffic to get a more accurate and comprehensive view of what occurred.', 'kb-doc-04-nist-sp-800-86-p76-16', 0, 28, '04-nist-sp-800-86', 'retrieved', '761036610649EE802EC23406D2492024622DD54DDE842821B649648B01909D6C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-17', 'doc-04-nist-sp-800-86', '', 76, 'Generally, analysts should focus on identifying the most important characteristics of the activity and assessing the negative impact it has caused or may cause the organization.', 'kb-doc-04-nist-sp-800-86-p76-17', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A402DBFFB5F6BED0DC95F736A96102A4DBFD166737069720D6596AEC5FA93F8C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-18', 'doc-04-nist-sp-800-86', '', 76, 'Other actions, such as determining the identity of an external attacker, are typically time-intensive and difficult to accomplish, and do not aid the organization in correcting the operational issues or security weaknesses.', 'kb-doc-04-nist-sp-800-86-p76-18', 0, 32, '04-nist-sp-800-86', 'retrieved', '7C5090728598E81B7AD139893A723DD0235B8F01E9EFB4A2F954D3D890B071D9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-19', 'doc-04-nist-sp-800-86', '', 76, 'Determining the intent of an attacker is also very difficult; for example, an unusual connection attempt could be caused by an attacker, malicious code, misconfigured software, or an incorrect keystroke, among other causes.', 'kb-doc-04-nist-sp-800-86-p76-19', 0, 33, '04-nist-sp-800-86', 'retrieved', '18C166A16B43084BBB9B66F44070A38D4DAA611D5E1AB8A1649BB9076642ACCF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-20', 'doc-04-nist-sp-800-86', '', 76, 'Although understanding intent is important in some cases, the negative impact of the event should be the primary concern.', 'kb-doc-04-nist-sp-800-86-p76-20', 0, 19, '04-nist-sp-800-86', 'retrieved', '5EB29057E20DD4BCB03F36963D53B462DB7BDECBF7D4146F3FC009DFAC20C4FE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-21', 'doc-04-nist-sp-800-86', '', 76, 'Establishing the identity of the attacker might be important to the organization, particularly when criminal activity has occurred, but in other cases it should be weighed against other important goals to put it into perspective.', 'kb-doc-04-nist-sp-800-86-p76-21', 0, 35, '04-nist-sp-800-86', 'retrieved', '5F26FD56D4EAB77F1C114B90C8C56667BD0086BD7C63A22B261742EFE045A17A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-22', 'doc-04-nist-sp-800-86', '', 76, 'The focus of the investigation should be determined at the onset by the appropriate parties, who should decide if learning the identity of the attacker is vital.', 'kb-doc-04-nist-sp-800-86-p76-22', 0, 27, '04-nist-sp-800-86', 'retrieved', '847C97EACBE1202CA34CF64AF88520A6E8D32DDDC1A6C606A67EC8926CC5D1CF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-23', 'doc-04-nist-sp-800-86', '', 76, 'It is particularly important to seek the advice of legal counsel when developing policies and procedures related to making such decisions, as well as when guidance is needed for a particular situation.', 'kb-doc-04-nist-sp-800-86-p76-23', 0, 32, '04-nist-sp-800-86', 'retrieved', '3784D240AC6770A07C5A606BCD8ADCE7B58C0574A2FD2D81B506EBE022BD7916', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-24', 'doc-04-nist-sp-800-86', '', 76, 'Organizations should be interested not only in analyzing real events, but also in understanding the causes of false alarms.', 'kb-doc-04-nist-sp-800-86-p76-24', 0, 19, '04-nist-sp-800-86', 'retrieved', '4706806898A0AF22E94C7981F82A719E8650EE4F59A869D3A272AE582B06734C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-25', 'doc-04-nist-sp-800-86', '', 76, 'For example, analysts are often well-positioned to identify the root causes of IDS false positives.', 'kb-doc-04-nist-sp-800-86-p76-25', 0, 15, '04-nist-sp-800-86', 'retrieved', 'D15F458B838F00A4513C39EF63113A819890DC55365C4DEA81019C98AF39BBBB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p76-26', 'doc-04-nist-sp-800-86', '', 76, 'As merited, analysts should recommend changes to security event data sources that improve detection accuracy.', 'kb-doc-04-nist-sp-800-86-p76-26', 0, 15, '04-nist-sp-800-86', 'retrieved', 'ABB275458F9614D33440BA48D58F02B34B207F2A757844A334B4DBD6CE78EE52', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-2', 'doc-04-nist-sp-800-86', '', 77, 'Attacker Identification When analyzing most attacks, identifying the attacker is not an immediate, primary concern: ensuring that the attack is stopped and recovering systems and data are the main interests.', 'kb-doc-04-nist-sp-800-86-p77-2', 0, 30, '04-nist-sp-800-86', 'retrieved', '4E26F598FC71C8F0EBAFCA0249F62D695E214EC44A4D6FA18376F27E6EC7EDBD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-3', 'doc-04-nist-sp-800-86', '', 77, 'If an attack is ongoing, such as an extended denial of service attack, organizations might want to identify the IP address used by the attacker so that the attack can be stopped.', 'kb-doc-04-nist-sp-800-86-p77-3', 0, 32, '04-nist-sp-800-86', 'retrieved', '8F86BFEDC1BD5031E366F9631B2D2F576D629F485262578F8322E80F24D88983', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-5', 'doc-04-nist-sp-800-86', '', 77, 'The following items explain potential issues involving the IP addresses apparently used to conduct an attack: ! Spoofed IP Addresses.', 'kb-doc-04-nist-sp-800-86-p77-5', 0, 20, '04-nist-sp-800-86', 'retrieved', '9F110E56BEA0BB4F934733DC998ACEAFB99A78A03800A09138839E176D3404AB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-7', 'doc-04-nist-sp-800-86', '', 77, 'Spoofing is far more difficult to perform successfully for attacks that require connections to be established, so it is most commonly used in cases where connections are not needed.111 When packets are spoofed, usually the attacker has no interest in seeing the response.', 'kb-doc-04-nist-sp-800-86-p77-7', 0, 43, '04-nist-sp-800-86', 'retrieved', 'B084849E070861260FEE878585BCF1146A41FF2A7F11CD9D16CB4DD2509BB538', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-8', 'doc-04-nist-sp-800-86', '', 77, 'This is not always trueattackers could spoof an address from a subnet that they monitor, so that when the response goes to that system, they can sniff it from the network.', 'kb-doc-04-nist-sp-800-86-p77-8', 0, 31, '04-nist-sp-800-86', 'retrieved', 'EE9D145B73416E3EED1AC0E911B2D8956AF0EA7CCB8AC13801CF678FB16040B5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-9', 'doc-04-nist-sp-800-86', '', 77, 'Sometimes spoofing occurs by accident, such as an attacker misconfiguring a tool and accidentally using internal NAT addresses.', 'kb-doc-04-nist-sp-800-86-p77-9', 0, 18, '04-nist-sp-800-86', 'retrieved', 'B594175EA8F34F0F700493FDC8ABBF663BEB9FD72757E689B8046214F3219046', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-10', 'doc-04-nist-sp-800-86', '', 77, 'Sometimes an attacker spoofs a particular address on purposefor example, the spoofed address might be the actual intended target of the attack, and the organization seeing the activity might simply be a middleman.', 'kb-doc-04-nist-sp-800-86-p77-10', 0, 33, '04-nist-sp-800-86', 'retrieved', 'EB40438F8A016EAFC9C1D8B61EBD3B65AF4EA93E707027114BD5097AA25E9C4F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-12', 'doc-04-nist-sp-800-86', '', 77, 'Some attacks appear to use hundreds or thousands of different source IP addresses.', 'kb-doc-04-nist-sp-800-86-p77-12', 0, 13, '04-nist-sp-800-86', 'retrieved', 'C7A11A98457EB9CBFE02417F660F7AB6D898B20BE05122F92DAF2FEAA6790666', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-13', 'doc-04-nist-sp-800-86', '', 77, 'Sometimes this appearance reflects realityfor example, DDoS attacks typically rely on large numbers of compromised machines performing a coordinated attack.', 'kb-doc-04-nist-sp-800-86-p77-13', 0, 20, '04-nist-sp-800-86', 'retrieved', '5D63DBEC75F040B8E7F9EA2058BD071B6C883164DBF783863DA64CDB62595620', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-14', 'doc-04-nist-sp-800-86', '', 77, 'Sometimes this appearance is illusoryan attack might not require the use of real source IP addresses, so the attacker generates many different fake IP addresses to add confusion.', 'kb-doc-04-nist-sp-800-86-p77-14', 0, 28, '04-nist-sp-800-86', 'retrieved', '9E5C3DFC00B7ADC49248511829B13E4810D20F3E19D7E41225C19388BE3C71B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-15', 'doc-04-nist-sp-800-86', '', 77, 'Sometimes attackers will use one real IP address and many fake ones; in that case, it might be possible to identify the real IP address by looking for other network activity occurring before or after the attack that uses any of the same IP addresses.', 'kb-doc-04-nist-sp-800-86-p77-15', 0, 45, '04-nist-sp-800-86', 'retrieved', 'CD8344CC3DD05B2329E91EEB1F981C0D47E135F75950044DB618352F19009DD9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-16', 'doc-04-nist-sp-800-86', '', 77, 'Finding a match does not confirm that it was the attackers address; the attacker could have inadvertently or purposely spoofed a legitimate IP address that happened to be interacting with the organization.', 'kb-doc-04-nist-sp-800-86-p77-16', 0, 32, '04-nist-sp-800-86', 'retrieved', 'A00E5B45F80600642967ED27508C3FD5F6950062FA44E88CEF3849483268A506', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-18', 'doc-04-nist-sp-800-86', '', 77, 'Because IP addresses are often assigned dynamically, the system currently at a particular IP address might not be the same system that was there when the attack occurred.', 'kb-doc-04-nist-sp-800-86-p77-18', 0, 28, '04-nist-sp-800-86', 'retrieved', 'F33418B8C98194CA285B68774B70B1C756C79CDAFBDC282471581D395D2A58A4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-19', 'doc-04-nist-sp-800-86', '', 77, 'In addition, many IP addresses do not belong to end-user systems, but instead to network infrastructure components that substitute their IP address for the actual source address, such as a firewall performing NAT.', 'kb-doc-04-nist-sp-800-86-p77-19', 0, 33, '04-nist-sp-800-86', 'retrieved', '43994DE9053A9F26CB3164778A66878EDC66F0524E40A8AC52125EE77C707999', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-20', 'doc-04-nist-sp-800-86', '', 77, 'Some attackers use anonymizers, which are intermediate servers that perform activity on a users behalf to preserve the users privacy.', 'kb-doc-04-nist-sp-800-86-p77-20', 0, 20, '04-nist-sp-800-86', 'retrieved', '8855D0C8E3175290CFDF1D8A7F4C047205CE128EC165B2429D932979B82A0FED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-21', 'doc-04-nist-sp-800-86', '', 77, 'Several ways of validating the identity of a suspicious host are as follows: ! Contact the IP Address Owner.', 'kb-doc-04-nist-sp-800-86-p77-21', 0, 19, '04-nist-sp-800-86', 'retrieved', '42A530AE6273D994249CC19C5BF84F90A0309E8335A61520447F55E5D063046D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-22', 'doc-04-nist-sp-800-86', '', 77, 'The Regional Internet Registries, such as the American Registry for Internet Numbers (ARIN),112 provide WHOIS query mechanisms on their Web sites for identifying the organization or person that ownsis responsible fora particular IP address.', 'kb-doc-04-nist-sp-800-86-p77-22', 0, 34, '04-nist-sp-800-86', 'retrieved', '4FFB743EE65CA65A67B7D5A2E593B72D10499DEBF9B4CBE962AEBF7E8B3E98E9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-23', 'doc-04-nist-sp-800-86', '', 77, 'This information can be helpful in analyzing some attacks, such as seeing that three different IP addresses generating suspicious activity are all registered to the same owner.', 'kb-doc-04-nist-sp-800-86-p77-23', 0, 27, '04-nist-sp-800-86', 'retrieved', '7FD95D3DF7663EF65FB49483DE27FF006C952759A79B6E461855523FE0500515', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-24', 'doc-04-nist-sp-800-86', '', 77, 'However, in most cases, analysts should not contact the owner directly; instead, they should provide information about the owner to the management and legal advisors of the analysts organization, who can initiate contact with the organization or give the analyst approval to do so if needed.', 'kb-doc-04-nist-sp-800-86-p77-24', 0, 46, '04-nist-sp-800-86', 'retrieved', 'F42C35425B40C5C6F8A54314028E3D35D3D84720471257FF76F23579EA55DDE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-26', 'doc-04-nist-sp-800-86', '', 77, '111 Connectionless protocols such as ICMP and UDP are the most likely to be spoofed.', 'kb-doc-04-nist-sp-800-86-p77-26', 0, 15, '04-nist-sp-800-86', 'retrieved', 'D0593D60617FB1D3FE72A336ABC8A7345882D044FE44A13071EBBF7E958F0E43', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p77-28', 'doc-04-nist-sp-800-86', '', 77, 'The other registries are the Asia Pacific Network Information Centre (APNIC), located at http://www.apnic.net/; Latin American and Caribbean IP Address Regional Registry (LACNIC), located at http://lacnic.net/; and Réseaux IP Européens Network Coordination Centre (RIPE NCC), located at http://www.ripe.net/.', 'kb-doc-04-nist-sp-800-86-p77-28', 0, 38, '04-nist-sp-800-86', 'retrieved', '1614B95436FF5B9C0E306D3576B73F6CEB43C2E7CF368433C11375E4A287DAED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-1', 'doc-04-nist-sp-800-86', '', 78, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE is primarily related to concerns about sharing information with external organizations; also, the owner of an IP address could be the person attacking the organization.', 'kb-doc-04-nist-sp-800-86-p78-1', 0, 33, '04-nist-sp-800-86', 'retrieved', '73DC32B2E1DF1DF1127890466F743054C986F19B93FA2323FAD8810FC978EADA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-3', 'doc-04-nist-sp-800-86', '', 78, 'Organizations should not send network traffic to an apparent attacking IP address to validate its identity.', 'kb-doc-04-nist-sp-800-86-p78-3', 0, 16, '04-nist-sp-800-86', 'retrieved', '8DF67887D6BE49E3BE35FE5C4A6FF0D8CFC75143F7E035F50F19BF26187A6E50', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-4', 'doc-04-nist-sp-800-86', '', 78, 'Any response that is generated cannot conclusively confirm the identity of the attacking host.', 'kb-doc-04-nist-sp-800-86-p78-4', 0, 14, '04-nist-sp-800-86', 'retrieved', 'F8143F8711E5171CE192D64A9B6E8B8ACCDA8771B86E9B201B668AC0906BDEB1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-5', 'doc-04-nist-sp-800-86', '', 78, 'Moreover, if the IP address is for the attackers system, the attacker might see the traffic and react by destroying evidence or attacking the host sending the traffic.', 'kb-doc-04-nist-sp-800-86-p78-5', 0, 28, '04-nist-sp-800-86', 'retrieved', '400D83D406E79146C8157DC2524163C6FBCAE96BE221FFAC21CB67F419EBCD8C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-6', 'doc-04-nist-sp-800-86', '', 78, 'If the IP address is spoofed, sending unsolicited network traffic to the system could be interpreted as unauthorized use or an attack.', 'kb-doc-04-nist-sp-800-86-p78-6', 0, 22, '04-nist-sp-800-86', 'retrieved', 'AE827DDA42A013D624964DCFAD9A20F44A566031AEA24CA7E7BE4E2B18A6B4AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-7', 'doc-04-nist-sp-800-86', '', 78, 'Under no circumstances should individuals attempt to gain access to others systems without permission.', 'kb-doc-04-nist-sp-800-86-p78-7', 0, 14, '04-nist-sp-800-86', 'retrieved', 'A4415183E62F404C4881AD324CCD174D292689C16D1D744248AFA3D86D2E648C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
