INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-9', 'doc-04-nist-sp-800-86', '', 78, 'As mentioned in Section 6.3.1, ISPs generally require a court order before providing any information to an organization about suspicious network activity.', 'kb-doc-04-nist-sp-800-86-p78-9', 0, 22, '04-nist-sp-800-86', 'retrieved', 'A78CCB2DDB1D7407F666929F4785D922196EC909D72841F8D28099476DBCAC2E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
