VALUES ('doc-04-nist-sp-800-86-p78-10', 'doc-04-nist-sp-800-86', '', 78, 'Accordingly, ISP assistance is generally an option during only the most serious network-based attacks.', 'kb-doc-04-nist-sp-800-86-p78-10', 0, 14, '04-nist-sp-800-86', 'retrieved', '0E10040661E529A8FDEF5AEFBE7D41004B9B31EC7C505A3CD4147BAD8C96B646', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
