VALUES ('doc-04-nist-sp-800-86-p78-11', 'doc-04-nist-sp-800-86', '', 78, 'This assistance is particularly useful in relation to attacks that involve IP address spoofing.', 'kb-doc-04-nist-sp-800-86-p78-11', 0, 14, '04-nist-sp-800-86', 'retrieved', '81176EB3C901D72644A487E80EE49DB32B1375E647184471812A01D9A21B1218', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
