VALUES ('doc-04-nist-sp-800-86-p78-12', 'doc-04-nist-sp-800-86', '', 78, 'ISPs have the ability to trace ongoing attacks back to their source, whether the IP addresses are spoofed or not.', 'kb-doc-04-nist-sp-800-86-p78-12', 0, 20, '04-nist-sp-800-86', 'retrieved', '9939D767ECE30216C4B696B5D9581357EFF382EC2F64EB058616A8BD7486BA4E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
