VALUES ('doc-04-nist-sp-800-86-p78-14', 'doc-04-nist-sp-800-86', '', 78, 'Analysts can look for previous suspicious activity associated with the same IP address or IP address block.', 'kb-doc-04-nist-sp-800-86-p78-14', 0, 17, '04-nist-sp-800-86', 'retrieved', 'C346BC988B1DAFF5FD2E7362DEC8DCC2E95649317ED5A0551537A6190636225A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
