VALUES ('doc-04-nist-sp-800-86-p78-15', 'doc-04-nist-sp-800-86', '', 78, 'The organizations own network traffic data archives and incident tracking databases might show previous activity.', 'kb-doc-04-nist-sp-800-86-p78-15', 0, 15, '04-nist-sp-800-86', 'retrieved', '65A0D9065235F8D7D471A40C625F4E5C22E0F096E0D075F3C60E378592870B30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
