VALUES ('doc-04-nist-sp-800-86-p78-16', 'doc-04-nist-sp-800-86', '', 78, 'Possible external sources include Internet search engines and online incident databases that allow searches by IP address.113 ! Look for Clues in Application Content.', 'kb-doc-04-nist-sp-800-86-p78-16', 0, 24, '04-nist-sp-800-86', 'retrieved', '547A39E02FDCBFD9557C41F2C6E173BCE8D39D74AF5E80DE6693CCB906895251', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
