VALUES ('doc-04-nist-sp-800-86-p78-17', 'doc-04-nist-sp-800-86', '', 78, 'Application data packets related to an attack might contain clues to the attackers identity.', 'kb-doc-04-nist-sp-800-86-p78-17', 0, 14, '04-nist-sp-800-86', 'retrieved', 'CDE799DDC39A40B5B1918B404A530F11C69899E6AFF0D45C92705D9621A7F80A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
