VALUES ('doc-04-nist-sp-800-86-p78-18', 'doc-04-nist-sp-800-86', '', 78, 'In addition to IP addresses, valuable information could include an e-mail address or an Internet relay chat (IRC) nickname.', 'kb-doc-04-nist-sp-800-86-p78-18', 0, 19, '04-nist-sp-800-86', 'retrieved', '6F06A23E8F142ED033BAD50CC9DABDA2DF50D6BB17D4695E43EA00768C5CEFF0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
