VALUES ('doc-04-nist-sp-800-86-p78-19', 'doc-04-nist-sp-800-86', '', 78, 'In most cases, organizations do not need to positively identify the IP address used for an attack.', 'kb-doc-04-nist-sp-800-86-p78-19', 0, 17, '04-nist-sp-800-86', 'retrieved', '17A40635449B9B149DA1D46F0187463EAE97207555B8B99DDC96F35274364187', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
