INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-20', 'doc-04-nist-sp-800-86', '', 78, '6.5 Re commendations Key recommendations presented in this section for using data from network traffic are as follows: ! Organizations should have policies regarding privacy and sensitive information.', 'kb-doc-04-nist-sp-800-86-p78-20', 0, 28, '04-nist-sp-800-86', 'retrieved', '54A7BD7CBC67FCE5C3173735422CCEEF3AB2F4E37C67F7DEFA26E4FCB5C94C05', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-21', 'doc-04-nist-sp-800-86', '', 78, 'The use of forensic tools and techniques might inadvertently disclose sensitive information to analysts and others involved in forensic activities.', 'kb-doc-04-nist-sp-800-86-p78-21', 0, 20, '04-nist-sp-800-86', 'retrieved', '3424AB32B8C558756DEFD54E4C466BFFAACB07894342AF27D1CA46716D8E8B08', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
