INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p78-22', 'doc-04-nist-sp-800-86', '', 78, 'Also, long-term storage of sensitive information inadvertently captured by forensic tools might violate data retention policies.', 'kb-doc-04-nist-sp-800-86-p78-22', 0, 16, '04-nist-sp-800-86', 'retrieved', '7E5465D043D68D34CBCDC8F4944CEB201ACD0CCAAE420343B3AF18404336FF85', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
