VALUES ('doc-04-nist-sp-800-86-p78-23', 'doc-04-nist-sp-800-86', '', 78, 'Policies should also address the monitoring of networks, as well as requiring warning banners on systems that indicate activity may be monitored.', 'kb-doc-04-nist-sp-800-86-p78-23', 0, 22, '04-nist-sp-800-86', 'retrieved', '246992AD55A45E053568856469161DC6104B63DA8CA3F9423EBD4A9F431B83AA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
