VALUES ('doc-04-nist-sp-800-86-p78-25', 'doc-04-nist-sp-800-86', '', 78, 'Organizations should estimate typical and peak log usage, determine how many hours or days worth of data should be retained based on the organizations policies, and ensure that systems and applications have sufficient storage available.', 'kb-doc-04-nist-sp-800-86-p78-25', 0, 35, '04-nist-sp-800-86', 'retrieved', '38D67EA1FA8C73C328226E72CCAE1C108A5ACA827B3E797B77C2FCA6E088EB21', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
