VALUES ('doc-04-nist-sp-800-86-p78-26', 'doc-04-nist-sp-800-86', '', 78, 'Logs related to computer security incidents might need to be kept for a substantially longer period of time than other logs.', 'kb-doc-04-nist-sp-800-86-p78-26', 0, 21, '04-nist-sp-800-86', 'retrieved', 'F578FFA8A095C620E3FB047F24A7EA96EBC739BE866D9514E5508B44C5F8AF94', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
