INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p79-2', 'doc-04-nist-sp-800-86', '', 79, 'Because current tools have rather limited analysis abilities, analysts should be well-trained, experienced, and knowledgeable in networking principles, common network and application protocols, network and application security products, and network-based threats and attack methods.', 'kb-doc-04-nist-sp-800-86-p79-2', 0, 34, '04-nist-sp-800-86', 'retrieved', 'D4EF248745C11C5CCE4E582D3AB5C8B804A212A815ADEB22B61ECC44617A735E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
