VALUES ('doc-04-nist-sp-800-86-p79-4', 'doc-04-nist-sp-800-86', '', 79, 'Analysts should have more confidence in original data sources than in data sources that receive normalized data from other sources.', 'kb-doc-04-nist-sp-800-86-p79-4', 0, 20, '04-nist-sp-800-86', 'retrieved', 'AAC27CFF9446B7D07154FCB26C59543212D00A6BA3C5D1980E52EC3F29149739', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
