VALUES ('doc-04-nist-sp-800-86-p79-5', 'doc-04-nist-sp-800-86', '', 79, 'The analysts should validate any unusual or unexpected data that is based on interpretation of data, such as IDS and SEM alerts.', 'kb-doc-04-nist-sp-800-86-p79-5', 0, 22, '04-nist-sp-800-86', 'retrieved', 'C72994F09D819E55F6CF110BD06A5BC82B9C85687FC25ED16BD0019CA2CAAB8F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
