VALUES ('doc-04-nist-sp-800-86-p79-7', 'doc-04-nist-sp-800-86', '', 79, 'Determining the identity of an attacker and other similar actions are typically time-intensive and difficult to accomplish, and do not aid the organization in correcting operational issues or security weaknesses.', 'kb-doc-04-nist-sp-800-86-p79-7', 0, 30, '04-nist-sp-800-86', 'retrieved', '7A96C4E171E9BD8BFB284016BFE84D09C41C623CA1DB2290F5EC115F2F75463C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p79-8', 'doc-04-nist-sp-800-86', '', 79, 'Establishing the identity and intent of an attacker may be important, especially if a criminal investigation will ensue, but should be weighed against other important goals, such as stopping an attack and recovering systems and data.', 'kb-doc-04-nist-sp-800-86-p79-8', 0, 36, '04-nist-sp-800-86', 'retrieved', 'DDBB2630ECB12477894C704F429C20BD952846159304B11D1D6F13511567B1AB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-1', 'doc-04-nist-sp-800-86', '', 81, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 7. Using Data from Applications Applications such as e-mail, Web browsers, and word processors are what make computers valuable to users.', 'kb-doc-04-nist-sp-800-86-p81-1', 0, 29, '04-nist-sp-800-86', 'retrieved', '16409067B9FAAC306BE8B65698794DBCED6E50D13EE4C3C50140E64C93ADD842', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-2', 'doc-04-nist-sp-800-86', '', 81, 'OSs, files, and networks are all needed to support applications: OSs to run the applications, networks to send application data between systems, and files to store application data, configuration settings, and logs.', 'kb-doc-04-nist-sp-800-86-p81-2', 0, 32, '04-nist-sp-800-86', 'retrieved', 'CBDD5D1964FD332AD03F1BB7C413274E3F0DB19BD7414C8B7932C22F85994BDE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-3', 'doc-04-nist-sp-800-86', '', 81, 'From a forensic perspective, applications bring together files, OSs, and networks.', 'kb-doc-04-nist-sp-800-86-p81-3', 0, 11, '04-nist-sp-800-86', 'retrieved', 'E61997BDA2FBC8E13286A4884933DDE52646314E1CE81AA7A5A3E1D4D5C937C5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-4', 'doc-04-nist-sp-800-86', '', 81, 'This section describes application architecturesthe components that typically make up applications and provides insights into the types of applications that are most often the focus of forensics.', 'kb-doc-04-nist-sp-800-86-p81-4', 0, 27, '04-nist-sp-800-86', 'retrieved', '33B39104A87317025F1CBE718A34E8A27F6FF9B25D8D17B3AEAB8FBA330768AB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-5', 'doc-04-nist-sp-800-86', '', 81, 'The section also provides guidance on collecting, examining, and analyzing application data.', 'kb-doc-04-nist-sp-800-86-p81-5', 0, 12, '04-nist-sp-800-86', 'retrieved', '02506A547C996DCD5024FCC1A92A38EFD082A2A2ECCB4C2BD035B3F70A4870B7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-6', 'doc-04-nist-sp-800-86', '', 81, '7.1 A pplication Components All applications contain code in the form of executable files (and related files, such as shared code libraries) or scripts.', 'kb-doc-04-nist-sp-800-86-p81-6', 0, 24, '04-nist-sp-800-86', 'retrieved', '6A0ADA10B0B2A5ABC82FCDB0128DC2907FADD5E89DB16DF34B113E0F94034878', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-7', 'doc-04-nist-sp-800-86', '', 81, 'In addition to code, many applications have one or more of the following components: configuration settings, authentication, logs, data, and supporting files.', 'kb-doc-04-nist-sp-800-86-p81-7', 0, 22, '04-nist-sp-800-86', 'retrieved', '197BA9C0CB98762EAB2431E75938AE0CB5FFB02F1C41BB1FF9B900DBCE88462E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-8', 'doc-04-nist-sp-800-86', '', 81, 'Sections 7.1.1 through 7.1.5 describe these components in detail, and Section 7.1.6 discusses the major types of application architectures, which relate to the intended distribution of the major components.', 'kb-doc-04-nist-sp-800-86-p81-8', 0, 29, '04-nist-sp-800-86', 'retrieved', '2E46A3050CA76F1C2BA1833A0FF2C3D69C66EC534D1EFCE0FF325C6B9AE54326', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-10', 'doc-04-nist-sp-800-86', '', 81, 'Configuration Settings Most applications allow users or administrators to customize certain aspects of the applications behavior by altering configuration settings.', 'kb-doc-04-nist-sp-800-86-p81-10', 0, 20, '04-nist-sp-800-86', 'retrieved', 'A9933E5147202F9244324C2E41B38EFFC4F3C05B4E5A1F578B934F47EA621667', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-11', 'doc-04-nist-sp-800-86', '', 81, 'From a forensics perspective, many settings are trivial (e.g., specifying background colors), but others might be very important, such as the host and directory where data files and logs are stored or the default username.', 'kb-doc-04-nist-sp-800-86-p81-11', 0, 35, '04-nist-sp-800-86', 'retrieved', '9107CA1C7F8A6A09C52076B19AE985FA76AB4353A396B8CA8AC2E194519E510B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-12', 'doc-04-nist-sp-800-86', '', 81, 'Configuration settings may be temporaryset dynamically during a particular application sessionor permanent.', 'kb-doc-04-nist-sp-800-86-p81-12', 0, 12, '04-nist-sp-800-86', 'retrieved', '7E81221726A381D08D2BCBE6B76597DB5B202DE5664541B661A13B3680406F80', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-13', 'doc-04-nist-sp-800-86', '', 81, 'Many applications have some settings that apply to all users, and also support some user-specific settings.', 'kb-doc-04-nist-sp-800-86-p81-13', 0, 16, '04-nist-sp-800-86', 'retrieved', '8AC5754CF7E05B29FAA7DD4E1B46247B99DD05F7A86ED113ED18BE24FF86D39E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-14', 'doc-04-nist-sp-800-86', '', 81, 'Configuration settings may be stored in several ways, including the following: ! Configuration File.', 'kb-doc-04-nist-sp-800-86-p81-14', 0, 14, '04-nist-sp-800-86', 'retrieved', '6F0EF727B3BAE25BE22B0020EF358B38E0FB89983BCD627965B1461072FF9F35', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-15', 'doc-04-nist-sp-800-86', '', 81, 'Applications may store settings in a text file or a file with a proprietary binary format.114 Some applications require the configuration file to be on the same host as the application, whereas other applications allow configuration files to be located on other hosts.', 'kb-doc-04-nist-sp-800-86-p81-15', 0, 43, '04-nist-sp-800-86', 'retrieved', 'F7E9A1115453BADB50E173CC19BF1B46BCE8A98D577790C991A7AEADE9D91639', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-16', 'doc-04-nist-sp-800-86', '', 81, 'For example, an application might be installed on a workstation, but the configuration file for a particular user could be stored on the users home directory on a file server.', 'kb-doc-04-nist-sp-800-86-p81-16', 0, 30, '04-nist-sp-800-86', 'retrieved', 'A9CE149181948D7789CE963645083D2B7C86E6884E7461238AFC465E2B73E292', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-18', 'doc-04-nist-sp-800-86', '', 81, 'Some applications permit certain configuration settings to be specified at runtime through the use of command-line options.', 'kb-doc-04-nist-sp-800-86-p81-18', 0, 17, '04-nist-sp-800-86', 'retrieved', '01F585D81FBEDE45C7292F84B1EFE01C7EF5A89A2EC0A8024576A3148DE3303E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-19', 'doc-04-nist-sp-800-86', '', 81, 'For example, the UNIX e-mail client mutt has options for specifying the location of the mailbox to open and the location of the configuration file.', 'kb-doc-04-nist-sp-800-86-p81-19', 0, 25, '04-nist-sp-800-86', 'retrieved', '872030E84D84C74E77CF026CE03888DE7858029FF4DBADEA1613CDB075A8D8A7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-20', 'doc-04-nist-sp-800-86', '', 81, 'Identification of the options being used for an active session is OS- and application-specific; possible identification methods include reviewing the list of active OS processes, examining an OS history file, and reviewing an application log.', 'kb-doc-04-nist-sp-800-86-p81-20', 0, 35, '04-nist-sp-800-86', 'retrieved', '034887463B6488797BB27B406982728A1D0FFA7C266A87F6D0837909AE8FE031', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-21', 'doc-04-nist-sp-800-86', '', 81, 'Runtime options can also be specified in icons, startup files, batch files, and other ways.', 'kb-doc-04-nist-sp-800-86-p81-21', 0, 15, '04-nist-sp-800-86', 'retrieved', 'BA827F3CD3BE02B34238367EC19F796EA1E83E949252EC6567CF4969283893D4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-23', 'doc-04-nist-sp-800-86', '', 81, 'Some applications that make source code available (e.g., open source applications, scripts) actually place user or administrator-specified configuration settings directly into the source code.', 'kb-doc-04-nist-sp-800-86-p81-23', 0, 24, '04-nist-sp-800-86', 'retrieved', '606762A8B2ED9EAD802C40A867D46742974850BFF4588980C33EAF41A5215730', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-24', 'doc-04-nist-sp-800-86', '', 81, 'If the application is then compiled (e.g., converted from human-readable code to a binary, machine-readable format), the configuration settings may actually be contained within executable files, potentially making the settings far more difficult to access than if they were specified in configuration files or as runtime options.', 'kb-doc-04-nist-sp-800-86-p81-24', 0, 47, '04-nist-sp-800-86', 'retrieved', '3DA48ECBAB318F8EF1BE5DA68AEA200721C43DCC619A2DD5156B3308039F0C1E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-25', 'doc-04-nist-sp-800-86', '', 81, 'In some cases, the settings can be found by searching for text strings within the executable files.', 'kb-doc-04-nist-sp-800-86-p81-25', 0, 17, '04-nist-sp-800-86', 'retrieved', 'E5320642E288F62EFD22F4EFD5AEA4080676A4DD0B90C1357249988B26B8FAB2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p81-26', 'doc-04-nist-sp-800-86', '', 81, '114 For example, on Windows systems, many configuration settings are stored in the Windows registry, which is essentially a set of large configuration files.', 'kb-doc-04-nist-sp-800-86-p81-26', 0, 24, '04-nist-sp-800-86', 'retrieved', '49685B9D8E3351CAFEF30C7FADA298713E1A5728CAAE26D291CF5C74CC999AB7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
