INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-1', 'doc-04-nist-sp-800-86', '', 82, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 7.1.2 7.1.3 Authentication Some applications verify the identity of each user attempting to run the application.', 'kb-doc-04-nist-sp-800-86-p82-1', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C91508E44F3F9CC98BCFE0128AFC084BC3D73567A515F1C8ABA25A8290A79A7A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-2', 'doc-04-nist-sp-800-86', '', 82, 'Although this is usually done to prevent unauthorized access to the application, it may also be done when access is not a concern so that the application can be customized based on the users identity.', 'kb-doc-04-nist-sp-800-86-p82-2', 0, 35, '04-nist-sp-800-86', 'retrieved', '638FEE4E670CEE27492F646FB446C35D559D5F250B28B70C843DA4F29B2648DC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-4', 'doc-04-nist-sp-800-86', '', 82, 'The application may use an external authentication service, such as a directory server.', 'kb-doc-04-nist-sp-800-86-p82-4', 0, 13, '04-nist-sp-800-86', 'retrieved', '122A39AFCCF68A885A0230BFAEA51CB3FEFFFDE044E5A44E9DE6FECC9F748221', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-5', 'doc-04-nist-sp-800-86', '', 82, 'Although the application may contain some records related to authentication, the external authentication service is likely to contain more detailed authentication information.', 'kb-doc-04-nist-sp-800-86-p82-5', 0, 22, '04-nist-sp-800-86', 'retrieved', '3A19139D056C5C4B755F926CB6B7A834F8B7DBC95B04986D546BF2D521A79D40', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-7', 'doc-04-nist-sp-800-86', '', 82, 'The application may have its own authentication mechanism, such as user accounts and passwords that are part of the application, not the OS.', 'kb-doc-04-nist-sp-800-86-p82-7', 0, 23, '04-nist-sp-800-86', 'retrieved', 'A289E5CA416E81717705BFE2F101049A77CF251CA2196F5BB880C485AB8786E1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-9', 'doc-04-nist-sp-800-86', '', 82, 'Pass-through authentication refers to passing OS credentials (typically, username and password) unencrypted from the OS to the application.', 'kb-doc-04-nist-sp-800-86-p82-9', 0, 18, '04-nist-sp-800-86', 'retrieved', 'F99AC4BBA77BFB8AB37DCF65D554FBF668C421FC2763DB7045638D4A2433565C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-11', 'doc-04-nist-sp-800-86', '', 82, 'Within a controlled environment (e.g., managed workstations and servers within an organization), some applications may be able to rely on previous authentication performed by the OS.', 'kb-doc-04-nist-sp-800-86-p82-11', 0, 26, '04-nist-sp-800-86', 'retrieved', 'CCF5D7B1A5CE502660D6CEBEE9058014356EAABAF58E3C74997D4B06372CE27B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-12', 'doc-04-nist-sp-800-86', '', 82, 'For example, if all hosts using an application are part of the same Windows domain and each user has already been authenticated by the domain, then the application can extract the OS-authenticated identity from each workstations environment.', 'kb-doc-04-nist-sp-800-86-p82-12', 0, 37, '04-nist-sp-800-86', 'retrieved', '81CA977FB4B76A9F86618EC8AFB3B3C2C497D92C3618AA3D4420F49FFE5FEDDB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-13', 'doc-04-nist-sp-800-86', '', 82, 'The application can then restrict access to the application by tracking which users are permitted to have access and comparing the OS-authenticated identity to the authorized user list.', 'kb-doc-04-nist-sp-800-86-p82-13', 0, 28, '04-nist-sp-800-86', 'retrieved', '73E1EA98E93836FEB8A272BAA319E87444654D8CC799E052E9128EA9AEDD84A2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-14', 'doc-04-nist-sp-800-86', '', 82, 'This technique is effective only if users cannot alter the user identity in the workstation environment.', 'kb-doc-04-nist-sp-800-86-p82-14', 0, 16, '04-nist-sp-800-86', 'retrieved', 'E78E6154A01A2CE47C7BB25BCF94431B95F1D620E5640D68BBC03823932B52EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-17', 'doc-04-nist-sp-800-86', '', 82, 'However, analysts should be aware that there are many ways in which users can be authenticated and that, accordingly, the sources of user authentication records might vary greatly among applications and application implementations.', 'kb-doc-04-nist-sp-800-86-p82-17', 0, 33, '04-nist-sp-800-86', 'retrieved', 'DBBBC87860B1EC40D4A3A95AEDFDF25FEAF233B2592E824851E7294156CD6274', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-18', 'doc-04-nist-sp-800-86', '', 82, 'Analysts should also know that some applications use access control (typically enforced by the OS) to restrict access to certain types of information or application functions.', 'kb-doc-04-nist-sp-800-86-p82-18', 0, 26, '04-nist-sp-800-86', 'retrieved', '98B6CAE4260CEB9242ECF514EC8DFDB7A9805C617C56286A96F03031FFFC4A47', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-19', 'doc-04-nist-sp-800-86', '', 82, 'This knowledge can be helpful in determining what a particular application user could have done.', 'kb-doc-04-nist-sp-800-86-p82-19', 0, 15, '04-nist-sp-800-86', 'retrieved', '747A0B33A02F53FACD8F4C8D7A8356A3696845FCA077D5CCB3915B5B796F012B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-20', 'doc-04-nist-sp-800-86', '', 82, 'In addition, some applications record information related to access control, such as failed attempts to perform sensitive actions or access restricted data.', 'kb-doc-04-nist-sp-800-86-p82-20', 0, 22, '04-nist-sp-800-86', 'retrieved', '3BCBDC5FCDA0846A50B50DA1CD8AE3494CA615E4AB75BE0795DE2825AC1DA791', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-21', 'doc-04-nist-sp-800-86', '', 82, 'Logs Although some applications (primarily very simple ones) do not record any information to logs, most applications perform some type of logging.', 'kb-doc-04-nist-sp-800-86-p82-21', 0, 22, '04-nist-sp-800-86', 'retrieved', 'A478AF4C910073CD1FB7A35B3125B4DDABA57D7D5F298CF3A8780D72D99DD964', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-22', 'doc-04-nist-sp-800-86', '', 82, 'An application may record log entries to an OS-specific log (e.g., syslog on UNIX systems, event logs on Windows systems), a text file, a database, or a proprietary file format.', 'kb-doc-04-nist-sp-800-86-p82-22', 0, 30, '04-nist-sp-800-86', 'retrieved', 'D14114E00592A79A9F29F525F879B6DEF37D1AC13029D5F1BD7C280D0310109A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-25', 'doc-04-nist-sp-800-86', '', 82, 'Event log entries typically list actions that were performed, the date and time each action occurred, and the result of each action.', 'kb-doc-04-nist-sp-800-86-p82-25', 0, 22, '04-nist-sp-800-86', 'retrieved', '88CC2206845D6D35EB34E7601314EC039E4E8D5AED40AA4182DE0788FC4231F0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-26', 'doc-04-nist-sp-800-86', '', 82, 'Examples of actions that might be recorded are establishing a connection to another system and issuing administrator-level commands.', 'kb-doc-04-nist-sp-800-86-p82-26', 0, 18, '04-nist-sp-800-86', 'retrieved', 'BC4D392845F1E51A306946A4BC33F9DA5F6B09D5037E810E934931FED04FDAFF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p82-27', 'doc-04-nist-sp-800-86', '', 82, 'Event log entries might also include supporting information, such as what username was used to perform each action and what status code was returned (which provides more information about the result than a simple successful/failed status).', 'kb-doc-04-nist-sp-800-86-p82-27', 0, 36, '04-nist-sp-800-86', 'retrieved', '70AE01075E5B7EB583F1BDF6B6F9F944E6818509B6223B98351100F0CB9944C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-2', 'doc-04-nist-sp-800-86', '', 83, 'Audit log entries, also known as security log entries, contain information pertaining to audited activities, such as successful and failed logon attempts, security policy changes, file access, and process execution.115 Applications may use audit capabilities built into the OS or may provide their own auditing capabilities.', 'kb-doc-04-nist-sp-800-86-p83-2', 0, 46, '04-nist-sp-800-86', 'retrieved', 'C0F9FED9B49D31144A8769D7AE90772F8581280C55EB801FF9B31E85B5117069', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-4', 'doc-04-nist-sp-800-86', '', 83, 'Some applications create error logs, which record information regarding application errors, typically with timestamps.', 'kb-doc-04-nist-sp-800-86-p83-4', 0, 14, '04-nist-sp-800-86', 'retrieved', 'B5F1CBDA01CE40144A493C84EC5FF27BADC571413C98F072549AA8CCCDE65450', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-6', 'doc-04-nist-sp-800-86', '', 83, 'Error messages can be helpful in determining when an event of interest occurred and in identifying some characteristics of the event.', 'kb-doc-04-nist-sp-800-86-p83-6', 0, 21, '04-nist-sp-800-86', 'retrieved', 'AEBDBE663DD55573669C649DB4D88D7AD6445C1789D7D31990415916D304FE30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-8', 'doc-04-nist-sp-800-86', '', 83, 'An application may create a separate installation log file that records information pertinent to the initial installation and subsequent updates of that application.', 'kb-doc-04-nist-sp-800-86-p83-8', 0, 23, '04-nist-sp-800-86', 'retrieved', 'E84116C7A727851499FD1CAA9391746560AD74C93E741519C8D6891DA37EE9C5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-9', 'doc-04-nist-sp-800-86', '', 83, 'Information recorded in an installation log varies widely but is likely to include the status of various phases of the installation.', 'kb-doc-04-nist-sp-800-86-p83-9', 0, 21, '04-nist-sp-800-86', 'retrieved', '2D26CC9384DBC46CD6ED5AF3AF6E0D2B19FFC18FCBA8209D46491188BE621DAF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-10', 'doc-04-nist-sp-800-86', '', 83, 'The log may also indicate the source of the installation files, the locations where the application components were placed, and options involving the applications configuration.', 'kb-doc-04-nist-sp-800-86-p83-10', 0, 25, '04-nist-sp-800-86', 'retrieved', 'E10F2A1D58E1D595F2B4E22A8B6F7F00BF35373AB2480D94A279C572881BE41D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
