INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-12', 'doc-04-nist-sp-800-86', '', 83, 'Some applications can be run in a debugging mode, which means that they log far more information than usual regarding the operation of the application.', 'kb-doc-04-nist-sp-800-86-p83-12', 0, 25, '04-nist-sp-800-86', 'retrieved', '9092CF6EE8C01B86618DEFA0891B9FC2CF3528BE92CC93E477C400572AE00931', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-13', 'doc-04-nist-sp-800-86', '', 83, 'Debugging records are often very cryptic and may have meaning only to the softwares creator, who can decipher error codes and other facets of the records.', 'kb-doc-04-nist-sp-800-86-p83-13', 0, 26, '04-nist-sp-800-86', 'retrieved', '2EC01FD7AEB92E5C837EC0FEAA3050F01E8834AF8EA11176D50B6257F31BE8BE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-14', 'doc-04-nist-sp-800-86', '', 83, 'If an application offers a debugging capability, typically it is enabled only if administrators or developers need to resolve a specific operational problem.', 'kb-doc-04-nist-sp-800-86-p83-14', 0, 23, '04-nist-sp-800-86', 'retrieved', '593FB6205C92BF171E5CD578EB9B081E00B469F60E2CC8D5B0BA5F81C755BE1E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
