INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-16', 'doc-04-nist-sp-800-86', '', 83, 'Data Nearly every application is specifically designed to handle data in one or more ways, such as creating, displaying, transmitting, receiving, modifying, deleting, protecting, and storing data.', 'kb-doc-04-nist-sp-800-86-p83-16', 0, 27, '04-nist-sp-800-86', 'retrieved', 'DE6EC88E607D039E30F966158C1697BC0C8FE82FBA5F5AB38FB8FD80CED9849B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-17', 'doc-04-nist-sp-800-86', '', 83, 'For example, an e- mail client allows a user to create an e-mail message and to send it to someone, as well as to receive, view, and delete an e-mail message from someone else.', 'kb-doc-04-nist-sp-800-86-p83-17', 0, 34, '04-nist-sp-800-86', 'retrieved', '5B5CCC58516F265896AF1CFCF7D21FF324818CF3C3871C9C3AAA9FCFE706A484', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-18', 'doc-04-nist-sp-800-86', '', 83, 'Application data often resides temporarily in memory, and temporarily or permanently in files.', 'kb-doc-04-nist-sp-800-86-p83-18', 0, 13, '04-nist-sp-800-86', 'retrieved', 'E11E8FC4F7A2AC9AB772AD08660F33B722CDB7FD5CD20EB84E2D464485AA45DA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
