INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-19', 'doc-04-nist-sp-800-86', '', 83, 'The format of a file containing application data may be generic (e.g., text files, bitmap graphics) or proprietary.', 'kb-doc-04-nist-sp-800-86-p83-19', 0, 18, '04-nist-sp-800-86', 'retrieved', '82315ACA0D76A99E5F1051F4E1D2A74890546AFAD369F137932C9E1D58101C6D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
