INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-20', 'doc-04-nist-sp-800-86', '', 83, 'Data may also be stored in databases, which are highly structured collections of files and data specifications.', 'kb-doc-04-nist-sp-800-86-p83-20', 0, 17, '04-nist-sp-800-86', 'retrieved', '3511A3D3FA8D9392CA4F48282D3B7D866B268896820C08F4088F19997D4E8626', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
