INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-21', 'doc-04-nist-sp-800-86', '', 83, 'Some applications create temporary files during a session, which may contain application data.', 'kb-doc-04-nist-sp-800-86-p83-21', 0, 13, '04-nist-sp-800-86', 'retrieved', '352711322979FBBF937A7EB8B37DF0BAB051B26E9CAED2E71D08BFFA9EF57486', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
