INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-22', 'doc-04-nist-sp-800-86', '', 83, 'If an application fails to shut down gracefully, it may leave temporary files on media.', 'kb-doc-04-nist-sp-800-86-p83-22', 0, 15, '04-nist-sp-800-86', 'retrieved', '1BB9CD0D48A649C52FD6C1D5FE23620C1942614F6A466AD8CD1AB90B53F2AC3D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
