INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-23', 'doc-04-nist-sp-800-86', '', 83, 'Most OSs have a directory designated for temporary files; however, some applications have their own temporary directory, and other applications place temporary files in the same directory where data is stored.', 'kb-doc-04-nist-sp-800-86-p83-23', 0, 31, '04-nist-sp-800-86', 'retrieved', '199E569E0939BAD042E4CFC8E035B4017660B69C7E7673F90318C635837F6127', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-24', 'doc-04-nist-sp-800-86', '', 83, 'Applications may also contain data file templates and sample data files (e.g., databases, documents).', 'kb-doc-04-nist-sp-800-86-p83-24', 0, 14, '04-nist-sp-800-86', 'retrieved', '9EB15FF004B419B9DE1FDEFD26956F518AAA340126084E6FA31086B8F6FC5239', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
