INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-25', 'doc-04-nist-sp-800-86', '', 83, 'Supporting Files Applications often include one or more types of supporting files, such as documentation and graphics.', 'kb-doc-04-nist-sp-800-86-p83-25', 0, 17, '04-nist-sp-800-86', 'retrieved', 'DFFE829AC285C112C2A712AE53EA88064615AD45FB5A3A9AD34072A8DFEA6E44', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-26', 'doc-04-nist-sp-800-86', '', 83, 'Supporting files tend to be static, but that does not mean that they are not of value for forensics.', 'kb-doc-04-nist-sp-800-86-p83-26', 0, 19, '04-nist-sp-800-86', 'retrieved', '2E625F7EA910201CEF4AA30252DDE0B7BF237E3C7C77DF2D6CBA7305D70FE6FF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
