VALUES ('doc-04-nist-sp-800-86-p83-28', 'doc-04-nist-sp-800-86', '', 83, 'This may include administrator and user manuals, help files, and licensing information.', 'kb-doc-04-nist-sp-800-86-p83-28', 0, 12, '04-nist-sp-800-86', 'retrieved', '65AFBB4683963AF7A3CED6486B397C2225D929EDD2BE085B33AE4E28B401D806', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-29', 'doc-04-nist-sp-800-86', '', 83, 'Documentation can be helpful to analysts in many ways, such as explaining what the application does, how the application works, and what components the application has.', 'kb-doc-04-nist-sp-800-86-p83-29', 0, 26, '04-nist-sp-800-86', 'retrieved', '7034CF58E7334C36B1ABF8AAF2CE665C4E5B6F8E5722C7388737341D6B67B1D9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p83-30', 'doc-04-nist-sp-800-86', '', 83, 'Documentation also typically contains contact information for the vendor of the application; the vendor might be able to answer questions and provide other assistance in understanding the application.', 'kb-doc-04-nist-sp-800-86-p83-30', 0, 28, '04-nist-sp-800-86', 'retrieved', '067B816E84474AFD89B1EAA9BAB8CB7928046474909D6CBE8F95A320E12E26A5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-2', 'doc-04-nist-sp-800-86', '', 84, 'Also known as shortcuts, links are simply pointers to something else, such as an executable.', 'kb-doc-04-nist-sp-800-86-p84-2', 0, 15, '04-nist-sp-800-86', 'retrieved', 'F741948599E93BD269AE9CA5E8FC0CCB4F99BE7C0A51F6DC512842DB10758DE3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-3', 'doc-04-nist-sp-800-86', '', 84, 'Links are most frequently used on Windows systems; for example, the items listed on the Start menu are really links to programs.', 'kb-doc-04-nist-sp-800-86-p84-3', 0, 22, '04-nist-sp-800-86', 'retrieved', 'CC50A4600E04B409BA2BE414C3EA923DF9C0F045432620AEBE5EA2B8B58CF92C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-4', 'doc-04-nist-sp-800-86', '', 84, 'By examining the properties of a link, an analyst can determine what program the link runs, where the program is, and what options (if any) are set.', 'kb-doc-04-nist-sp-800-86-p84-4', 0, 27, '04-nist-sp-800-86', 'retrieved', '3A0B517C54585299F328130F1155E3E7B066F48495F9923F88779A13B845A52D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-6', 'doc-04-nist-sp-800-86', '', 84, 'These files may include standalone graphics used by the application, as well as graphics for icons.', 'kb-doc-04-nist-sp-800-86-p84-6', 0, 16, '04-nist-sp-800-86', 'retrieved', '9540FA79118CC3EDD5E7C389C3C86A438EF8BE3AC0319B2E6C05A8B956C09992', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-7', 'doc-04-nist-sp-800-86', '', 84, 'Although application graphics are typically of little interest to an analyst, icon graphics may be of interest for identifying which executable was running.', 'kb-doc-04-nist-sp-800-86-p84-7', 0, 23, '04-nist-sp-800-86', 'retrieved', '95C5788A151A544061CDD09902D343467CC879D00C40CAA8DAAF9530589F8571', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
