INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-8', 'doc-04-nist-sp-800-86', '', 84, '7.1.6 Application Architecture Every application has an architecture, which refers to the logical separation of its components and the communication mechanisms used between components.', 'kb-doc-04-nist-sp-800-86-p84-8', 0, 24, '04-nist-sp-800-86', 'retrieved', '31C9650A63674C3E1408793A753923490B4AE79BBDA0608385065D2ED586F9D2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
