INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-9', 'doc-04-nist-sp-800-86', '', 84, 'Most applications are designed to follow one of three major application architecture categories, as follows: ! Local.', 'kb-doc-04-nist-sp-800-86-p84-9', 0, 17, '04-nist-sp-800-86', 'retrieved', '1220F0DE5000DA34BBE24477738A5436FB2FA9E6103654759A8F55C1D4C64198', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
