INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-11', 'doc-04-nist-sp-800-86', '', 84, 'The code, configuration settings, logs, and supporting files are located on the users system.', 'kb-doc-04-nist-sp-800-86-p84-11', 0, 14, '04-nist-sp-800-86', 'retrieved', 'A1F34C18ABF834DF5972C34B17DB756E47786CA3D50AAF67F4E67E4D7DB29028', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-13', 'doc-04-nist-sp-800-86', '', 84, 'Application data may be contained on the users system or another system (e.g., file server) and usually cannot be modified simultaneously by multiple users.', 'kb-doc-04-nist-sp-800-86-p84-13', 0, 24, '04-nist-sp-800-86', 'retrieved', '42A4BBB92BBD2E37D96064F16585F43438D8DFB65F0BBBC50AA0D87C1647B931', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-14', 'doc-04-nist-sp-800-86', '', 84, 'Examples of local applications are text editors, graphics editors, and office productivity suites (e.g., word processor, spreadsheet).', 'kb-doc-04-nist-sp-800-86-p84-14', 0, 17, '04-nist-sp-800-86', 'retrieved', '38516FD1F2EA1BC32BEB94A8FA03525F7961DEF3E927D54EBBC66D1221A73D7F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-17', 'doc-04-nist-sp-800-86', '', 84, 'A two-tiered client/server application stores its code, configuration settings, and supporting files on each users workstation, and its data on one or more central servers accessed by all users.', 'kb-doc-04-nist-sp-800-86-p84-17', 0, 29, '04-nist-sp-800-86', 'retrieved', '33705B394E0C445218D060690433596C94972A7F382C64B3B9EC80A75BADC075', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-19', 'doc-04-nist-sp-800-86', '', 84, 'A three-tiered client/server application separates the user interface from the rest of the application, and also separates the data from the other components.', 'kb-doc-04-nist-sp-800-86-p84-19', 0, 23, '04-nist-sp-800-86', 'retrieved', '7B16331326C8F1D1695CC4EB6FE47DF5E4442E5ECC04A35BDC3A0CDF1E6D5AEF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-20', 'doc-04-nist-sp-800-86', '', 84, 'The classic three-tier model places the user interface code on the client workstation (along with some supporting files), the rest of the application code on an application server, and the data on a database server.', 'kb-doc-04-nist-sp-800-86-p84-20', 0, 35, '04-nist-sp-800-86', 'retrieved', 'C7B24B7D4C961680CB57649D0452C4CBA54160BA36A14E88CE827F08DA58B0DC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-21', 'doc-04-nist-sp-800-86', '', 84, 'Many Web-based applications use four-tier models: Web browser, Web server, application server, and database server.', 'kb-doc-04-nist-sp-800-86-p84-21', 0, 15, '04-nist-sp-800-86', 'retrieved', '1086EC0B2AD11D0C23875EBF9660B325C2A09DC63BB76D1243D667892B404CE3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-22', 'doc-04-nist-sp-800-86', '', 84, 'Each tier interacts only with the adjacent tiers, so in three and four-tier models, the client does not interact directly with the database server.', 'kb-doc-04-nist-sp-800-86-p84-22', 0, 24, '04-nist-sp-800-86', 'retrieved', 'F3B834EF23E9210EE8DC02093A3BC1DF648F582EB4C3016A9D9E0EAE8E87C990', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-23', 'doc-04-nist-sp-800-86', '', 84, 'Examples of typical client/server applications are medical records systems, e-commerce applications, and inventory systems.', 'kb-doc-04-nist-sp-800-86-p84-23', 0, 14, '04-nist-sp-800-86', 'retrieved', '69D82ED67755E5E739ABD6D0CD8648BA13921BE21A9C0D9FDF13B3090F6E0042', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-25', 'doc-04-nist-sp-800-86', '', 84, 'A peer-to-peer application is designed so that individual client hosts directly communicate and share data with each other.', 'kb-doc-04-nist-sp-800-86-p84-25', 0, 18, '04-nist-sp-800-86', 'retrieved', '4E8CCFE0C6EF2DF469EF72D87DB6DB61BCF8658E9B5BCEE8276ADD9E18AC58B7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-26', 'doc-04-nist-sp-800-86', '', 84, 'Typically, the clients first communicate with a centralized server that provides information about other clients; this information is then used to establish direct connections that do not need to go through the centralized server.', 'kb-doc-04-nist-sp-800-86-p84-26', 0, 34, '04-nist-sp-800-86', 'retrieved', 'CDFFFC9FC98C8C0A37C45BF14A742A81950D209AC666A2CD5137CF5206347150', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-27', 'doc-04-nist-sp-800-86', '', 84, 'Examples of peer-to-peer applications are certain file sharing, chat, and IM programs.', 'kb-doc-04-nist-sp-800-86-p84-27', 0, 12, '04-nist-sp-800-86', 'retrieved', '551F9B3DD999AD0C6B6BA320DAB55C5B16CBA7D94EF4CBE3F561AE06189FF86F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-28', 'doc-04-nist-sp-800-86', '', 84, 'However, some programs of these types, while popularly referred to as peer-to-peer, are actually client/server, because the clients communicate with a centralized server, instead of communicating directly with each other.', 'kb-doc-04-nist-sp-800-86-p84-28', 0, 30, '04-nist-sp-800-86', 'retrieved', '02036E3C800C5F48098460CF2C3D921C58FBA40306FD60951474EF20C7C2087F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-30', 'doc-04-nist-sp-800-86', '', 84, 'For example, many client/server applications can have multiple tiers installed on a single system.', 'kb-doc-04-nist-sp-800-86-p84-30', 0, 14, '04-nist-sp-800-86', 'retrieved', '91F2A94CAC14E40BABBC0792180DD7B5745439A52FE6EF2B7A187450E89EEC74', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-31', 'doc-04-nist-sp-800-86', '', 84, 'Especially during application demonstrations or testing, all tiers might be installed on one system.', 'kb-doc-04-nist-sp-800-86-p84-31', 0, 14, '04-nist-sp-800-86', 'retrieved', '45BA4EF4B550589047A0DA1FE051753429C4C948F84BE8C098CC267B374744B9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
