INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-32', 'doc-04-nist-sp-800-86', '', 84, 'On the other hand, some local applications can be split among systems, with some components on local systems and some on remote systems.', 'kb-doc-04-nist-sp-800-86-p84-32', 0, 23, '04-nist-sp-800-86', 'retrieved', '5E561567CEFC584DE6D7E68A3D04629231F2130B6BC4EB9315F005233D2BF1EC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p84-33', 'doc-04-nist-sp-800-86', '', 84, 'Applications often make it easy to specify where different components should be installed and where data and configuration files should be stored.', 'kb-doc-04-nist-sp-800-86-p84-33', 0, 22, '04-nist-sp-800-86', 'retrieved', 'CCB8E77D6F4FEAAAD34D1923404D7B1D46378E4506A464355D34703392B5EE98', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-1', 'doc-04-nist-sp-800-86', '', 85, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Applications that are designed to split their code among multiple hosts typically use application protocols for communications between hosts.116 Ubiquitous types of applications, such as e-mail and Web, use well-known, standardized application protocols to facilitate interoperability among different components.', 'kb-doc-04-nist-sp-800-86-p85-1', 0, 47, '04-nist-sp-800-86', 'retrieved', '8FCADF8D0F1BCC43793CE5DE21745BB2DBE8EF75DB7DDFBB36A8406FC1803ECE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-2', 'doc-04-nist-sp-800-86', '', 85, 'For example, nearly every e-mail client program is compatible with nearly every e-mail server program because they are based on the same application protocol standards.', 'kb-doc-04-nist-sp-800-86-p85-2', 0, 25, '04-nist-sp-800-86', 'retrieved', 'CA6732E5F225FF02EEC0C6CC887214A9F5EF5387CBD0335316AD4CA491EE2B49', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-3', 'doc-04-nist-sp-800-86', '', 85, 'However, a program based on a standard might add proprietary features or violate the standard in some way, especially if the standard is not exhaustively detailed.', 'kb-doc-04-nist-sp-800-86-p85-3', 0, 26, '04-nist-sp-800-86', 'retrieved', 'BB90F75CCED2B765714405A86D4B2BCD904DA3EDF12A97CD7397B3D6F1E5B898', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-4', 'doc-04-nist-sp-800-86', '', 85, 'If interoperability with other applications is not a concern (or not desirable) and the same party is creating all application components, non-standard protocols are often used.', 'kb-doc-04-nist-sp-800-86-p85-4', 0, 26, '04-nist-sp-800-86', 'retrieved', '2B14FAB1A9A5CF82F7E9E83FD88440D7E8C75E7B0A3028BC72504A26A96ADFC5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-5', 'doc-04-nist-sp-800-86', '', 85, 'As described throughout Section 7.1, applications may have many different components that operate together.', 'kb-doc-04-nist-sp-800-86-p85-5', 0, 14, '04-nist-sp-800-86', 'retrieved', 'BB81E8DBB1999EB40158DBBE7681FBC5C75C62CDAEA6A9B10DAFAD2609B842C8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-8', 'doc-04-nist-sp-800-86', '', 85, 'Many applications also rely on OS services, such as printing and DNS lookups (to find the IP addresses of application servers and other devices).', 'kb-doc-04-nist-sp-800-86-p85-8', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C332A7B071BA66361E44AA6A17E956C63EF0E87C37C2F08E150D5C7BD64E5DE8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-9', 'doc-04-nist-sp-800-86', '', 85, 'Applications vary widely in complexity, from a simple utility program such as a calculator to a large e-commerce application that may involve many thousands of components and have millions of users.', 'kb-doc-04-nist-sp-800-86-p85-9', 0, 31, '04-nist-sp-800-86', 'retrieved', '5AEFFDBFB21E685904D933CE10AAD12647F5D93FAD9FEB59297079CCED70A9A6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-10', 'doc-04-nist-sp-800-86', '', 85, '7.2 Types of Applications Applications exist for nearly every purpose imaginable.', 'kb-doc-04-nist-sp-800-86-p85-10', 0, 11, '04-nist-sp-800-86', 'retrieved', '4E41C8BF7084A77C68ADDB619BD70FC03B65180E60A69FAC295C5BE7AC3C2A34', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-11', 'doc-04-nist-sp-800-86', '', 85, 'Although forensic techniques can be applied to any application, certain types of applications are more likely to be the focus of forensic analysis, including e-mail, Web usage, interactive messaging, file sharing, document usage, security applications, and data concealment tools.', 'kb-doc-04-nist-sp-800-86-p85-11', 0, 39, '04-nist-sp-800-86', 'retrieved', 'A331E8489115C36304EDEFD5225838CE523C4F22DC49358F53F181112FB0BF52', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
