VALUES ('doc-04-nist-sp-800-86-p85-12', 'doc-04-nist-sp-800-86', '', 85, 'Nearly every computer has at least a few applications installed from these categories.', 'kb-doc-04-nist-sp-800-86-p85-12', 0, 13, '04-nist-sp-800-86', 'retrieved', '2EF461C7911E47E95D4489F1CFDEDDAD2451D6E6144C610422469AF806CDC88A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
