VALUES ('doc-04-nist-sp-800-86-p85-15', 'doc-04-nist-sp-800-86', '', 85, 'E-mail E-mail has become the predominant means for people to communicate electronically.', 'kb-doc-04-nist-sp-800-86-p85-15', 0, 12, '04-nist-sp-800-86', 'retrieved', '1F520BAA003723202CDBC1C3AB45441C2F5011E92D8219EFA20DF4D62F6498F2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
