VALUES ('doc-04-nist-sp-800-86-p85-17', 'doc-04-nist-sp-800-86', '', 85, 'The body of the e-mail contains the actual content of the message, such as a memorandum or a personal letter.', 'kb-doc-04-nist-sp-800-86-p85-17', 0, 20, '04-nist-sp-800-86', 'retrieved', '2CEC8FC48E8E94DE0044B015B06AB43C98BD803CBAAE87786DC11082662CDE81', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
