VALUES ('doc-04-nist-sp-800-86-p85-18', 'doc-04-nist-sp-800-86', '', 85, 'The header of the e-mail includes various pieces of information regarding the e-mail.', 'kb-doc-04-nist-sp-800-86-p85-18', 0, 13, '04-nist-sp-800-86', 'retrieved', 'DA618BF7D2AABE78038A6EE48725BB13086650413DCA22DAF7F574D95058C853', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
