INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-19', 'doc-04-nist-sp-800-86', '', 85, 'By default, most e-mail client applications display only a few header fields for each message: the senders and recipients e-mail addresses, the date and time the message was sent, and the subject of the message.', 'kb-doc-04-nist-sp-800-86-p85-19', 0, 35, '04-nist-sp-800-86', 'retrieved', '1617B988A48F8F0BDAC5223DFD0B85BE142360343A762ADE983DAB68EAC49422', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-20', 'doc-04-nist-sp-800-86', '', 85, 'However, the header typically includes several other fields, including the following:117 ! Message ID ! Type of e-mail client used to create the message ! Importance of the message, as indicated by the sender (e.g., low, normal, high) ! Routing informationwhich e-mail servers the message passed through in transit and when each server received it ! Message content type, which indicates whether the e-mail content simply consists of a text body or also has file attachments, embedded graphics, etc.', 'kb-doc-04-nist-sp-800-86-p85-20', 0, 79, '04-nist-sp-800-86', 'retrieved', 'B398EAE5162E4543B42BBCE5F76F61841888B609FB8BFE9D8C65A4DC1D637538', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-21', 'doc-04-nist-sp-800-86', '', 85, 'E-mail client applications are used to receive, store, read, compose, and send e-mails.', 'kb-doc-04-nist-sp-800-86-p85-21', 0, 13, '04-nist-sp-800-86', 'retrieved', '7271BE8921FEA3FA6770C81D8AC753FBB9A332911612F129ACC59C8324E1B072', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
