INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p85-22', 'doc-04-nist-sp-800-86', '', 85, 'Most e-mail clients also provide an address book that can hold contact information, such as e-mail addresses, names, and', 'kb-doc-04-nist-sp-800-86-p85-22', 0, 19, '04-nist-sp-800-86', 'retrieved', '657063F4264F18143B87410FA374C7623231BA7D65E5ADD34BCC0D148B7A41CA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
