VALUES ('doc-04-nist-sp-800-86-p85-23', 'doc-04-nist-sp-800-86', '', 85, '116 Applications that are designed to keep all code on a single host typically do not need to use any application protocols.', 'kb-doc-04-nist-sp-800-86-p85-23', 0, 22, '04-nist-sp-800-86', 'retrieved', '8B9754E16FF9C72D53DD3769EDB5B9148CF2AF856F75E459096D5AC296259AD6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
