VALUES ('doc-04-nist-sp-800-86-p85-24', 'doc-04-nist-sp-800-86', '', 85, '117 Most e-mail clients have a configuration setting that specifies whether full or partial e-mail headers should be displayed.', 'kb-doc-04-nist-sp-800-86-p85-24', 0, 19, '04-nist-sp-800-86', 'retrieved', '76A921E7173860B84CD368C0A2513DBC6B94E73B3E53BA81F7CB02CC8EEF1B12', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
