VALUES ('doc-04-nist-sp-800-86-p86-2', 'doc-04-nist-sp-800-86', '', 86, 'Encryption programs are sometimes used in conjunction with e-mail clients to encrypt an e-mails body and/or attachments.', 'kb-doc-04-nist-sp-800-86-p86-2', 0, 17, '04-nist-sp-800-86', 'retrieved', 'FF1E3AC2F47658F28A3E1AEB5248B68D0C894D9A9A09426DDFCCD4140B51770C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
