INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-3', 'doc-04-nist-sp-800-86', '', 86, 'When a user sends an e-mail, it is transferred from the e-mail client to the server using SMTP.', 'kb-doc-04-nist-sp-800-86-p86-3', 0, 18, '04-nist-sp-800-86', 'retrieved', 'EE1E070A283F85B11F87328BECD458151AB1BD7A551768AA9283A08A99FE0D0B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-4', 'doc-04-nist-sp-800-86', '', 86, 'If the sender and recipient of the e-mail use different e-mail servers, the e-mail is then routed using SMTP through additional e-mail servers until it reaches the recipients server.', 'kb-doc-04-nist-sp-800-86-p86-4', 0, 29, '04-nist-sp-800-86', 'retrieved', 'F543BB76EDA83B6AA705D82B378AAD743835F922EF31195838C9B0E57785C066', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-5', 'doc-04-nist-sp-800-86', '', 86, 'Typically, the recipient uses an e- mail client on a separate system to retrieve the e-mail using Post Office Protocol 3 (POP3) or Internet Message Access Protocol (IMAP); in some cases, the e-mail client may be on the destination server (e.g., a multi-user UNIX system).', 'kb-doc-04-nist-sp-800-86-p86-5', 0, 45, '04-nist-sp-800-86', 'retrieved', '54C52C69F2B394A6ECAD85065A2286717FD418A009C898BDE3008CF5123F5D7C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-6', 'doc-04-nist-sp-800-86', '', 86, 'The destination server often performs checks on the e-mails before making them available for retrieval, such as blocking messages with inappropriate content (e.g., spam, virus).', 'kb-doc-04-nist-sp-800-86-p86-6', 0, 25, '04-nist-sp-800-86', 'retrieved', '209395B1D3C3CC8B51D3443C076EB2DC176BA865C1E7B10E54E1747FE1B940F0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-7', 'doc-04-nist-sp-800-86', '', 86, 'From end to end, information regarding a single e-mail message may be recorded in several placesthe senders system, each e-mail server that handles the message, and the recipients system, as well as antivirus, spam, and content filtering servers.118 7.2.2', 'kb-doc-04-nist-sp-800-86-p86-7', 0, 39, '04-nist-sp-800-86', 'retrieved', '59C6FBB9CBE2C34247F165C95B145590425E3BF2E87D0F74A577BD21F33551D7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-8', 'doc-04-nist-sp-800-86', '', 86, 'Web Usage Through Web browsers, people access Web servers that contain nearly every type of data imaginable.', 'kb-doc-04-nist-sp-800-86-p86-8', 0, 17, '04-nist-sp-800-86', 'retrieved', '202ED422D8193A9A2DE4CCE6644C2FC2D013A42B9099C4B72790BA3031A5599B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
