INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-9', 'doc-04-nist-sp-800-86', '', 86, 'Many applications also offer Web-based interfaces, which are also accessed through Web browsers.', 'kb-doc-04-nist-sp-800-86-p86-9', 0, 13, '04-nist-sp-800-86', 'retrieved', '3A353F99A86960A5423B853766298DFB2E8A25A4255FBCD2831BE11B3243F3A5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
