INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-10', 'doc-04-nist-sp-800-86', '', 86, 'Because they can be used for so many purposes, Web browsers are one of the most commonly used applications.', 'kb-doc-04-nist-sp-800-86-p86-10', 0, 19, '04-nist-sp-800-86', 'retrieved', 'F5B4E687C67189CDEA1DD4B1E36B0FC8AEAC9144F0EC73480D17506DFF89BE76', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-11', 'doc-04-nist-sp-800-86', '', 86, 'The basic standard for Web communications is HTTP; however, HTTP can contain many types of data in a variety of standard and proprietary formats.', 'kb-doc-04-nist-sp-800-86-p86-11', 0, 24, '04-nist-sp-800-86', 'retrieved', '862374107B36A41A436565F59D2517DB1C62449EC35562C947823935B7DBF3D0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-12', 'doc-04-nist-sp-800-86', '', 86, 'HTTP is essentially the mechanism for transferring data between the Web browsers and the Web servers.119 Typically, the richest sources of information regarding Web usage are the hosts running the Web browsers.', 'kb-doc-04-nist-sp-800-86-p86-12', 0, 32, '04-nist-sp-800-86', 'retrieved', '1A80BC74FCA7105BF66283E4D70C9ECD391179CD9D3769628484861F8D811BCA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-13', 'doc-04-nist-sp-800-86', '', 86, 'Information that may be retrieved from Web browsers include a list of favorite Web sites, a history (with timestamps) of Web sites visited, cached Web data files, and cookies (including their creation and expiration dates).', 'kb-doc-04-nist-sp-800-86-p86-13', 0, 35, '04-nist-sp-800-86', 'retrieved', '0957CBBADA55A04EC086965AAFEC5698C6F9539A04C5EDAF01D80B6067AC46F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-14', 'doc-04-nist-sp-800-86', '', 86, 'Another good source of Web usage information is Web servers, which typically keep logs of the requests they receive.', 'kb-doc-04-nist-sp-800-86-p86-14', 0, 19, '04-nist-sp-800-86', 'retrieved', 'AC711D52BC9271D6D2FC16B3F24C7190F5F742DDFB262DB918449C76978FD2F5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-15', 'doc-04-nist-sp-800-86', '', 86, 'Data that is often logged by Web servers for each request includes a timestamp; the IP address, Web browser version, and OS of the host making the request; the type of request (e.g., read data, write data); the resource requested; and the status code.', 'kb-doc-04-nist-sp-800-86-p86-15', 0, 44, '04-nist-sp-800-86', 'retrieved', '87539E67E67A374198E5CDC7EEE9CFAB972C2E1323C914AFE9D5F447C760FC8C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
