INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-16', 'doc-04-nist-sp-800-86', '', 86, 'The response to each request includes a three-digit status code that indicates the success or failure of the request.', 'kb-doc-04-nist-sp-800-86-p86-16', 0, 19, '04-nist-sp-800-86', 'retrieved', 'BBF3C630BD7B773C4B975DE9F9926A0AC1C554B17ED605D5C66EFCE2A738DBD6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-17', 'doc-04-nist-sp-800-86', '', 86, 'For successful requests, the status code explains what action was performed; for failures, the status code explains why the request failed.', 'kb-doc-04-nist-sp-800-86-p86-17', 0, 21, '04-nist-sp-800-86', 'retrieved', 'A77DB578C390D4F3415EDE036929B70B13C8F5A4F19D9D5313E2C343A895BEA2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
