INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-18', 'doc-04-nist-sp-800-86', '', 86, 'Several other types of devices and software, in addition to Web browsers and servers, might also log related information.', 'kb-doc-04-nist-sp-800-86-p86-18', 0, 19, '04-nist-sp-800-86', 'retrieved', '7C7208747030A1052BDA768F3126E2D5293AC6B8FAB84D26707D60AEB347A0CD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-19', 'doc-04-nist-sp-800-86', '', 86, 'For example, Web proxy servers and application proxying firewalls might perform detailed logging of HTTP activity, with a level of detail similar to that of Web server logs.120 Routers, non-proxying firewalls, and other network devices might log the basic aspects of HTTP network connections, such as source and destination IP addresses and ports.', 'kb-doc-04-nist-sp-800-86-p86-19', 0, 53, '04-nist-sp-800-86', 'retrieved', '6AC4E28DC06AEC214404956B5D452DD3A0D311B47E0FB35457E19FFF3D8EB8F4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-20', 'doc-04-nist-sp-800-86', '', 86, 'Organizations that use Web content monitoring and filtering services might find useful data in the services logs, particularly regarding denied Web requests.', 'kb-doc-04-nist-sp-800-86-p86-20', 0, 22, '04-nist-sp-800-86', 'retrieved', '79C668C260395B3B7B46F9306FA178DB28D8A3F64EB7BBC821ABF651A4CB0E95', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-21', 'doc-04-nist-sp-800-86', '', 86, '118 For more information on e-mail services, see NIST SP 800-45, Guidelines on Electronic Mail Security, available for download from http://csrc.nist.gov/publications/nistpubs/index.html.', 'kb-doc-04-nist-sp-800-86-p86-21', 0, 21, '04-nist-sp-800-86', 'retrieved', '9CB7E57336B17B377F92FB933E83652464A0A11BE27942AA8DA5F7CE3EA2D0C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-22', 'doc-04-nist-sp-800-86', '', 86, '119 For a detailed description of the current HTTP standard, see RFC 2616, Hypertext Transfer ProtocolHTTP/1.1, available at http://www.ietf.org/rfc/rfc2616.txt.', 'kb-doc-04-nist-sp-800-86-p86-22', 0, 19, '04-nist-sp-800-86', 'retrieved', '8A343E2BBE7AA167B229D30662FC5CC3E47EB3387F33B6D3E3C3E47A0A3718E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-23', 'doc-04-nist-sp-800-86', '', 86, 'Also, see NIST SP 800-44, Guidelines on Securing Public Web Servers, for additional information on Web services; it is available for download from http://csrc.nist.gov/publications/nistpubs/index.html.', 'kb-doc-04-nist-sp-800-86-p86-23', 0, 24, '04-nist-sp-800-86', 'retrieved', 'ECD320E6DC3AF73AA9FC2D4ACD7B213906F555AE5B9F33774C70FA86E37B6F34', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p86-24', 'doc-04-nist-sp-800-86', '', 86, '120 Typically, proxies cannot log the details of SSL or TLS-protected HTTP requests, because the requests and the corresponding responses pass through the proxy encrypted, which conceals their contents.', 'kb-doc-04-nist-sp-800-86-p86-24', 0, 29, '04-nist-sp-800-86', 'retrieved', 'AAEBBA357A818E1F45202912E266F964B472A7CE66D0F5A9E5980CDC06CF22F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-2', 'doc-04-nist-sp-800-86', '', 87, 'Interactive Communications Unlike e-mail messages, which typically take minutes to go from sender to recipient, interactive communications services provide real-time (or near-real-time) communications.', 'kb-doc-04-nist-sp-800-86-p87-2', 0, 23, '04-nist-sp-800-86', 'retrieved', '7D35715B5324FB37C673B7FB1E549EAFC551C628E341504EAB38310A7E11E5ED', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-3', 'doc-04-nist-sp-800-86', '', 87, 'Types of applications commonly used for interactive communications include the following: ! Group Chat.', 'kb-doc-04-nist-sp-800-86-p87-3', 0, 14, '04-nist-sp-800-86', 'retrieved', '8EFBE99BFC36475FFD722CACF3C25129A40B36AFA42792B6C8447AA53A40D9D2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-4', 'doc-04-nist-sp-800-86', '', 87, 'Group chat applications provide virtual meeting spaces where many users can share messages at once.', 'kb-doc-04-nist-sp-800-86-p87-4', 0, 15, '04-nist-sp-800-86', 'retrieved', '75FD6717FD7A5D08291FD4A5A8FD47267C7022F76C2CDDE574CC5349CEC26BFC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-6', 'doc-04-nist-sp-800-86', '', 87, 'The most popular group chat protocol, Internet Relay Chat (IRC), is a standard protocol that uses relatively simple text-based communications.121 IRC also provides a mechanism for users to send and receive files.', 'kb-doc-04-nist-sp-800-86-p87-6', 0, 32, '04-nist-sp-800-86', 'retrieved', '19B5003379E13D9B8C5F25CDA1EBD085CBF94B8F62E9B439E0B0716980488EB2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-8', 'doc-04-nist-sp-800-86', '', 87, 'IM applications are either peer-to-peer, allowing users to send text messages and files directly to each other, or client/server, passing messages and files through a centralized server.', 'kb-doc-04-nist-sp-800-86-p87-8', 0, 27, '04-nist-sp-800-86', 'retrieved', '8611E5CBB022EEF83F91AB7AAE5AB702A0F88E0D174789213A06B210057352F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-9', 'doc-04-nist-sp-800-86', '', 87, 'IM application configuration settings may contain user information, lists of users that the user has communicated with, file transfer information, and archived messages or chat sessions.', 'kb-doc-04-nist-sp-800-86-p87-9', 0, 26, '04-nist-sp-800-86', 'retrieved', '899CB20AEDF12A04EE4E3DD172297D0C6E364FC771C3977ED212D6DE444B0667', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-10', 'doc-04-nist-sp-800-86', '', 87, 'There are several major Internet-based IM services, each of which uses its own proprietary communications protocols.', 'kb-doc-04-nist-sp-800-86-p87-10', 0, 16, '04-nist-sp-800-86', 'retrieved', 'FCB9B36F70D6209EC6F4E3E3191BE4C5D7A6DFB71546C370474237124DB4A545', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-11', 'doc-04-nist-sp-800-86', '', 87, 'Several companies also offer enterprise IM products that are run within an organization.', 'kb-doc-04-nist-sp-800-86-p87-11', 0, 13, '04-nist-sp-800-86', 'retrieved', '8E2FCAAFF0EE9C0ABF94DD8C0039AA4D0BA367C27438B0EAC5A54C3CE14280BD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-12', 'doc-04-nist-sp-800-86', '', 87, 'Such products are often integrated to some extent with the organizations e-mail services and can be used only by authenticated e-mail users.', 'kb-doc-04-nist-sp-800-86-p87-12', 0, 22, '04-nist-sp-800-86', 'retrieved', '74594DBEA700862B2DF88BFB0BD23345B656250CC30CF9DE5EFAACDE6A5BF495', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-14', 'doc-04-nist-sp-800-86', '', 87, 'As the capacity of networks continues to increase, conducting real-time video and audio communications across computer networks also becomes more common.', 'kb-doc-04-nist-sp-800-86-p87-14', 0, 21, '04-nist-sp-800-86', 'retrieved', '551A852CD2E6E3CEAB493239ACC1D3A87048E58AFE0BD407E9897673E48853F0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-15', 'doc-04-nist-sp-800-86', '', 87, 'Technologies such as Voice over IP (VoIP) permit people to conduct telephone conversations over networks such as the Internet.122 Some audio implementations provide computer-based service from end to end, whereas others are only partially computer-based, with an intermediate server converting the communications between computer networks and standard phone networks.', 'kb-doc-04-nist-sp-800-86-p87-15', 0, 49, '04-nist-sp-800-86', 'retrieved', 'A78D5DD6B0C894C70857D21CEE30AC9A6E19E77EB90EB865AA556D6D11BA873F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-17', 'doc-04-nist-sp-800-86', '', 87, 'Video technologies can be used to hold teleconferences or to have video phone communications between two individuals.', 'kb-doc-04-nist-sp-800-86-p87-17', 0, 17, '04-nist-sp-800-86', 'retrieved', '869BE292E76CFC317608F916C924F5860EF5240C0C9C7726324DC98F04429E6B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-18', 'doc-04-nist-sp-800-86', '', 87, 'Commonly used protocols for audio and video communications include H.323 and Session Initiation Protocol (SIP).123 File Sharing Users can share files through many different programs.', 'kb-doc-04-nist-sp-800-86-p87-18', 0, 25, '04-nist-sp-800-86', 'retrieved', 'A66118CE0010FCF85C1AC29AE3F405DAA71B63B591A6ABE2E6AEB0FC68A124C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-19', 'doc-04-nist-sp-800-86', '', 87, 'As described previously in this section, e-mail, group chat programs, and IM software all offer the ability to send and receive particular files.', 'kb-doc-04-nist-sp-800-86-p87-19', 0, 23, '04-nist-sp-800-86', 'retrieved', '3CACD635BB917925E87117C2B2A623F4D92FB4880FB4514270FF0654E99D51E1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-20', 'doc-04-nist-sp-800-86', '', 87, 'However, these programs generally do not allow a recipient to browse through files and to choose the files to transfer.', 'kb-doc-04-nist-sp-800-86-p87-20', 0, 20, '04-nist-sp-800-86', 'retrieved', '45C5DD178046068C268497635B95B69AF3762209262DD2FD79BE00B877F199B3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p87-21', 'doc-04-nist-sp-800-86', '', 87, 'Full-fledged file sharing programs and protocols are needed for this level of functionality.', 'kb-doc-04-nist-sp-800-86-p87-21', 0, 13, '04-nist-sp-800-86', 'retrieved', '68B914BDCB746C2D9142988DAEA9B88DFB149FE007B484F2C8D9F5041385E493', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
