VALUES ('doc-04-nist-sp-800-86-p87-23', 'doc-04-nist-sp-800-86', '', 87, 'Traditional file sharing services use client/server architectures, with a central file server containing a repository of files.', 'kb-doc-04-nist-sp-800-86-p87-23', 0, 17, '04-nist-sp-800-86', 'retrieved', '9BA9735AB19F1D9AC418120C0B65069F791CBA866F263400E2B2DF4CE2F2649C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
