VALUES ('doc-04-nist-sp-800-86-p87-24', 'doc-04-nist-sp-800-86', '', 87, 'Clients can use the server by initiating connections to it, authenticating to it (if required), reviewing the list of available files (if needed), then transferring files to or from the server.', 'kb-doc-04-nist-sp-800-86-p87-24', 0, 31, '04-nist-sp-800-86', 'retrieved', '3C6A2A951C8684DB1E607C0E2A134D40580EACC3A6B65D098E006AD593FBFE87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
