VALUES ('doc-04-nist-sp-800-86-p87-25', 'doc-04-nist-sp-800-86', '', 87, 'Some commonly used client/server file sharing services are FTP, Network File Sharing (NFS), Apple Filing Protocol (AFP), and Server Message Block (SMB).124', 'kb-doc-04-nist-sp-800-86-p87-25', 0, 22, '04-nist-sp-800-86', 'retrieved', 'B87E1D6004454D1FBE9BF7B93831C35A12E4DE9ED4C2CDF18591887293758F12', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
