VALUES ('doc-04-nist-sp-800-86-p87-27', 'doc-04-nist-sp-800-86', '', 87, 'RFCs 2810 through 2813 contain additional information that supplements RFC 1459.', 'kb-doc-04-nist-sp-800-86-p87-27', 0, 11, '04-nist-sp-800-86', 'retrieved', '860C82CC7AD199EF2E35E412EE29890EDB442FFD781856E43E076C94CB3D41C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
