VALUES ('doc-04-nist-sp-800-86-p88-1', 'doc-04-nist-sp-800-86', '', 88, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE These are standardized protocols that do not protect the confidentiality of the data in transit, including any supplied authentication credentials, such as passwords.', 'kb-doc-04-nist-sp-800-86-p88-1', 0, 31, '04-nist-sp-800-86', 'retrieved', '6CFF23CEF4FCEA8F6085B0818C5DD016FE75241BD72E72D2EE3AAFD1EF7837FB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
