INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-2', 'doc-04-nist-sp-800-86', '', 88, 'Secure alternatives, such as Secure FTP (SFTP) and Secure Copy (scp), encrypt their network communications.', 'kb-doc-04-nist-sp-800-86-p88-2', 0, 15, '04-nist-sp-800-86', 'retrieved', 'E9EFA29C8AB40F8149699D6E7CA12A8FA85398FB18353EA41D9D5D10A5A9D6E8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
