INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-3', 'doc-04-nist-sp-800-86', '', 88, 'Most OSs have built-in file sharing clients (e.g., FTP, SMB), but users can also install various third-party programs that provide similar functionality.', 'kb-doc-04-nist-sp-800-86-p88-3', 0, 22, '04-nist-sp-800-86', 'retrieved', '4CB42B866C0B270F2A3F6CDBB2B0D79C39915CC38F8F03337BABA40E960B0494', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
