INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-5', 'doc-04-nist-sp-800-86', '', 88, 'Most peer-to-peer file sharing services are primarily used to trade music, graphics, or software across the Internet.', 'kb-doc-04-nist-sp-800-86-p88-5', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A498E93E95A0569EA3592A77EE1879B45B94C8E0129D2242A747E0D1D4DE3E1E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-6', 'doc-04-nist-sp-800-86', '', 88, 'Unlike client/server file sharing, in which a single server holds the file repository, peer-to-peer file sharing is distributed, with files located on many different hosts.', 'kb-doc-04-nist-sp-800-86-p88-6', 0, 25, '04-nist-sp-800-86', 'retrieved', '7D62DB4A6D74BECB1A379A54D957144934D67FFA31A350B8BFA6847897A8E29E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-7', 'doc-04-nist-sp-800-86', '', 88, 'Peer-to-peer file sharing services typically have a central server that gives clients information on where other clients are located, but the server does not participate in the transmission of files or file information.', 'kb-doc-04-nist-sp-800-86-p88-7', 0, 33, '04-nist-sp-800-86', 'retrieved', 'AFDB3FB53B3F2FF62EADB5821EADEBE9A7C5F9E876ED99FE1C6746DC371D8359', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-10', 'doc-04-nist-sp-800-86', '', 88, 'Users typically can choose from several client programs when using a particular service.', 'kb-doc-04-nist-sp-800-86-p88-10', 0, 13, '04-nist-sp-800-86', 'retrieved', '5F1448001D486CD41B3A235327C7891AB3FB1BE93F9F9BECCB5AF23E5EE32AA4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-11', 'doc-04-nist-sp-800-86', '', 88, 'Although most services allow each user to control which files are shared on their system, services known as encrypted peer-to-peer work by storing others files on an encrypted portion of each users hard drive, and giving users no control over or knowledge of what is stored in that area of their own systems.', 'kb-doc-04-nist-sp-800-86-p88-11', 0, 53, '04-nist-sp-800-86', 'retrieved', '90ADB21564440829A6A12347B0CE86B74507F17C702984D522E9FD17A869B3DB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-12', 'doc-04-nist-sp-800-86', '', 88, 'Anonymous peer-to-peer services send requested files through multiple intermediate hosts instead of simply sending them from source to destination, with the goal of making it very difficult to identify the true source or destination of any given file.', 'kb-doc-04-nist-sp-800-86-p88-12', 0, 38, '04-nist-sp-800-86', 'retrieved', 'CAA6EC753ECA763F74E57257B3DCEA8643BA6D225E5877B259A8418BCAB2832C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-14', 'doc-04-nist-sp-800-86', '', 88, 'Document Usage Many users spend much of their time working with documents, such as letters, reports, and charts.', 'kb-doc-04-nist-sp-800-86-p88-14', 0, 18, '04-nist-sp-800-86', 'retrieved', 'F690AD5F545B79C9F2FFC0D9ADBBB539D5CE31CDBB6B58896950E0851519C23A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
