VALUES ('doc-04-nist-sp-800-86-p88-15', 'doc-04-nist-sp-800-86', '', 88, 'Documents may contain any type of data, so they are often of interest to analysts.', 'kb-doc-04-nist-sp-800-86-p88-15', 0, 15, '04-nist-sp-800-86', 'retrieved', 'BFAA0F09629D9AEF6C3C3BE56A2C8D7994BC6FD0D22AB736AC4D99069E65B6AE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
