VALUES ('doc-04-nist-sp-800-86-p88-16', 'doc-04-nist-sp-800-86', '', 88, 'The class of software used for creating, viewing, and editing such documents is known as office productivity applications.', 'kb-doc-04-nist-sp-800-86-p88-16', 0, 18, '04-nist-sp-800-86', 'retrieved', '8D4C166D8F9C57FE4112CF91BDCE75D456430B78F2AEAEA6E57D065D51CA2052', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
