VALUES ('doc-04-nist-sp-800-86-p88-17', 'doc-04-nist-sp-800-86', '', 88, 'This includes word processor, spreadsheet, presentation, and personal database software.', 'kb-doc-04-nist-sp-800-86-p88-17', 0, 10, '04-nist-sp-800-86', 'retrieved', 'ED3188A9357BA59FA5B446122345FAC0341D05BF6524237C1C863AF814E7AD42', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
