INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-18', 'doc-04-nist-sp-800-86', '', 88, 'Documents often have user or system information embedded in them, such as the name or username of the person who created or most recently edited the document, or the license number of the software or the MAC address of the system used to create the document.125 Security Applications Hosts often run one or more security applications that attempt to protect the host from misuse and abuse occurring through commonly used applications, such as e-mail clients and Web browsers.', 'kb-doc-04-nist-sp-800-86-p88-18', 0, 78, '04-nist-sp-800-86', 'retrieved', 'D5C763B263CBD6DEF44903A61DAA576CE21A41BEF2633D32EEAF2C2B6E5F134D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-19', 'doc-04-nist-sp-800-86', '', 88, 'Some commonly used security applications are antivirus software, spyware detection and removal utilities, content filtering (e.g., anti-spam measures), and host-based intrusion detection software.', 'kb-doc-04-nist-sp-800-86-p88-19', 0, 23, '04-nist-sp-800-86', 'retrieved', '7531A10ED5CF6E7DC9ED5F2B43EE1F7D0618E02CA6A028E754E9B0A07DF041EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p88-20', 'doc-04-nist-sp-800-86', '', 88, 'The logs of security applications may contain detailed records of suspicious activity and may also indicate whether a security compromise occurred or was prevented.', 'kb-doc-04-nist-sp-800-86-p88-20', 0, 24, '04-nist-sp-800-86', 'retrieved', 'B1017C7F2FA006B5C640B4136307B6DFF6D9AE2869DF7C81D0AA5DF133C36387', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
