VALUES ('doc-04-nist-sp-800-86-p88-21', 'doc-04-nist-sp-800-86', '', 88, 'If the security application is part of an enterprise deployment, such as centrally managed and controlled antivirus software, logs may be available both on individual hosts and on a centralized application log.', 'kb-doc-04-nist-sp-800-86-p88-21', 0, 32, '04-nist-sp-800-86', 'retrieved', '46E4161F38D093867762C7D17C20928C7AE3400ECFE772D0622F7CD7B11705F9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
