VALUES ('doc-04-nist-sp-800-86-p88-23', 'doc-04-nist-sp-800-86', '', 88, 'This might be done for benign purposes, such as protecting the confidentiality and integrity of data against access by unauthorized parties, or for malicious purposes, such as concealing evidence of improper activities.', 'kb-doc-04-nist-sp-800-86-p88-23', 0, 32, '04-nist-sp-800-86', 'retrieved', 'CFA3F1472A07A789FA36FFAEF7CA72D183F1D530DF890DB4FDCC50C6FDAD411D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
