VALUES ('doc-04-nist-sp-800-86-p88-24', 'doc-04-nist-sp-800-86', '', 88, 'Examples of data concealment tools include file encryption utilities, steganographic tools, and system cleanup tools.', 'kb-doc-04-nist-sp-800-86-p88-24', 0, 15, '04-nist-sp-800-86', 'retrieved', 'C7569873DB7AAA7E2EA99DFA3DAA2419FC80677A8FA9D395FCECDC6B7924E167', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
