VALUES ('doc-04-nist-sp-800-86-p89-1', 'doc-04-nist-sp-800-86', '', 89, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE special-purpose software that removes data pertaining to particular applications, such as Web browsers, as well as data in general locations, such as temporary directories.', 'kb-doc-04-nist-sp-800-86-p89-1', 0, 32, '04-nist-sp-800-86', 'retrieved', '2FC9A48D82E81677B5E64951F34DAB2E92DD6A0732BB86007ACA51668236E0B3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
