VALUES ('doc-04-nist-sp-800-86-p89-3', 'doc-04-nist-sp-800-86', '', 89, 'Analysts should be aware of the capabilities of these tools so that they can identify such tools on a system and recognize the tools effects.', 'kb-doc-04-nist-sp-800-86-p89-3', 0, 25, '04-nist-sp-800-86', 'retrieved', '9FF191E4E23E8A5C0BCA30EA507F99A0829B9E96B8841590F3FB15F494540C44', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
