VALUES ('doc-04-nist-sp-800-86-p89-4', 'doc-04-nist-sp-800-86', '', 89, '7.3 C ollecting Application Data As described in Section 7.1, application-related data may be located within filesystems, volatile OS data, and network traffic.', 'kb-doc-04-nist-sp-800-86-p89-4', 0, 23, '04-nist-sp-800-86', 'retrieved', 'DFFD2753F4499CF6032C6F38FD3651BC5E9F3DC53512E33DF59D81AD037AFFA1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
