VALUES ('doc-04-nist-sp-800-86-p89-5', 'doc-04-nist-sp-800-86', '', 89, 'Sections 4.2, 5.2, and 6.3 contain specific information about collecting data from these respective sources.', 'kb-doc-04-nist-sp-800-86-p89-5', 0, 15, '04-nist-sp-800-86', 'retrieved', '206AAB0D7E5FE5B808186108609BB51867CFA847592EDFCBD1FB5867B378E75A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
