VALUES ('doc-04-nist-sp-800-86-p89-6', 'doc-04-nist-sp-800-86', '', 89, 'The types of application data that these sources may contain are as follows: ! Filesystems.', 'kb-doc-04-nist-sp-800-86-p89-6', 0, 15, '04-nist-sp-800-86', 'retrieved', '92070C942B58819F37142EA84CFA276C186940DF744D8B36D1ED621CABF2D4B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
