INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-7', 'doc-04-nist-sp-800-86', '', 89, 'Filesystems may contain many types of files related to applications, including executable files and scripts, configuration files, supporting files (e.g., documentation), logs, and data files.', 'kb-doc-04-nist-sp-800-86-p89-7', 0, 25, '04-nist-sp-800-86', 'retrieved', '8007EAF63ACCC180052229AD3AE60D182E2ED3883B69A869B52F488FB7354B65', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-9', 'doc-04-nist-sp-800-86', '', 89, 'Volatile OS data may contain information about network connections used by applications, the application processes running on a system and the command line arguments used for each process, and the files held open by applications, as well as other types of supporting information.', 'kb-doc-04-nist-sp-800-86-p89-9', 0, 43, '04-nist-sp-800-86', 'retrieved', '26B036556E03DEF609525AE671DFF1642C22761FD70879D0769C16A6EA080F92', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-11', 'doc-04-nist-sp-800-86', '', 89, 'The most relevant network traffic data involves user connections to a remote application and communications between application components on different systems.', 'kb-doc-04-nist-sp-800-86-p89-11', 0, 21, '04-nist-sp-800-86', 'retrieved', 'D00E424299BE3D15D3EDF3D3754F1E34EC887FD33662546A28588E72C1C0DE88', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-12', 'doc-04-nist-sp-800-86', '', 89, 'Other network traffic records might also provide supporting information, such as network connections for remote printing from an application, and DNS lookups by the application client or other components to resolve application components domain names to IP addresses.', 'kb-doc-04-nist-sp-800-86-p89-12', 0, 38, '04-nist-sp-800-86', 'retrieved', 'C179EBAD6E89BB715E65478B3DFBA7672455096C01859817672527934F684EDA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-13', 'doc-04-nist-sp-800-86', '', 89, 'Analysts often face a major challenge in determining which data should be collected.', 'kb-doc-04-nist-sp-800-86-p89-13', 0, 13, '04-nist-sp-800-86', 'retrieved', '59820E97325649C202C17023915E84E37217D64060928FFB74A14E6A89EC4E33', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-15', 'doc-04-nist-sp-800-86', '', 89, 'For example, it is common to have multiple Web browsers and e-mail clients installed on a single system.', 'kb-doc-04-nist-sp-800-86-p89-15', 0, 18, '04-nist-sp-800-86', 'retrieved', '2059E79EA6030849ACD6F0A0F3F558CC19A9A8503BA399477C5EED97EA561D33', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-16', 'doc-04-nist-sp-800-86', '', 89, 'If analysts are asked to collect data regarding an individuals use of the organizations e-mail services, they need to be mindful of all the ways in which the individual could have accessed those services.', 'kb-doc-04-nist-sp-800-86-p89-16', 0, 34, '04-nist-sp-800-86', 'retrieved', '70B2494A544A7FFD0F443A11FA61A9F2A3E501714877250033188861FF4C469B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-17', 'doc-04-nist-sp-800-86', '', 89, 'The users computer could contain three different e-mail clients, plus two Web browsers that could be used to access a Web-based e-mail client provided by the organization.', 'kb-doc-04-nist-sp-800-86-p89-17', 0, 27, '04-nist-sp-800-86', 'retrieved', 'CAC263406127B3995D98633E1F02CCBF7155138D37E60EC4C77FB37DE5D8932A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-18', 'doc-04-nist-sp-800-86', '', 89, 'For the users computer, analysts could simply collect all data from the computer and then determine during the examination process which clients were actually used for e-mail.', 'kb-doc-04-nist-sp-800-86-p89-18', 0, 27, '04-nist-sp-800-86', 'retrieved', 'B97DF6FE8CF483EB0BF7BED8DCCA2542139D477CD6D27F4F3A4E3B7BDB41375E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-19', 'doc-04-nist-sp-800-86', '', 89, 'However, there are many potential data sources aside from the users computer, and these sources might vary based on the client that was used.', 'kb-doc-04-nist-sp-800-86-p89-19', 0, 24, '04-nist-sp-800-86', 'retrieved', '07E556AC610F264028EAB4A73F81C2953E3F67A7E2561AA52693DFC4E6DF1FD0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-20', 'doc-04-nist-sp-800-86', '', 89, 'For example, use of the Web-based client might have been recorded in Web server, firewall, IDS, and content monitoring software logs, as well as in Web browser history files, Web browser caches, cookies, and personal firewall logs.', 'kb-doc-04-nist-sp-800-86-p89-20', 0, 37, '04-nist-sp-800-86', 'retrieved', '94A834FC0E0B14619307A1A1C9FD0CA682A0D48937605EE07CC97C75CA298C9D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-21', 'doc-04-nist-sp-800-86', '', 89, 'In some situations, collecting the necessary data might involve identifying all components of the application, deciding which were most likely to be of interest (based on the details of the situation and the need), finding the location of each component, and collecting data from those components.', 'kb-doc-04-nist-sp-800-86-p89-21', 0, 46, '04-nist-sp-800-86', 'retrieved', 'AC04177558E4DD2CB840A67049F800C64240A688B186AE0229616C71E40365DB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-22', 'doc-04-nist-sp-800-86', '', 89, 'Section 8 contains examples that illustrate the complexity of identifying components and prioritizing data collection for applications.', 'kb-doc-04-nist-sp-800-86-p89-22', 0, 17, '04-nist-sp-800-86', 'retrieved', 'F007C6611AC5D8C9C9E0668E7676C96F3282999EDA25A9925A30D8E3BAE6B94F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-23', 'doc-04-nist-sp-800-86', '', 89, '7.4 Examining and Analyzing Application Data Examining and analyzing application data largely consists of looking at specific portions of application datafilesystems, volatile OS data, and network trafficusing the tools and techniques described in Sections 4.3 and 4.4, 5.3, and 6.4, respectively.', 'kb-doc-04-nist-sp-800-86-p89-23', 0, 41, '04-nist-sp-800-86', 'retrieved', '65442A5F0136ED59D77100231195A6C939978276B4ACE5043C756C2F189D5547', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-24', 'doc-04-nist-sp-800-86', '', 89, 'Examination and analysis might be hindered if the application were custom, such as a program written by the user; the analyst is unlikely to have any knowledge of such an application.', 'kb-doc-04-nist-sp-800-86-p89-24', 0, 31, '04-nist-sp-800-86', 'retrieved', '772BD6D0A5FF9746D6B659782B736AD262734EFBDC02074E0C0F5F3367F8B550', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
