VALUES ('doc-04-nist-sp-800-86-p89-25', 'doc-04-nist-sp-800-86', '', 89, 'Another possible issue in examination involves use of application- based security controls, such as data encryption and passwords.', 'kb-doc-04-nist-sp-800-86-p89-25', 0, 18, '04-nist-sp-800-86', 'retrieved', '52750A946DD95F5C0FDDA38A77A5619A443C93BC1C808E926FB588904BB71C62', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
