INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p89-26', 'doc-04-nist-sp-800-86', '', 89, 'Many applications use such security controls to thwart unauthorized access to sensitive data by authorized users.', 'kb-doc-04-nist-sp-800-86-p89-26', 0, 16, '04-nist-sp-800-86', 'retrieved', '30CEE971E9725CA8FB85D4859B792F52B8D9AD2B45C53EC87BB275128638B560', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
