INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-1', 'doc-04-nist-sp-800-86', '', 90, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE In some cases, analysts bring together pertinent application data from several varied application data sources; this is largely a manual process.', 'kb-doc-04-nist-sp-800-86-p90-1', 0, 29, '04-nist-sp-800-86', 'retrieved', 'ABF33F9814CCC3FEB552E1AE8E44C0CF677AE09FC13E2F31A0FEC41E970957AF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
