INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-2', 'doc-04-nist-sp-800-86', '', 90, 'Detailed analysis of application-related events and event reconstruction usually require a skilled and knowledgeable analyst who understands the information presented by all the sources.', 'kb-doc-04-nist-sp-800-86-p90-2', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C63BEE95723AC249599D755BE279FDACF789CBCCD52BDA06131DEAEDEB1FE6A7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
