INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-3', 'doc-04-nist-sp-800-86', '', 90, 'The analyst can review the results of the examination and analysis of individual application data sources and see how the information fits together.', 'kb-doc-04-nist-sp-800-86-p90-3', 0, 23, '04-nist-sp-800-86', 'retrieved', 'D150BA4FB1C8D8934DB630095F5A48CB8FA0C93F922A617566549C172AF2990D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
