INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-4', 'doc-04-nist-sp-800-86', '', 90, 'Tools that may be helpful to analysts include security event management software (described in Section 6.2.5), which can correlate some application-related events among multiple data sources, and log analysis software (including some types of host-based intrusion detection software), which can be run against certain types of logs to identify suspicious activity.', 'kb-doc-04-nist-sp-800-86-p90-4', 0, 51, '04-nist-sp-800-86', 'retrieved', 'DAB691202417FD26016C1E608B3756A1F6B235B15AE90CDC6F80160EA616E352', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-5', 'doc-04-nist-sp-800-86', '', 90, 'Section 8 shows how data from multiple types of sources can be correlated through analysis to reach a more accurate and comprehensive view of what occurred.', 'kb-doc-04-nist-sp-800-86-p90-5', 0, 26, '04-nist-sp-800-86', 'retrieved', 'F7524C22E3EE98E45A9CB1CFB30CBF2C42F0029BC2C8A6732C5D9F5FB6777039', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
