INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-6', 'doc-04-nist-sp-800-86', '', 90, '7.5 Re commendations The key recommendations presented in this section for using data from applications are as follows: ! Analysts should consider all possible application data sources.', 'kb-doc-04-nist-sp-800-86-p90-6', 0, 27, '04-nist-sp-800-86', 'retrieved', '3E41F4C563550D4B83F6C66E6A77E40FC79E3AB98BCE1D32EBC5969D5693C770', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
