INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-8', 'doc-04-nist-sp-800-86', '', 90, 'In addition, applications might be used through multiple mechanisms, such as multiple client programs installed on a system and Web-based client interfaces.', 'kb-doc-04-nist-sp-800-86-p90-8', 0, 22, '04-nist-sp-800-86', 'retrieved', 'BF470E5B5F07D97A79143AFDB9A8B7BA84463010C212EC9525DB86EC5EDA0388', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
