INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-9', 'doc-04-nist-sp-800-86', '', 90, 'In such situations, analysts should identify all application components, decide which are most likely to be of interest, find the location of each component of interest, and collect the data.', 'kb-doc-04-nist-sp-800-86-p90-9', 0, 30, '04-nist-sp-800-86', 'retrieved', '7DAB44B791708ED86CA28E3F4CA8EEF45AFC4CBA215BF133FA3AA31C76A82465', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
