INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p90-11', 'doc-04-nist-sp-800-86', '', 90, 'The analyst should review the results of the examination and analysis of individual application data sources and determine how the information fits together, to perform a detailed analysis of application-related events and event reconstruction.', 'kb-doc-04-nist-sp-800-86-p90-11', 0, 34, '04-nist-sp-800-86', 'retrieved', 'BC5F79101C630B65AA73DC2D887530A11C82B2E1C25FE35206FF1D4F2DB60446', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
