VALUES ('doc-04-nist-sp-800-86-p91-1', 'doc-04-nist-sp-800-86', '', 91, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 8. Using Data from Multiple Sources Sections 4 through 6 describe the collection, examination, and analysis of data from three data source categories: data files, OSs, and network traffic.', 'kb-doc-04-nist-sp-800-86-p91-1', 0, 37, '04-nist-sp-800-86', 'retrieved', 'D6E9472A0F1227AF891D479326E8D1FB3E7313FF4DA1F86CAB63343F6CE46973', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
