INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-2', 'doc-04-nist-sp-800-86', '', 91, 'The techniques and processes for collecting, examining, and analyzing the data in these categories are fundamentally different.', 'kb-doc-04-nist-sp-800-86-p91-2', 0, 17, '04-nist-sp-800-86', 'retrieved', 'EC3B934A87F3085F27953DC047C917036C6094A93E00760BFC76EBC342FB9683', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
