VALUES ('doc-04-nist-sp-800-86-p91-3', 'doc-04-nist-sp-800-86', '', 91, 'Section 7 describes the collection, examination, and analysis of application data, which brings together the three data source categories.', 'kb-doc-04-nist-sp-800-86-p91-3', 0, 19, '04-nist-sp-800-86', 'retrieved', '63883EB0A0FDDF5A614C4D9813D25BA0B3A4A0CE46934B36B18A7ADDC155D9A6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
