VALUES ('doc-04-nist-sp-800-86-p91-4', 'doc-04-nist-sp-800-86', '', 91, 'For example, many applications use data files, alter the configuration of OSs, and generate network traffic.', 'kb-doc-04-nist-sp-800-86-p91-4', 0, 16, '04-nist-sp-800-86', 'retrieved', 'E4C64B8522165C035AAB05F24B5486BEDC574FE88F7FF6CBA7AA72B9A253D69E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
