VALUES ('doc-04-nist-sp-800-86-p91-5', 'doc-04-nist-sp-800-86', '', 91, 'Many situations, such as computer security incidents, can be handled most effectively by analyzing multiple types of data sources and correlating events across sources.', 'kb-doc-04-nist-sp-800-86-p91-5', 0, 24, '04-nist-sp-800-86', 'retrieved', '8821A2704BBA6F096CF801B086CFF42B097C1CB8D6CF872FF2FB14AE59D23C49', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
