VALUES ('doc-04-nist-sp-800-86-p91-6', 'doc-04-nist-sp-800-86', '', 91, 'This section of the guide presents two examples of the use of multiple data sources during digital forensics.', 'kb-doc-04-nist-sp-800-86-p91-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '91EA20F9E2654D0524F79995156EEE510B8188BE630B47D9847004931AEB10B1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
