VALUES ('doc-04-nist-sp-800-86-p91-7', 'doc-04-nist-sp-800-86', '', 91, 'Each example describes a scenario, indicates a specific need for forensic analysis, and presents an explanation of how the forensic process might be performed.', 'kb-doc-04-nist-sp-800-86-p91-7', 0, 24, '04-nist-sp-800-86', 'retrieved', '0EFA09CA0D604DC217CE48EC7D572A163A7BDF2A3758B9E015DFBF4149E3EDE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
