VALUES ('doc-04-nist-sp-800-86-p91-9', 'doc-04-nist-sp-800-86', '', 91, 'The examples presented in this section are as follows: ! Determining which worm has infected a system and identifying the worms characteristics ! Reconstructing the sequence of cyber events involving a threatening e-mail.', 'kb-doc-04-nist-sp-800-86-p91-9', 0, 33, '04-nist-sp-800-86', 'retrieved', 'E30EEB16C47903E26E6B8C5A111B13751F795C2C78C6E2F99D9D705F6486CCBC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
