INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-10', 'doc-04-nist-sp-800-86', '', 91, '8.1 Suspected Network Service Worm Infection An organizations help desk receives several calls in a short time from users complaining about a particular server providing slow responses.', 'kb-doc-04-nist-sp-800-86-p91-10', 0, 27, '04-nist-sp-800-86', 'retrieved', 'BD1F1A0ADBE7F4250F57EC8EA96134573514EE330CB9DEEBC65D4197F2FDF10E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-12', 'doc-04-nist-sp-800-86', '', 91, 'That groups network IDSs have recently reported several unusual alerts involving the server, and the analyst who reviewed the alerts believes that they may be accurate.', 'kb-doc-04-nist-sp-800-86-p91-12', 0, 26, '04-nist-sp-800-86', 'retrieved', '7A3C114C18D2C2DD49190CE16829476A6240904DD21BE6BC3C2D24757D5BB44D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-13', 'doc-04-nist-sp-800-86', '', 91, 'The data in the alerts indicates that some suspicious activity was directed at the server, and the server is now generating identical activity directed at other systems.', 'kb-doc-04-nist-sp-800-86-p91-13', 0, 27, '04-nist-sp-800-86', 'retrieved', 'DFBFB8BFB1F4461717525A79A931B7FE6A1B8A0208D34B6223F1C74F9F28812F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-14', 'doc-04-nist-sp-800-86', '', 91, 'The intrusion detection analysts initial hypothesis is that a worm may have attacked a vulnerable network service and infected the server, which is now attempting to infect other systems.', 'kb-doc-04-nist-sp-800-86-p91-14', 0, 29, '04-nist-sp-800-86', 'retrieved', '4BFE2C50F27254837F05ACE7288A807E0D4C797613CA028A1FC28A9BC7285D3D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-15', 'doc-04-nist-sp-800-86', '', 91, 'The monitoring group contacts the incident handler on duty to investigate the possible incident on the server.', 'kb-doc-04-nist-sp-800-86-p91-15', 0, 17, '04-nist-sp-800-86', 'retrieved', 'D362CBC82C964A8E27822B2D99C0A13F219E4F5FEDA44F125EA7F07B42C67C77', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
