INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-16', 'doc-04-nist-sp-800-86', '', 91, 'For the incident, this particular incident handlers role is to determine the type of worm that has infected the system and to identify the distinguishing characteristics of the worm.', 'kb-doc-04-nist-sp-800-86-p91-16', 0, 29, '04-nist-sp-800-86', 'retrieved', '544A9EFF76066A42857BBC64B352B92ADD13A33B7CE8931DB96E8081E197B261', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
