INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-17', 'doc-04-nist-sp-800-86', '', 91, 'This information is critical to the incident response teams ability to effectively perform containment, eradication, and recovery activities and to prevent other systems within the organization from becoming infected.', 'kb-doc-04-nist-sp-800-86-p91-17', 0, 29, '04-nist-sp-800-86', 'retrieved', '4BA5F06DC55B1FE0FD2A01C6262F69C83C5FE76F5DF61A89B5C714525B1F73E6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-18', 'doc-04-nist-sp-800-86', '', 91, 'If the incident handlers investigation shows that the incident was probably caused by something other than a worm, the characteristics the handler identifies should be very helpful in determining what actually occurred.', 'kb-doc-04-nist-sp-800-86-p91-18', 0, 32, '04-nist-sp-800-86', 'retrieved', '41C280EB25844A1E9D068E4F34A36E6CDD2D4BBA62FCFF8CE346218CC51BFE35', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-19', 'doc-04-nist-sp-800-86', '', 91, 'Information regarding this incident may be recorded in several different places.', 'kb-doc-04-nist-sp-800-86-p91-19', 0, 11, '04-nist-sp-800-86', 'retrieved', '75BEFA8D7FB9C4A4ECDDF6319B25A348BE2D6129C3F26FE80C63B8A01E034151', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-20', 'doc-04-nist-sp-800-86', '', 91, 'The incident handler should check the data sources that are most likely to have relevant information first, based on the handlers previous experience with the data sources and the initial information available regarding the incident.', 'kb-doc-04-nist-sp-800-86-p91-20', 0, 35, '04-nist-sp-800-86', 'retrieved', '3D633AFFD16E132D3EFB431BC2F128698889A392D8B054D223C8CDC935342855', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-21', 'doc-04-nist-sp-800-86', '', 91, 'For example, because network IDS sensors saw the suspicious activity, other network-based data sources monitoring the same network segment might also contain relevant information.', 'kb-doc-04-nist-sp-800-86-p91-21', 0, 24, '04-nist-sp-800-86', 'retrieved', '24F5FB7132ECDF1D96FEB2E74F97C68ABE7F046CCF9CA8273D3DDF7676EEE082', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-22', 'doc-04-nist-sp-800-86', '', 91, 'If the organization uses security event management or network forensic analysis tool software, which bring together data from many different sources, the incident handler may be able to gather all necessary information just by running a few queries from the SEM or NFAT console.', 'kb-doc-04-nist-sp-800-86-p91-22', 0, 44, '04-nist-sp-800-86', 'retrieved', '02D697C0EE3F58799E9ECEA00606067D3929825D548E3A607ED712D000B19C77', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-23', 'doc-04-nist-sp-800-86', '', 91, 'If a centralized source of data is not available, the handler should check individual potential sources of attack characteristics, such as the following: ! Network IDS.', 'kb-doc-04-nist-sp-800-86-p91-23', 0, 26, '04-nist-sp-800-86', 'retrieved', '5E242918ADACE47E10E2782B803620D8C0C36B08A61E92D1034032B5A0FD883C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p91-24', 'doc-04-nist-sp-800-86', '', 91, 'Because the initial reports of the incident were generated by network IDS sensors, it is very likely that the network IDS data contains information on the basic characteristics of the 8-1', 'kb-doc-04-nist-sp-800-86-p91-24', 0, 31, '04-nist-sp-800-86', 'retrieved', '268955235CCB4197628BF6BCF9963B37963C315F521F7A559B7BD475695441CB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-1', 'doc-04-nist-sp-800-86', '', 92, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE network activity.', 'kb-doc-04-nist-sp-800-86-p92-1', 0, 10, '04-nist-sp-800-86', 'retrieved', 'ADF210E28596779CD072E3A93EA324448892ABF3E81DA5F079BD7AAB351F846F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-2', 'doc-04-nist-sp-800-86', '', 92, 'At a minimum, the data should indicate which server was attacked and on what port number, which indicates which network service was targeted.', 'kb-doc-04-nist-sp-800-86-p92-2', 0, 23, '04-nist-sp-800-86', 'retrieved', '39BF33AC3DC81095B0873948D1A7EB3D4D8D3EAD3833D5DB3C199296B2454F51', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-3', 'doc-04-nist-sp-800-86', '', 92, 'Identifying the service is very important to finding the exploited vulnerability and developing a mitigation strategy to prevent similar incidents from occurring on other systems.', 'kb-doc-04-nist-sp-800-86-p92-3', 0, 25, '04-nist-sp-800-86', 'retrieved', '5BA2D7A5B3047B6A33B9D7B13C67E9C600B91B021C7E9C1C932CC4ED1DC0EEF8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-4', 'doc-04-nist-sp-800-86', '', 92, 'From an analysis standpoint, knowing the targeted service and port number is also important because the information can be used to identify other likely data sources and to query them for relevant information.', 'kb-doc-04-nist-sp-800-86-p92-4', 0, 33, '04-nist-sp-800-86', 'retrieved', 'AD13D43ADACE6050A736F9E8CA979438E229F2C99B89636E22880C6FA575B819', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-5', 'doc-04-nist-sp-800-86', '', 92, 'Some network IDS deployments may record additional useful information, such as application data (e.g., Web requests and responses, e-mail headers and file attachment names).', 'kb-doc-04-nist-sp-800-86-p92-5', 0, 24, '04-nist-sp-800-86', 'retrieved', 'D8CB6446C3EBF872D4DEABF5B0DC357F6F7FE9B3DB9235BFB582E753BF3CC020', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-6', 'doc-04-nist-sp-800-86', '', 92, 'The application data may contain words, phrases, or other character sequences that are associated with a particular worm.', 'kb-doc-04-nist-sp-800-86-p92-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '620874C1C6231583A9BDBC4974B4E94393DC8E730EB373B0A2FDF059290452AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-8', 'doc-04-nist-sp-800-86', '', 92, 'Firewalls are typically configured to log blocked connection attempts, including the intended destination IP address and port.', 'kb-doc-04-nist-sp-800-86-p92-8', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A27745E804164E6CCAF1773AB9E6D3D886301D5BBF7EAFC38492FD90940ECA41', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-10', 'doc-04-nist-sp-800-86', '', 92, 'Some worms attempt to exploit multiple services or service ports; firewall records might show that a worm has actually tried to establish connections to at least four different port numbers, but that the firewall blocked connections using three of the ports.', 'kb-doc-04-nist-sp-800-86-p92-10', 0, 41, '04-nist-sp-800-86', 'retrieved', '18026FB3D5C266884A3E077EAAFAFCE9967FC72E5250C22C811135FEB8EEA218', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-12', 'doc-04-nist-sp-800-86', '', 92, 'If firewalls are configured to record permitted connections, their logs may show which hosts within the organization have received worm traffic or been infected and generated their own worm traffic.', 'kb-doc-04-nist-sp-800-86-p92-12', 0, 30, '04-nist-sp-800-86', 'retrieved', '69F088C0606821926E16C1AE8A33DA9CE4E7E018799A5CE790FA2750377718FD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-13', 'doc-04-nist-sp-800-86', '', 92, 'This is particularly useful for situations in which network IDS sensors do not monitor all traffic that reaches the firewall.', 'kb-doc-04-nist-sp-800-86-p92-13', 0, 20, '04-nist-sp-800-86', 'retrieved', '8A4347E13F5FBE2E63AD086FB2729975295221871934681DD57EC013588C1949', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-14', 'doc-04-nist-sp-800-86', '', 92, 'Other perimeter devices that the worm traffic may have passed through, such as routers, VPN gateways, and remote access servers, may record information similar to that logged by network-based firewalls.', 'kb-doc-04-nist-sp-800-86-p92-14', 0, 30, '04-nist-sp-800-86', 'retrieved', 'B634CB48A57D7C7ACFCFAA8DCD46404F13D7DCDDEF807394B7FD5E6639196965', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-16', 'doc-04-nist-sp-800-86', '', 92, 'IDS and firewall products running on the infected system may contain more detailed information than network IDS and firewall products.', 'kb-doc-04-nist-sp-800-86-p92-16', 0, 20, '04-nist-sp-800-86', 'retrieved', '6E883CF0E5BF236A7BB61A9F62ED9206B4B052F599A73D18018CB40A540AEBBB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-17', 'doc-04-nist-sp-800-86', '', 92, 'For example, a host IDS can identify changes to files or configuration settings on the host that were performed by a worm.', 'kb-doc-04-nist-sp-800-86-p92-17', 0, 22, '04-nist-sp-800-86', 'retrieved', 'DFAAAFAD84106B6582B8CD612255D5C5C41660A3BB68BE795BBC8B301ED5F4B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-18', 'doc-04-nist-sp-800-86', '', 92, 'This information is helpful not only in planning containment, eradication, and recovery activities by determining how the worm has affected the host, but also in identifying which worm infected the system.', 'kb-doc-04-nist-sp-800-86-p92-18', 0, 31, '04-nist-sp-800-86', 'retrieved', 'E8334507BFB0EB981528F52741CCC337CB3E43EF16F7019CEFEA53A770AC4017', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-19', 'doc-04-nist-sp-800-86', '', 92, 'However, because many worms disable host-based security controls and destroy log entries, data from host IDS and firewall software may be limited or missing.', 'kb-doc-04-nist-sp-800-86-p92-19', 0, 24, '04-nist-sp-800-86', 'retrieved', '1C14A3F59DB24AFA636E1F3A91825C5ADEBAEDA4405F4D1CC69496D1432F1D38', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-20', 'doc-04-nist-sp-800-86', '', 92, 'If the software was configured to forward copies of its logs to centralized log servers, then queries to those servers may provide some information.', 'kb-doc-04-nist-sp-800-86-p92-20', 0, 24, '04-nist-sp-800-86', 'retrieved', '220D4EDE4A75351CA72B414A7B708544FB9DD8DF1A2596A8DF1266C599A7E3FE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-22', 'doc-04-nist-sp-800-86', '', 92, 'Because the threat reached the server and successfully breached it, it is unlikely that network or host-based antivirus software contains any record of the threat.', 'kb-doc-04-nist-sp-800-86-p92-22', 0, 25, '04-nist-sp-800-86', 'retrieved', '25E07CDD38CE588B9FEEF45A6C88841EE505907628F1FA15E4FC8F677F28FE1A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-24', 'doc-04-nist-sp-800-86', '', 92, 'However, it is possible that the antivirus software saw the worm but somehow failed to stop it, or that the antivirus software was updated since the infection with new signatures that can recognize the worm.', 'kb-doc-04-nist-sp-800-86-p92-24', 0, 35, '04-nist-sp-800-86', 'retrieved', 'E8A553B5B11E5A8D9B0987B07C99D9083387C3D6BF9BE0885CC42F6787E8196C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-25', 'doc-04-nist-sp-800-86', '', 92, 'The incident handler can also scan the server for worms using a current version of antivirus software from a forensic toolkit.', 'kb-doc-04-nist-sp-800-86-p92-25', 0, 21, '04-nist-sp-800-86', 'retrieved', 'A19EFF6AEECFE279D4BB2E956B9824E0F5437B145A295E1FF23B282F29BD847E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-27', 'doc-04-nist-sp-800-86', '', 92, 'If the worm used a common application protocol, such as HTTP or SMTP, information regarding it might be recorded in several places, such as application server logs, proxy servers, and application-specific security controls.', 'kb-doc-04-nist-sp-800-86-p92-27', 0, 33, '04-nist-sp-800-86', 'retrieved', 'CDC9E51F2BE5408893AADAF69BF5CE047F8E65B41943021CE12DC50E8B7091A9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-28', 'doc-04-nist-sp-800-86', '', 92, 'Less common application protocols probably have information only in the application server logs.', 'kb-doc-04-nist-sp-800-86-p92-28', 0, 13, '04-nist-sp-800-86', 'retrieved', 'A432829AEA8F1933C7EC104E1EA5A752CB2FFE14AA9BEF2239BD4C6690C0118B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-29', 'doc-04-nist-sp-800-86', '', 92, 'Application logs record extensive details on the application-specific characteristics of the activity, and are particularly helpful at identifying attack characteristics from less common applications.', 'kb-doc-04-nist-sp-800-86-p92-29', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C3CA7CFAC432EE1D715C4FAFF54536DBF0A68A3CB1FEAD1697D84591CF2BCF39', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-30', 'doc-04-nist-sp-800-86', '', 92, 'The goal in the initial information gathering effort is to identify enough characteristics for positive identification of the worm.', 'kb-doc-04-nist-sp-800-86-p92-30', 0, 19, '04-nist-sp-800-86', 'retrieved', '23C8A34032A7A451533CDE5E6AD18A8E0B0DF1B380EB00D53EF4D184F6EFDB71', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-31', 'doc-04-nist-sp-800-86', '', 92, 'This can be challenging, particularly for worms that have dozens of variants; these variants often have similar characteristics but have different effects on systems.', 'kb-doc-04-nist-sp-800-86-p92-31', 0, 24, '04-nist-sp-800-86', 'retrieved', 'F4D152534230748A0EBCB3C03B3A17EF81E91FF968C8F312A5CEA30CB3BA0721', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p92-32', 'doc-04-nist-sp-800-86', '', 92, 'Analysts can perform queries on antivirus vendors malware databases, searching for identified characteristics such as 8-2', 'kb-doc-04-nist-sp-800-86-p92-32', 0, 16, '04-nist-sp-800-86', 'retrieved', '0B0A34A90AC17D694DD9885670B52653E35B841BDBF158EF19762C2841E9F16F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-1', 'doc-04-nist-sp-800-86', '', 93, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE product name, service name or port number, text strings within the malware, and files or settings modified on the target.126 Virtually any instance of malware, other than the latest threats (e.g., released in the past several hours), is likely to be included in major malware databases.', 'kb-doc-04-nist-sp-800-86-p93-1', 0, 54, '04-nist-sp-800-86', 'retrieved', '38E6F54ED70A93D2AA50BA222A6F7E7F10D2619EAA42DFA1097CA45169C18EF1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-2', 'doc-04-nist-sp-800-86', '', 93, 'Each database entry typically contains extensive information on how the worm spreads, how it affects systems (e.g., what changes it makes), and how it can be eradicated, including measures concerning prevention of infections on other systems.', 'kb-doc-04-nist-sp-800-86-p93-2', 0, 36, '04-nist-sp-800-86', 'retrieved', '389C6A52F15202FAEBB081C3690DE4EAA1D25DC77CC9E2577CE141809015F2CB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-3', 'doc-04-nist-sp-800-86', '', 93, 'If a search of malware databases does not lead to identification of the worm, then the incident handler may need to perform additional research and analysis to discover the information usually provided by malware database entries.', 'kb-doc-04-nist-sp-800-86-p93-3', 0, 36, '04-nist-sp-800-86', 'retrieved', 'E7A9B9BCC1C34A598C8F3D9947D4B8FD139096847F0EEB6D9A8693F97934FDFB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-4', 'doc-04-nist-sp-800-86', '', 93, 'Although the organization can send a copy of the worm to the organizations antivirus vendor for analysis and identification, the organization should perform its own analysis in the meantime, since the time frame for the vendors response is unknown.', 'kb-doc-04-nist-sp-800-86-p93-4', 0, 39, '04-nist-sp-800-86', 'retrieved', 'CC5C3E3F4E5D6BCA657BC6E80E36085009CE6128F0592DDFE6A0137AD4274544', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-5', 'doc-04-nist-sp-800-86', '', 93, 'To gather more information, the analyst can examine the infection through the following methods: ! Current State of the Host.', 'kb-doc-04-nist-sp-800-86-p93-5', 0, 20, '04-nist-sp-800-86', 'retrieved', 'CFE942C801575B4DFC6E383CDC344B133482473E666747A66EBC1D84D84D35C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-6', 'doc-04-nist-sp-800-86', '', 93, 'The analyst can examine the host to look at several aspects of its current state.', 'kb-doc-04-nist-sp-800-86-p93-6', 0, 15, '04-nist-sp-800-86', 'retrieved', '9FDB216C1814C6C35BD8648F1CDC38F6D6BB71F813ACD9027C6AD846E3C12CC0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-7', 'doc-04-nist-sp-800-86', '', 93, 'In this case, it is probably most effective to examine the network connections listing to identify unusual connections (e.g., large number, unexpected port number usage, unexpected hosts) and unexpected listening ports (e.g., backdoors created by the worm).', 'kb-doc-04-nist-sp-800-86-p93-7', 0, 37, '04-nist-sp-800-86', 'retrieved', '8521F9A9C906559E8BF88C7A57FCACF43ED1CB7C4A91FD53B7EA2699F533E99D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-8', 'doc-04-nist-sp-800-86', '', 93, 'Other steps that may be useful include identifying unknown processes in the running processes list and examining the hosts logs to reveal any unusual entries that may be related to the infection.', 'kb-doc-04-nist-sp-800-86-p93-8', 0, 32, '04-nist-sp-800-86', 'retrieved', '60BB19E002C598954AD79E8D85964ED08173394C12448366B5C4DE6B82BAE08B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-10', 'doc-04-nist-sp-800-86', '', 93, 'The analyst can collect worm traffic being generated by the infected server through a packet sniffer and protocol analyzer.', 'kb-doc-04-nist-sp-800-86-p93-10', 0, 19, '04-nist-sp-800-86', 'retrieved', '18186729FF3CB101843E7BB7CF16197E160CA012D5AF515B4252DA2642BCCE2F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-11', 'doc-04-nist-sp-800-86', '', 93, 'This may provide enough additional information regarding the characteristics of the worm to enable the analyst to locate it in major malware databases.', 'kb-doc-04-nist-sp-800-86-p93-11', 0, 23, '04-nist-sp-800-86', 'retrieved', 'D2470E0A6DAD515E7A5C4B09F9608073C75C87F5C75AD39444B965540EF4AA25', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-12', 'doc-04-nist-sp-800-86', '', 93, 'Worm incidents often necessitate as rapid a response as possible, because an infected system may be attacking other systems inside and outside the organization.', 'kb-doc-04-nist-sp-800-86-p93-12', 0, 24, '04-nist-sp-800-86', 'retrieved', 'F24DE7FCB1376B92971276F791880A1FA1FC601C2151B2385580A5320A7C918F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-13', 'doc-04-nist-sp-800-86', '', 93, 'In addition, worms often install backdoors and other tools on systems that permit attackers to gain remote access to infected systems, which can create additional damage.', 'kb-doc-04-nist-sp-800-86-p93-13', 0, 26, '04-nist-sp-800-86', 'retrieved', '518FFC36944FC019F8BCFB07461FE4765DB9E9D8C0A58D9EC681B825D2C26073', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-14', 'doc-04-nist-sp-800-86', '', 93, 'Accordingly, organizations may choose to disconnect infected systems from networks immediately, instead of performing data collection for the host first.', 'kb-doc-04-nist-sp-800-86-p93-14', 0, 20, '04-nist-sp-800-86', 'retrieved', 'E00F46428742E8E2AAE72D3233C360428B6B97C57D66912233024C73A03F0365', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-15', 'doc-04-nist-sp-800-86', '', 93, 'This step may make it considerably more difficult for analysts to identify a worm and to determine its effects on systemsfor example, if systems are disconnected from the network, network activity and certain aspects of the host state will not be available.', 'kb-doc-04-nist-sp-800-86-p93-15', 0, 42, '04-nist-sp-800-86', 'retrieved', '6183FD3F7060390D68F9961D4EC30B24457B567F04968CDD18843981DB588C48', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-16', 'doc-04-nist-sp-800-86', '', 93, 'In such cases, the analyst may need to perform a more detailed forensic analysis of the server, such as collecting its filesystems and examining them for signs of malicious activity (e.g., altered system executables) to determine exactly what happened to the server.', 'kb-doc-04-nist-sp-800-86-p93-16', 0, 42, '04-nist-sp-800-86', 'retrieved', '4BDEF3E9DD9582170E405B4C415DCC54E0B25AC6F9AD6090BA5DA1EEEE46D80E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-17', 'doc-04-nist-sp-800-86', '', 93, 'The analyst can also examine non-volatile characteristics of the servers OS, such as looking for administrative-level user accounts and groups that may have been added by the worm.', 'kb-doc-04-nist-sp-800-86-p93-17', 0, 28, '04-nist-sp-800-86', 'retrieved', '1F8ACA9982DFCEB303CF7063905906B0EC4AD66B60FAA0929BB715B339934EE7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-18', 'doc-04-nist-sp-800-86', '', 93, 'Ultimately, the analyst should gather enough information to identify the worms behavior in sufficient detail to enable the incident response team to act effectively to contain, eradicate, and recover from the incident.', 'kb-doc-04-nist-sp-800-86-p93-18', 0, 32, '04-nist-sp-800-86', 'retrieved', '79CE96A18F04CF5E2E92C7BAC113FBC95314A502FBF72085ECB2DAE23CAA6E30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
