VALUES ('doc-04-nist-sp-800-86-p93-20', 'doc-04-nist-sp-800-86', '', 93, 'An employee has been accused of sending a threatening e-mail to another employee through the organizations e-mail system.', 'kb-doc-04-nist-sp-800-86-p93-20', 0, 18, '04-nist-sp-800-86', 'retrieved', 'BA9BA8E6A0A0D3DAD687824FBE4C53D41E4BF0E110F0368BC4527C26890214D8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
