VALUES ('doc-04-nist-sp-800-86-p93-21', 'doc-04-nist-sp-800-86', '', 93, 'The incident handler has been asked to help investigators find all data sources that may contain', 'kb-doc-04-nist-sp-800-86-p93-21', 0, 16, '04-nist-sp-800-86', 'retrieved', '10584C930234D540BAE9A29CCDE8E665C3AD852898D2B0CF6C70E6A072DE578E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
