INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p93-22', 'doc-04-nist-sp-800-86', '', 93, '126 Malware databases are maintained by several vendors, including Computer Associates (http://www3.ca.com/securityadvisor/virusinfo/default.aspx), F-Secure (http://www.f-secure.com/virus-info/), Network Associates (http://vil.nai.com/vil/default.aspx), Sophos (http://www.sophos.com/virusinfo/analyses/), Symantec (http://securityresponse.symantec.com/avcenter/vinfodb.html), and Trend Micro (http://www.trendmicro.com/vinfo/virusencyclo/).', 'kb-doc-04-nist-sp-800-86-p93-22', 0, 25, '04-nist-sp-800-86', 'retrieved', '5734AC90ED22C601DE44D65C34449F6296F8E029F0546B904413BD7948BC1899', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
