VALUES ('doc-04-nist-sp-800-86-p94-1', 'doc-04-nist-sp-800-86', '', 94, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE records of the e-mail.', 'kb-doc-04-nist-sp-800-86-p94-1', 0, 12, '04-nist-sp-800-86', 'retrieved', 'B36340F99CF4A6E261356525DEEC54B4A43941030A7F93A99D18B1BDE43DD7B8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-2', 'doc-04-nist-sp-800-86', '', 94, 'This information will be helpful to investigators in determining who sent the e- mail.', 'kb-doc-04-nist-sp-800-86-p94-2', 0, 14, '04-nist-sp-800-86', 'retrieved', 'DCE2BF574692AFA4EC2FD38C3A3885B8D060566BF5E34B06C723EE69148EC7B7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-3', 'doc-04-nist-sp-800-86', '', 94, 'Because e-mail can be forged easily, it is important to use all available data sources to reconstruct the sequence of events for creating, sending, and receiving the e-mail.', 'kb-doc-04-nist-sp-800-86-p94-3', 0, 28, '04-nist-sp-800-86', 'retrieved', 'F95ADDB819289F5B3774D3CFB4B3454C15CDA98A668729438505BC10B946E624', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-4', 'doc-04-nist-sp-800-86', '', 94, 'Also, the incident handler needs to perform all work using forensically sound tools, techniques, and procedures, and to document all actions performed.', 'kb-doc-04-nist-sp-800-86-p94-4', 0, 22, '04-nist-sp-800-86', 'retrieved', 'A77CFB8BACF09259826C5936A9CF95839546E53C9D73205774ACC4BDED9A95F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-5', 'doc-04-nist-sp-800-86', '', 94, 'The threatening e-mail is key to the investigation, and its header contains the most important information to the incident handler.', 'kb-doc-04-nist-sp-800-86-p94-5', 0, 20, '04-nist-sp-800-86', 'retrieved', 'C2107625A79DEBD64669FF0915BFECF8BA97A6DAECB2C070CEF31D135CAC8A49', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-6', 'doc-04-nist-sp-800-86', '', 94, 'It should contain the domain name and the IP address of the host that sent the e- mail, the type of e-mail client used to send the e-mail, the e-mails message ID, and the date and time the e-mail was sent.', 'kb-doc-04-nist-sp-800-86-p94-6', 0, 41, '04-nist-sp-800-86', 'retrieved', '4F22C5BBEC37374FA13DB24799ABABF02ED4FFBCA0BC89EBE56B3C1337BB846C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-7', 'doc-04-nist-sp-800-86', '', 94, 'The e-mail header should also list each e-mail server (domain name and IP address) that the message passed through and the date and time each server processed the e-mail.127 Because the e-mail was supposedly sent using the organizations e-mail system, the e-mail header should only list systems within the organization.', 'kb-doc-04-nist-sp-800-86-p94-7', 0, 50, '04-nist-sp-800-86', 'retrieved', '879D4285861F1C7B2DE6CAC036ABB384CFA16EC07AA0A9DE55204A2C111C41FC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-8', 'doc-04-nist-sp-800-86', '', 94, 'Assuming that this is the case, the incident handler can check each system on the list for correlating information.', 'kb-doc-04-nist-sp-800-86-p94-8', 0, 19, '04-nist-sp-800-86', 'retrieved', 'FBE0310095CC83C24049F2EBC99CA99C1E671A81444463A7AA159D6EBC2124DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-9', 'doc-04-nist-sp-800-86', '', 94, 'Because of the importance of the threatening e-mail, the incident handler should focus first on collecting a copy of the e-mail, including its header.', 'kb-doc-04-nist-sp-800-86-p94-9', 0, 24, '04-nist-sp-800-86', 'retrieved', '320E777133A6DA599707286BBF38EA4FFC050B0AA1A013663FC9E7795DF71A8B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-10', 'doc-04-nist-sp-800-86', '', 94, 'Depending on the type of e-mail client used by the recipient and its configuration, the e-mail may have been downloaded to the recipients workstation, or it may remain on the e-mail server.', 'kb-doc-04-nist-sp-800-86-p94-10', 0, 32, '04-nist-sp-800-86', 'retrieved', 'C621FAD33F259FB5536FE047CF3003B70850627118306FD5BFB82E1751CFA921', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-12', 'doc-04-nist-sp-800-86', '', 94, 'The incident handler should collect copies of the e-mail from multiple sources, if possible, to confirm that the content of the e-mail has been unchanged in transit or by the recipient.', 'kb-doc-04-nist-sp-800-86-p94-12', 0, 31, '04-nist-sp-800-86', 'retrieved', '62DC648894E8C84F40078C216EAE831E090415D22ECE054A470FABF84AAEBB92', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-13', 'doc-04-nist-sp-800-86', '', 94, 'After reviewing the header, the incident handler should next gather more information about the sending of the e-mail.', 'kb-doc-04-nist-sp-800-86-p94-13', 0, 18, '04-nist-sp-800-86', 'retrieved', 'AC2FF4CDA2E122F5E342AECF4BC5F7C50DD0D0F8747419245CEC4EE3B594BC24', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-14', 'doc-04-nist-sp-800-86', '', 94, 'The header should list the IP address and the e-mail client used by the sender; the incident handler should determine which host was using that IP address at the time the e-mail was sent.', 'kb-doc-04-nist-sp-800-86-p94-14', 0, 34, '04-nist-sp-800-86', 'retrieved', 'E260D072E4169C1546F1818453417CF19BBEC0A0A0F5E9A6C6ABF93FC893FB0A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-16', 'doc-04-nist-sp-800-86', '', 94, 'In this case, the incident handler should be able to use network records, such as DHCP logs, to identify the desktop, laptop, PDA, or other device used to send the e-mail.', 'kb-doc-04-nist-sp-800-86-p94-16', 0, 31, '04-nist-sp-800-86', 'retrieved', '1895006FE9F98513220B4D8C5E30B59DE809926270110E8EAFB398FA3CFA3472', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-17', 'doc-04-nist-sp-800-86', '', 94, 'The incident handler can then create images of the identified device and examine an image copy to look for malware and for records related to the e-mail.', 'kb-doc-04-nist-sp-800-86-p94-17', 0, 27, '04-nist-sp-800-86', 'retrieved', 'E90275024D1D695A227BE1E9E7DE44DAEDB9B877ED74CE6A59301D55502610B8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-18', 'doc-04-nist-sp-800-86', '', 94, 'For example, the e-mail client might be configured to keep a copy of each e-mail that it sends, or the user might have saved drafts of the e-mail message.', 'kb-doc-04-nist-sp-800-86-p94-18', 0, 29, '04-nist-sp-800-86', 'retrieved', '4F82467F9E23081ABD7304DDDB9620E55D1D2A282059CB34DC5B882BA0CCFC02', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-19', 'doc-04-nist-sp-800-86', '', 94, 'If the message cannot be found intact on the system, collecting data from the devices memory and filesystems, including deleted and temporary files, might lead to the identification of fragments of the e-mail.', 'kb-doc-04-nist-sp-800-86-p94-19', 0, 33, '04-nist-sp-800-86', 'retrieved', 'D26DD81E1F24A57A9B3BCD1D24853EEAA55D0136133EA5B67EB0B97A0DE73C32', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-20', 'doc-04-nist-sp-800-86', '', 94, 'In addition, security controls on the device, such as spam filtering and antivirus software, might have scanned the outgoing e-mail and logged a record of it.', 'kb-doc-04-nist-sp-800-86-p94-20', 0, 26, '04-nist-sp-800-86', 'retrieved', 'EB13B2E4643013A57BB33EC69C376C27C5EF0083B79ADAEE5D5D6FAE7C784801', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-21', 'doc-04-nist-sp-800-86', '', 94, 'It is also possible, but unlikely, that a copy of the e-mail is stored on an e-mail server.', 'kb-doc-04-nist-sp-800-86-p94-21', 0, 18, '04-nist-sp-800-86', 'retrieved', '125719D05CEF265A62ABB09C22F7C83C28B17C6939F7F7B757B08F66D0360EA5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-22', 'doc-04-nist-sp-800-86', '', 94, 'In addition to looking for records of the e-mail on the local host, the incident handler should analyze the authentication records on the host to determine which user account was in use when the e-mail was sent.', 'kb-doc-04-nist-sp-800-86-p94-22', 0, 37, '04-nist-sp-800-86', 'retrieved', '670F8CFBA9DF588D4FDA5BFDBC0DA903EC5BA35543831C58DA4BF5DA2BE04510', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-24', 'doc-04-nist-sp-800-86', '', 94, 'If the organization offers a server-based client, such as a Web- based e-mail interface, then the IP address may correspond to that server.', 'kb-doc-04-nist-sp-800-86-p94-24', 0, 23, '04-nist-sp-800-86', 'retrieved', '0F4D483BED9ED681A0F3B257E2CBC8BB2520F79A1140FC39D6EA3F09E689CFB9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-25', 'doc-04-nist-sp-800-86', '', 94, 'Typically, the use of such a server requires users to authenticate themselves, so there may be authentication records that indicate when the alleged sender logged on to the server and what IP address the users system was using.', 'kb-doc-04-nist-sp-800-86-p94-25', 0, 38, '04-nist-sp-800-86', 'retrieved', '3082A20FEEEE6E21635595FD9166C9FE91CA5D954122A9C3E1A04C34BC5451B7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-26', 'doc-04-nist-sp-800-86', '', 94, 'The incident handler can then determine which system was assigned that IP address at the time, perform bit stream imaging for the identified system, and examine a copy of', 'kb-doc-04-nist-sp-800-86-p94-26', 0, 29, '04-nist-sp-800-86', 'retrieved', 'DE81A82ED5CEACF27F8B9575EEC9B2FBFF06AF319B07ABEEBB27FE22CE21B3C0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-27', 'doc-04-nist-sp-800-86', '', 94, '127 Within the e-mail header, these records are stored in reverse order, so the most recent record occurs first and the least recent record occurs last.', 'kb-doc-04-nist-sp-800-86-p94-27', 0, 26, '04-nist-sp-800-86', 'retrieved', '33B1CCAB5E012507F3DED9628ECFB779CE95DAFC25D2A5351F1F9DB4A7455A97', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p94-28', 'doc-04-nist-sp-800-86', '', 94, 'If an e-mail has been forged, the false records are the least recent, so they should appear last in the header.', 'kb-doc-04-nist-sp-800-86-p94-28', 0, 21, '04-nist-sp-800-86', 'retrieved', 'CDC3F57C4620C27D8F7656E7C74A68C36D20F7CC22E5AF6E8E58E0DFE6FFF610', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-1', 'doc-04-nist-sp-800-86', '', 95, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the image for the malware and the e-mail.', 'kb-doc-04-nist-sp-800-86-p95-1', 0, 16, '04-nist-sp-800-86', 'retrieved', 'B6FB0B53454F1E10BD14A3395C1728A6E6B5182C65A120AC38F7BA4770404A7A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-2', 'doc-04-nist-sp-800-86', '', 95, 'For example, temporary files from the Web browser may contain a copy of the e-mails contents.', 'kb-doc-04-nist-sp-800-86-p95-2', 0, 16, '04-nist-sp-800-86', 'retrieved', '463ED75CA9F895A4B60B710B14DF0F584C7AB17F9ED2917F0FE090E98F058FC8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-4', 'doc-04-nist-sp-800-86', '', 95, 'If the IP address was fabricatedfor example, if it is not a valid address within the organizations networksthe incident handler should rely on other data sources to identify the host that actually sent the e-mail message.', 'kb-doc-04-nist-sp-800-86-p95-4', 0, 36, '04-nist-sp-800-86', 'retrieved', '3810EC523EA2EAE8AECD40F55D34B0425C143F7592B131CB367A945A66E2B8DC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-6', 'doc-04-nist-sp-800-86', '', 95, 'Each of the server IP addresses listed in the e-mail header should contain some record of the e-mail, including the message ID value, which should facilitate quick identification of pertinent records.', 'kb-doc-04-nist-sp-800-86-p95-6', 0, 31, '04-nist-sp-800-86', 'retrieved', 'A3D979084EC1BF6F1E00C1AC341F3C358F9DCF9529D7B7896B31AC1C9D1693B9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-7', 'doc-04-nist-sp-800-86', '', 95, 'As mentioned previously, the final e-mail server in the list may contain a copy of the e-mail.', 'kb-doc-04-nist-sp-800-86-p95-7', 0, 17, '04-nist-sp-800-86', 'retrieved', '5737F25DC6510ACD65DD683CD5E94CBF5F563BEE9B3AD98F805654A6F813AE1B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-8', 'doc-04-nist-sp-800-86', '', 95, 'Backups of that server may contain a copy of the e-mail, but only if it was held there for delivery for several hours or more.', 'kb-doc-04-nist-sp-800-86-p95-8', 0, 25, '04-nist-sp-800-86', 'retrieved', '3CD93358807887240E0CBCF3454A1495DB6F86FA8C9609B3161781BAE584D60B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-9', 'doc-04-nist-sp-800-86', '', 95, 'Other services associated with e-mail, such as antivirus software and spam filters, may also contain basic records of e-mail activity, but are unlikely to contain many details.', 'kb-doc-04-nist-sp-800-86-p95-9', 0, 27, '04-nist-sp-800-86', 'retrieved', 'F90DE1A4F27DDBDFD8799C91BFD42CCC49D26CCB8BE70B30457FA169B2C5525F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-11', 'doc-04-nist-sp-800-86', '', 95, 'Although few e-mail servers require users to authenticate to send e-mail, they typically do require authentication to deliver e-mail to users.', 'kb-doc-04-nist-sp-800-86-p95-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '4617EB5138DB084186BDB198BCD09DA354437A9B73074688CC47820F8029683A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-12', 'doc-04-nist-sp-800-86', '', 95, 'Because users often send and receive e-mail during a single session, authentication logs may contain records for receiving e-mail that can be helpful in determining who may have sent a particular e-mail.', 'kb-doc-04-nist-sp-800-86-p95-12', 0, 32, '04-nist-sp-800-86', 'retrieved', '26A1ED4B0FF65364F736823EF7B1DE086F74B10EA2E9D38F2E9CC8F70A78DC1C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-13', 'doc-04-nist-sp-800-86', '', 95, 'Another possible source of information is a record of the network traffic generated by sending or receiving the e-mail.', 'kb-doc-04-nist-sp-800-86-p95-13', 0, 19, '04-nist-sp-800-86', 'retrieved', '0AEF58E560BE6FF2455034A46D16B8C8C5D32D3F9223ECB888283C5CEE6F0631', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-14', 'doc-04-nist-sp-800-86', '', 95, 'Packet sniffers or network forensic analysis tools that were monitoring network activity might have captured the activity, including the actual IP addresses of the sending or receiving hosts, the contents and header of the e-mail, and any associated authentication activity.', 'kb-doc-04-nist-sp-800-86-p95-14', 0, 40, '04-nist-sp-800-86', 'retrieved', 'DAE6F76DAE61543701E881669E272BA8EC89968BD54DE7238F850AC2C3BD59AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-15', 'doc-04-nist-sp-800-86', '', 95, 'Ultimately, the incident handler should identify the hosts that were used to send and receive the e-mail, as well as all intermediate hosts that transferred the e-mail from sender to receiver.', 'kb-doc-04-nist-sp-800-86-p95-15', 0, 31, '04-nist-sp-800-86', 'retrieved', 'EE0068F22CDB7DE234E9D7A6211F70D628FE3F3841378BE9ED3F3A7D3F9C7B7C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-16', 'doc-04-nist-sp-800-86', '', 95, 'The incident handler should collect copies of the e-mail and supporting information from each relevant host and, using the timestamps in records, should re-create the sequence of events from a cyber perspective.', 'kb-doc-04-nist-sp-800-86-p95-16', 0, 32, '04-nist-sp-800-86', 'retrieved', '7EED0BC6FD9D032AD98404EEE4D8AB25A285C269D6213E169F6FA038989F9C7D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-17', 'doc-04-nist-sp-800-86', '', 95, 'For example, a possible sequence might be as follows: A user logged on to a particular desktop computer at 8:37 a.m.', 'kb-doc-04-nist-sp-800-86-p95-17', 0, 21, '04-nist-sp-800-86', 'retrieved', '6352BDB6AAD6E1245DFEBC21D3241B338CA60ABD9B6716F453F1B87908C0A8E8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-18', 'doc-04-nist-sp-800-86', '', 95, 'At 10:02 a.m., the threatening e-mail was sent from that computer using its built-in e-mail client.', 'kb-doc-04-nist-sp-800-86-p95-18', 0, 16, '04-nist-sp-800-86', 'retrieved', '707D75C1BC8884E93BA09696C638D151D2E6CB41FCE1C208BC013955BEAEFE22', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-19', 'doc-04-nist-sp-800-86', '', 95, 'The e- mail passed through three of the organizations e-mail servers and was stored on Server 4 to await retrieval by the intended recipient.', 'kb-doc-04-nist-sp-800-86-p95-19', 0, 24, '04-nist-sp-800-86', 'retrieved', '8BCF6AE4B74E99C703AA79F6042183D1490757D8A173F796EE492023ECE73DEF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-20', 'doc-04-nist-sp-800-86', '', 95, 'The recipient user logged onto a particular laptop computer at 11:20 a.m. and downloaded e-mail, including the threatening e-mail, at 11:23 a.m.', 'kb-doc-04-nist-sp-800-86-p95-20', 0, 22, '04-nist-sp-800-86', 'retrieved', '1B213B26B1C3793AAA9534075A0334C2AB044B0EE9ADB093794485C691E5993A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-21', 'doc-04-nist-sp-800-86', '', 95, 'The contents of the e-mail on the recipients computer, as well as user-provided header fields (e.g., From, To, Subject), were identical to a copy saved in the Sent folder on the first users desktop computer.', 'kb-doc-04-nist-sp-800-86-p95-21', 0, 35, '04-nist-sp-800-86', 'retrieved', 'F51F3BB7AB3DE03372C4433205558D7FDBF62B7545E736B3454B77F06E14EA73', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-22', 'doc-04-nist-sp-800-86', '', 95, 'This information can be used as a basis for further investigation; although it documents cyber activities, it does not tell the whole story.', 'kb-doc-04-nist-sp-800-86-p95-22', 0, 23, '04-nist-sp-800-86', 'retrieved', '71F768A419461C3527E1A5A58241B41B9649C83E983723B95B579195E4552D87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p95-23', 'doc-04-nist-sp-800-86', '', 95, 'For example, it cannot determine which person actually sent the e-mail from the desktop computer, only which user account was in use at the time.', 'kb-doc-04-nist-sp-800-86-p95-23', 0, 25, '04-nist-sp-800-86', 'retrieved', '82D8687372C6D1420D1D1EB8FB49905212F64D71A3ACA4373C026D049D302492', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
